/**
 * Event Projections for Read Models (ADR-007)
 *
 * Build read models from domain events using projections.
 * Projections listen to events and maintain queryable state.
 *
 * Implemented Projections:
 * - AgentStateProjection - Current state of all agents
 * - TaskHistoryProjection - Complete task execution history
 * - MemoryIndexProjection - Memory access patterns and index
 *
 * @module v3/shared/events/projections
 */

import { EventEmitter } from 'node:events';
import { DomainEvent } from './domain-events.js';
import { EventStore } from './event-store.js';
import { AgentId, TaskId, AgentStatus, TaskStatus } from '../types.js';

// =============================================================================
// Projection Base Class
// =============================================================================

export abstract class Projection extends EventEmitter {
  protected initialized: boolean = false;

  constructor(protected eventStore: EventStore) {
    super();
  }

  /**
   * Initialize the projection by replaying events
   */
  async initialize(): Promise<void> {
    if (this.initialized) return;

    // Replay all events to build current state
    for await (const event of this.eventStore.replay()) {
      await this.handle(event);
    }

    this.initialized = true;
    this.emit('initialized');
  }

  /**
   * Handle a domain event
   */
  abstract handle(event: DomainEvent): Promise<void>;

  /**
   * Reset the projection state
   */
  abstract reset(): void;
}

// =============================================================================
// Agent State Projection
// =============================================================================

export interface AgentProjectionState {
  id: AgentId;
  role: string;
  domain: string;
  status: AgentStatus;
  currentTask: TaskId | null;
  completedTasks: TaskId[];
  failedTasks: TaskId[];
  totalTaskDuration: number;
  taskCount: number;
  errorCount: number;
  spawnedAt: number;
  startedAt: number | null;
  stoppedAt: number | null;
  lastActivityAt: number;
}

export class AgentStateProjection extends Projection {
  private agents: Map<AgentId, AgentProjectionState> = new Map();

  /**
   * Get state for a specific agent
   */
  getAgent(agentId: AgentId): AgentProjectionState | null {
    return this.agents.get(agentId) || null;
  }

  /**
   * Get all agents
   */
  getAllAgents(): AgentProjectionState[] {
    return Array.from(this.agents.values());
  }

  /**
   * Get agents by status
   */
  getAgentsByStatus(status: AgentStatus): AgentProjectionState[] {
    return this.getAllAgents().filter((agent) => agent.status === status);
  }

  /**
   * Get agents by domain
   */
  getAgentsByDomain(domain: string): AgentProjectionState[] {
    return this.getAllAgents().filter((agent) => agent.domain === domain);
  }

  /**
   * Get active agent count
   */
  getActiveAgentCount(): number {
    return this.getAgentsByStatus('active').length;
  }

  async handle(event: DomainEvent): Promise<void> {
    switch (event.type) {
      case 'agent:spawned':
        this.handleAgentSpawned(event);
        break;
      case 'agent:started':
        this.handleAgentStarted(event);
        break;
      case 'agent:stopped':
        this.handleAgentStopped(event);
        break;
      case 'agent:failed':
        this.handleAgentFailed(event);
        break;
      case 'agent:status-changed':
        this.handleAgentStatusChanged(event);
        break;
      case 'agent:task-assigned':
        this.handleAgentTaskAssigned(event);
        break;
      case 'agent:task-completed':
        this.handleAgentTaskCompleted(event);
        break;
    }
  }

  reset(): void {
    this.agents.clear();
    this.emit('reset');
  }

  private handleAgentSpawned(event: DomainEvent): void {
    const { agentId, role, domain } = event.payload;

    this.agents.set(agentId as AgentId, {
      id: agentId as AgentId,
      role: role as string,
      domain: domain as string,
      status: 'idle',
      currentTask: null,
      completedTasks: [],
      failedTasks: [],
      totalTaskDuration: 0,
      taskCount: 0,
      errorCount: 0,
      spawnedAt: event.timestamp,
      startedAt: null,
      stoppedAt: null,
      lastActivityAt: event.timestamp,
    });

    this.emit('agent:spawned', { agentId });
  }

  private handleAgentStarted(event: DomainEvent): void {
    const { agentId } = event.payload;
    const agent = this.agents.get(agentId as AgentId);

    if (agent) {
      agent.status = 'active';
      agent.startedAt = event.timestamp;
      agent.lastActivityAt = event.timestamp;
      this.emit('agent:started', { agentId });
    }
  }

  private handleAgentStopped(event: DomainEvent): void {
    const { agentId } = event.payload;
    const agent = this.agents.get(agentId as AgentId);

    if (agent) {
      agent.status = 'completed';
      agent.stoppedAt = event.timestamp;
      agent.lastActivityAt = event.timestamp;
      this.emit('agent:stopped', { agentId });
    }
  }

  private handleAgentFailed(event: DomainEvent): void {
    const { agentId } = event.payload;
    const agent = this.agents.get(agentId as AgentId);

    if (agent) {
      agent.status = 'error';
      agent.errorCount++;
      agent.lastActivityAt = event.timestamp;
      this.emit('agent:failed', { agentId });
    }
  }

  private handleAgentStatusChanged(event: DomainEvent): void {
    const { agentId, newStatus } = event.payload;
    const agent = this.agents.get(agentId as AgentId);

    if (agent) {
      agent.status = newStatus as AgentStatus;
      agent.lastActivityAt = event.timestamp;
      this.emit('agent:status-changed', { agentId, status: newStatus });
    }
  }

  private handleAgentTaskAssigned(event: DomainEvent): void {
    const { agentId, taskId } = event.payload;
    const agent = this.agents.get(agentId as AgentId);

    if (agent) {
      agent.currentTask = taskId as TaskId;
      agent.status = 'active';
      agent.lastActivityAt = event.timestamp;
      this.emit('agent:task-assigned', { agentId, taskId });
    }
  }

  private handleAgentTaskCompleted(event: DomainEvent): void {
    const { agentId, taskId, duration } = event.payload;
    const agent = this.agents.get(agentId as AgentId);

    if (agent) {
      agent.completedTasks.push(taskId as TaskId);
      agent.currentTask = null;
      agent.taskCount++;
      agent.totalTaskDuration += (duration as number) || 0;
      agent.status = 'idle';
      agent.lastActivityAt = event.timestamp;
      this.emit('agent:task-completed', { agentId, taskId });
    }
  }
}

// =============================================================================
// Task History Projection
// =============================================================================

export interface TaskProjectionState {
  id: TaskId;
  type: string;
  title: string;
  status: TaskStatus;
  priority: string;
  assignedAgent: AgentId | null;
  dependencies: TaskId[];
  blockedBy: TaskId[];
  createdAt: number;
  startedAt: number | null;
  completedAt: number | null;
  failedAt: number | null;
  duration: number | null;
  result: unknown;
  error: string | null;
  retryCount: number;
}

export class TaskHistoryProjection extends Projection {
  private tasks: Map<TaskId, TaskProjectionState> = new Map();

  /**
   * Get task by ID
   */
  getTask(taskId: TaskId): TaskProjectionState | null {
    return this.tasks.get(taskId) || null;
  }

  /**
   * Get all tasks
   */
  getAllTasks(): TaskProjectionState[] {
    return Array.from(this.tasks.values());
  }

  /**
   * Get tasks by status
   */
  getTasksByStatus(status: TaskStatus): TaskProjectionState[] {
    return this.getAllTasks().filter((task) => task.status === status);
  }

  /**
   * Get tasks by agent
   */
  getTasksByAgent(agentId: AgentId): TaskProjectionState[] {
    return this.getAllTasks().filter((task) => task.assignedAgent === agentId);
  }

  /**
   * Get completed task count
   */
  getCompletedTaskCount(): number {
    return this.getTasksByStatus('completed').length;
  }

  /**
   * Get average task duration
   */
  getAverageTaskDuration(): number {
    const completed = this.getTasksByStatus('completed').filter((t) => t.duration !== null);

    if (completed.length === 0) return 0;

    const total = completed.reduce((sum, task) => sum + (task.duration || 0), 0);
    return total / completed.length;
  }

  async handle(event: DomainEvent): Promise<void> {
    switch (event.type) {
      case 'task:created':
        this.handleTaskCreated(event);
        break;
      case 'task:queued':
        this.handleTaskQueued(event);
        break;
      case 'task:started':
        this.handleTaskStarted(event);
        break;
      case 'task:completed':
        this.handleTaskCompleted(event);
        break;
      case 'task:failed':
        this.handleTaskFailed(event);
        break;
      case 'task:blocked':
        this.handleTaskBlocked(event);
        break;
    }
  }

  reset(): void {
    this.tasks.clear();
    this.emit('reset');
  }

  private handleTaskCreated(event: DomainEvent): void {
    const { taskId, taskType, title, priority, dependencies } = event.payload;

    this.tasks.set(taskId as TaskId, {
      id: taskId as TaskId,
      type: taskType as string,
      title: title as string,
      status: 'pending',
      priority: priority as string,
      assignedAgent: null,
      dependencies: (dependencies as TaskId[]) || [],
      blockedBy: [],
      createdAt: event.timestamp,
      startedAt: null,
      completedAt: null,
      failedAt: null,
      duration: null,
      result: null,
      error: null,
      retryCount: 0,
    });

    this.emit('task:created', { taskId });
  }

  private handleTaskQueued(event: DomainEvent): void {
    const { taskId } = event.payload;
    const task = this.tasks.get(taskId as TaskId);

    if (task) {
      task.status = 'queued';
      this.emit('task:queued', { taskId });
    }
  }

  private handleTaskStarted(event: DomainEvent): void {
    const { taskId, agentId } = event.payload;
    const task = this.tasks.get(taskId as TaskId);

    if (task) {
      task.status = 'in-progress';
      task.assignedAgent = agentId as AgentId;
      task.startedAt = event.timestamp;
      this.emit('task:started', { taskId, agentId });
    }
  }

  private handleTaskCompleted(event: DomainEvent): void {
    const { taskId, result, duration } = event.payload;
    const task = this.tasks.get(taskId as TaskId);

    if (task) {
      task.status = 'completed';
      task.completedAt = event.timestamp;
      task.duration = (duration as number) || (task.startedAt ? event.timestamp - task.startedAt : null);
      task.result = result;
      this.emit('task:completed', { taskId });
    }
  }

  private handleTaskFailed(event: DomainEvent): void {
    const { taskId, error, retryCount } = event.payload;
    const task = this.tasks.get(taskId as TaskId);

    if (task) {
      task.status = 'failed';
      task.failedAt = event.timestamp;
      task.error = error as string;
      task.retryCount = retryCount as number;
      this.emit('task:failed', { taskId });
    }
  }

  private handleTaskBlocked(event: DomainEvent): void {
    const { taskId, blockedBy } = event.payload;
    const task = this.tasks.get(taskId as TaskId);

    if (task) {
      task.status = 'blocked';
      task.blockedBy = blockedBy as TaskId[];
      this.emit('task:blocked', { taskId, blockedBy });
    }
  }
}

// =============================================================================
// Memory Index Projection
// =============================================================================

export interface MemoryProjectionState {
  id: string;
  namespace: string;
  key: string;
  type: string;
  size: number;
  accessCount: number;
  storedAt: number;
  lastAccessedAt: number;
  deletedAt: number | null;
  isDeleted: boolean;
}

export class MemoryIndexProjection extends Projection {
  private memories: Map<string, MemoryProjectionState> = new Map();

  /**
   * Get memory by ID
   */
  getMemory(memoryId: string): MemoryProjectionState | null {
    return this.memories.get(memoryId) || null;
  }

  /**
   * Get all active memories (not deleted)
   */
  getActiveMemories(): MemoryProjectionState[] {
    return Array.from(this.memories.values()).filter((m) => !m.isDeleted);
  }

  /**
   * Get memories by namespace
   */
  getMemoriesByNamespace(namespace: string): MemoryProjectionState[] {
    return this.getActiveMemories().filter((m) => m.namespace === namespace);
  }

  /**
   * Get most accessed memories
   */
  getMostAccessedMemories(limit: number = 10): MemoryProjectionState[] {
    return this.getActiveMemories()
      .sort((a, b) => b.accessCount - a.accessCount)
      .slice(0, limit);
  }

  /**
   * Get total memory size by namespace
   */
  getTotalSizeByNamespace(namespace: string): number {
    return this.getMemoriesByNamespace(namespace).reduce((sum, m) => sum + m.size, 0);
  }

  async handle(event: DomainEvent): Promise<void> {
    switch (event.type) {
      case 'memory:stored':
        this.handleMemoryStored(event);
        break;
      case 'memory:retrieved':
        this.handleMemoryRetrieved(event);
        break;
      case 'memory:deleted':
        this.handleMemoryDeleted(event);
        break;
      case 'memory:expired':
        this.handleMemoryExpired(event);
        break;
    }
  }

  reset(): void {
    this.memories.clear();
    this.emit('reset');
  }

  private handleMemoryStored(event: DomainEvent): void {
    const { memoryId, namespace, key, memoryType, size } = event.payload;

    this.memories.set(memoryId as string, {
      id: memoryId as string,
      namespace: namespace as string,
      key: key as string,
      type: memoryType as string,
      size: (size as number) || 0,
      accessCount: 0,
      storedAt: event.timestamp,
      lastAccessedAt: event.timestamp,
      deletedAt: null,
      isDeleted: false,
    });

    this.emit('memory:stored', { memoryId });
  }

  private handleMemoryRetrieved(event: DomainEvent): void {
    const { memoryId, accessCount } = event.payload;
    const memory = this.memories.get(memoryId as string);

    if (memory && !memory.isDeleted) {
      memory.accessCount = accessCount as number;
      memory.lastAccessedAt = event.timestamp;
      this.emit('memory:retrieved', { memoryId });
    }
  }

  private handleMemoryDeleted(event: DomainEvent): void {
    const { memoryId } = event.payload;
    const memory = this.memories.get(memoryId as string);

    if (memory) {
      memory.isDeleted = true;
      memory.deletedAt = event.timestamp;
      this.emit('memory:deleted', { memoryId });
    }
  }

  private handleMemoryExpired(event: DomainEvent): void {
    const { memoryId } = event.payload;
    const memory = this.memories.get(memoryId as string);

    if (memory) {
      memory.isDeleted = true;
      memory.deletedAt = event.timestamp;
      this.emit('memory:expired', { memoryId });
    }
  }
}

/**
 * RVF Event Log (ADR-057 Phase 2)
 *
 * Pure-TypeScript append-only event log that stores events in a binary
 * file format. Replaces the sql.js-dependent EventStore with a zero-
 * dependency alternative.
 *
 * Binary format:
 *   File header:  4 bytes — magic "RVFL"
 *   Record:       4 bytes (uint32 BE payload length) + N bytes (JSON payload)
 *
 * In-memory indexes are rebuilt on initialize() by replaying the file.
 * Snapshots are stored in a separate `.snap.rvf` file using the same format.
 *
 * @module v3/shared/events/rvf-event-log
 */

import { EventEmitter } from 'node:events';
import { existsSync, mkdirSync, readFileSync, writeFileSync, appendFileSync, renameSync } from 'node:fs';
import { dirname } from 'node:path';
import type { DomainEvent } from './domain-events.js';

// Re-export shared interfaces so consumers do not need to import event-store.ts
import type { EventFilter, EventSnapshot, EventStoreStats } from './event-store.js';

/** Validate a file path is safe */
function validatePath(p: string): void {
  if (p.includes('\0')) throw new Error('Event log path contains null bytes');
}

// =============================================================================
// Configuration
// =============================================================================

export interface RvfEventLogConfig {
  /** Path to event log file */
  logPath: string;
  /** Enable verbose logging */
  verbose?: boolean;
  /** Maximum events before snapshot recommendation */
  snapshotThreshold?: number;
}

const DEFAULT_CONFIG: Required<RvfEventLogConfig> = {
  logPath: 'events.rvf',
  verbose: false,
  snapshotThreshold: 100,
};

// =============================================================================
// Constants
// =============================================================================

/** Magic bytes that identify an RVF event log file */
const MAGIC = Buffer.from('RVFL');
const MAGIC_LENGTH = 4;
const LENGTH_PREFIX_BYTES = 4;

// =============================================================================
// RvfEventLog Implementation
// =============================================================================

export class RvfEventLog extends EventEmitter {
  private config: Required<RvfEventLogConfig>;
  private initialized = false;

  /**
   * All events kept in insertion order.
   * Rebuilt from the file on initialize().
   */
  private events: DomainEvent[] = [];

  /** Fast lookup: aggregateId -> indices into this.events */
  private aggregateIndex: Map<string, number[]> = new Map();

  /** Version tracking per aggregate */
  private aggregateVersions: Map<string, number> = new Map();

  /** Snapshots keyed by aggregateId (latest wins) */
  private snapshots: Map<string, EventSnapshot> = new Map();

  /** Path to the companion snapshot file */
  private snapshotPath: string;

  constructor(config: Partial<RvfEventLogConfig> = {}) {
    super();
    this.config = { ...DEFAULT_CONFIG, ...config } as Required<RvfEventLogConfig>;
    this.snapshotPath = this.config.logPath.replace(/\.rvf$/, '.snap.rvf');
    if (this.snapshotPath === this.config.logPath) {
      this.snapshotPath = this.config.logPath + '.snap.rvf';
    }
    validatePath(this.config.logPath);
  }

  // ===========================================================================
  // Lifecycle
  // ===========================================================================

  /** Create / open the log file and rebuild in-memory indexes. */
  async initialize(): Promise<void> {
    if (this.initialized) return;

    this.ensureDirectory(this.config.logPath);

    // --- events file ---
    if (existsSync(this.config.logPath)) {
      this.replayFile(this.config.logPath, (event: DomainEvent) => {
        this.indexEvent(event);
      });
    } else {
      const tmpLog = this.config.logPath + '.tmp';
      writeFileSync(tmpLog, MAGIC);
      renameSync(tmpLog, this.config.logPath);
    }

    // --- snapshots file ---
    if (existsSync(this.snapshotPath)) {
      this.replayFile(this.snapshotPath, (_raw: unknown) => {
        const snap = _raw as EventSnapshot;
        this.snapshots.set(snap.aggregateId, snap);
      });
    } else {
      const tmpSnap = this.snapshotPath + '.tmp';
      writeFileSync(tmpSnap, MAGIC);
      renameSync(tmpSnap, this.snapshotPath);
    }

    this.initialized = true;

    if (this.config.verbose) {
      console.log(
        `[RvfEventLog] Initialized – ${this.events.length} events, ` +
          `${this.snapshots.size} snapshots`
      );
    }

    this.emit('initialized');
  }

  /** Flush to disk and release resources. */
  async close(): Promise<void> {
    if (!this.initialized) return;

    // All data is already on disk (append-only), so just clear memory.
    this.events = [];
    this.aggregateIndex.clear();
    this.aggregateVersions.clear();
    this.snapshots.clear();
    this.initialized = false;

    this.emit('shutdown');
  }

  // ===========================================================================
  // Write Operations
  // ===========================================================================

  /** Append a domain event to the log. */
  async append(event: DomainEvent): Promise<void> {
    this.ensureInitialized();

    if (!event.aggregateId || typeof event.aggregateId !== 'string') {
      throw new Error('Event must have a valid aggregateId string');
    }
    if (!event.type || typeof event.type !== 'string') {
      throw new Error('Event must have a valid type string');
    }

    // Assign next version for aggregate
    const currentVersion = this.aggregateVersions.get(event.aggregateId) ?? 0;
    const nextVersion = currentVersion + 1;
    event.version = nextVersion;

    // Persist to disk first (crash-safe ordering)
    this.appendRecord(this.config.logPath, event);

    // Update in-memory state
    this.indexEvent(event);

    this.emit('event:appended', event);

    if (nextVersion % this.config.snapshotThreshold === 0) {
      this.emit('snapshot:recommended', {
        aggregateId: event.aggregateId,
        version: nextVersion,
      });
    }
  }

  /** Save a snapshot for an aggregate. */
  async saveSnapshot(snapshot: EventSnapshot): Promise<void> {
    this.ensureInitialized();

    this.appendRecord(this.snapshotPath, snapshot);
    this.snapshots.set(snapshot.aggregateId, snapshot);

    this.emit('snapshot:saved', snapshot);
  }

  // ===========================================================================
  // Read Operations
  // ===========================================================================

  /** Get events for a specific aggregate, optionally from a version. */
  async getEvents(aggregateId: string, fromVersion?: number): Promise<DomainEvent[]> {
    this.ensureInitialized();

    const indices = this.aggregateIndex.get(aggregateId);
    if (!indices || indices.length === 0) return [];

    let result = indices.map((i) => this.events[i]);

    if (fromVersion !== undefined) {
      result = result.filter((e) => e.version >= fromVersion);
    }

    // Events within an aggregate are already version-ordered because we
    // append in order, but sort defensively.
    return result.sort((a, b) => a.version - b.version);
  }

  /** Query events with an optional filter (matches EventStore.query API). */
  async getAllEvents(filter?: EventFilter): Promise<DomainEvent[]> {
    this.ensureInitialized();

    if (!filter) {
      return [...this.events].sort((a, b) => a.timestamp - b.timestamp);
    }

    let result: DomainEvent[] = [...this.events];

    // Aggregate ID filter
    if (filter.aggregateIds && filter.aggregateIds.length > 0) {
      const set = new Set(filter.aggregateIds);
      result = result.filter((e) => set.has(e.aggregateId));
    }

    // Aggregate type filter
    if (filter.aggregateTypes && filter.aggregateTypes.length > 0) {
      const set = new Set<string>(filter.aggregateTypes);
      result = result.filter((e) => set.has(e.aggregateType));
    }

    // Event type filter
    if (filter.eventTypes && filter.eventTypes.length > 0) {
      const set = new Set(filter.eventTypes);
      result = result.filter((e) => set.has(e.type));
    }

    // Timestamp filters
    if (filter.afterTimestamp !== undefined) {
      result = result.filter((e) => e.timestamp > filter.afterTimestamp!);
    }
    if (filter.beforeTimestamp !== undefined) {
      result = result.filter((e) => e.timestamp < filter.beforeTimestamp!);
    }

    // Version filter
    if (filter.fromVersion !== undefined) {
      result = result.filter((e) => e.version >= filter.fromVersion!);
    }

    // Sort by timestamp ascending (matches EventStore behaviour)
    result.sort((a, b) => a.timestamp - b.timestamp);

    // Pagination
    if (filter.offset) {
      result = result.slice(filter.offset);
    }
    if (filter.limit) {
      result = result.slice(0, filter.limit);
    }

    return result;
  }

  /** Get latest snapshot for an aggregate. */
  async getSnapshot(aggregateId: string): Promise<EventSnapshot | null> {
    this.ensureInitialized();
    return this.snapshots.get(aggregateId) ?? null;
  }

  /** Return event store statistics. */
  async getStats(): Promise<EventStoreStats> {
    this.ensureInitialized();

    const eventsByType: Record<string, number> = {};
    const eventsByAggregate: Record<string, number> = {};
    let oldest: number | null = null;
    let newest: number | null = null;

    for (const event of this.events) {
      // by type
      eventsByType[event.type] = (eventsByType[event.type] ?? 0) + 1;

      // by aggregate
      eventsByAggregate[event.aggregateId] =
        (eventsByAggregate[event.aggregateId] ?? 0) + 1;

      // timestamp range
      if (oldest === null || event.timestamp < oldest) oldest = event.timestamp;
      if (newest === null || event.timestamp > newest) newest = event.timestamp;
    }

    return {
      totalEvents: this.events.length,
      eventsByType,
      eventsByAggregate,
      oldestEvent: oldest,
      newestEvent: newest,
      snapshotCount: this.snapshots.size,
    };
  }

  /**
   * Flush to disk.
   * For the append-only log this is a no-op because every append() call
   * writes to disk synchronously. Provided for API compatibility with
   * EventStore.
   */
  async persist(): Promise<void> {
    // All records are already flushed on append. Nothing to do.
    if (this.config.verbose) {
      console.log('[RvfEventLog] persist() called — all data already on disk');
    }
  }

  // ===========================================================================
  // Private Helpers
  // ===========================================================================

  /**
   * Replay an RVF file and invoke `handler` for every decoded record.
   * Used both for events and snapshots.
   */
  private replayFile(filePath: string, handler: (record: any) => void): void {
    const buf = readFileSync(filePath);

    // Validate magic
    if (buf.length < MAGIC_LENGTH || buf.subarray(0, MAGIC_LENGTH).compare(MAGIC) !== 0) {
      throw new Error(`[RvfEventLog] Invalid file header in ${filePath}`);
    }

    let offset = MAGIC_LENGTH;

    const MAX_PAYLOAD_SIZE = 100 * 1024 * 1024; // 100MB safety limit
    while (offset + LENGTH_PREFIX_BYTES <= buf.length) {
      const payloadLength = buf.readUInt32BE(offset);
      offset += LENGTH_PREFIX_BYTES;

      if (payloadLength > MAX_PAYLOAD_SIZE) {
        if (this.config.verbose) {
          console.warn(`[RvfEventLog] Payload size ${payloadLength} exceeds safety limit`);
        }
        break;
      }

      if (offset + payloadLength > buf.length) {
        // Truncated record — stop reading (crash recovery).
        if (this.config.verbose) {
          console.warn(
            `[RvfEventLog] Truncated record at offset ${offset - LENGTH_PREFIX_BYTES} — ` +
              `expected ${payloadLength} bytes, have ${buf.length - offset}`
          );
        }
        break;
      }

      const json = buf.subarray(offset, offset + payloadLength).toString('utf8');
      offset += payloadLength;

      try {
        const record = JSON.parse(json);
        handler(record);
      } catch {
        if (this.config.verbose) {
          console.warn(`[RvfEventLog] Corrupt JSON record skipped`);
        }
      }
    }
  }

  /** Append a single record to an RVF file. */
  private appendRecord(filePath: string, record: unknown): void {
    const json = JSON.stringify(record);
    const payload = Buffer.from(json, 'utf8');
    const lengthBuf = Buffer.allocUnsafe(LENGTH_PREFIX_BYTES);
    lengthBuf.writeUInt32BE(payload.length, 0);

    appendFileSync(filePath, Buffer.concat([lengthBuf, payload]));
  }

  /** Add an event to the in-memory indexes. */
  private indexEvent(event: DomainEvent): void {
    const idx = this.events.length;
    this.events.push(event);

    // aggregateIndex
    let indices = this.aggregateIndex.get(event.aggregateId);
    if (!indices) {
      indices = [];
      this.aggregateIndex.set(event.aggregateId, indices);
    }
    indices.push(idx);

    // version tracker
    const current = this.aggregateVersions.get(event.aggregateId) ?? 0;
    if (event.version > current) {
      this.aggregateVersions.set(event.aggregateId, event.version);
    }
  }

  /** Ensure parent directory exists for a file path. */
  private ensureDirectory(filePath: string): void {
    const dir = dirname(filePath);
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true });
    }
  }

  /** Guard that throws if initialize() has not been called. */
  private ensureInitialized(): void {
    if (!this.initialized) {
      throw new Error('RvfEventLog not initialized. Call initialize() first.');
    }
  }
}

/**
 * State Reconstructor - ADR-007 Implementation
 *
 * Reconstructs aggregate state from event streams.
 * Implements event sourcing patterns for V3.
 *
 * @module v3/shared/events/state-reconstructor
 */

import { EventStore, type EventSnapshot } from './event-store.js';
import type { DomainEvent } from './domain-events.js';

/**
 * Aggregate root interface
 */
export interface AggregateRoot {
  id: string;
  version: number;
  apply(event: DomainEvent): void;
  getState(): Record<string, unknown>;
}

/**
 * Reconstructor options
 */
export interface ReconstructorOptions {
  useSnapshots: boolean;
  snapshotInterval: number; // Create snapshot every N events
  maxEventsToReplay: number;
}

/**
 * State Reconstructor
 *
 * Reconstructs aggregate state from event history.
 * Supports snapshots for performance optimization.
 */
export class StateReconstructor {
  private readonly options: ReconstructorOptions;

  constructor(
    private readonly eventStore: EventStore,
    options?: Partial<ReconstructorOptions>
  ) {
    this.options = {
      useSnapshots: true,
      snapshotInterval: 100,
      maxEventsToReplay: 10000,
      ...options,
    };
  }

  /**
   * Reconstruct aggregate state from events
   */
  async reconstruct<T extends AggregateRoot>(
    aggregateId: string,
    factory: (id: string) => T
  ): Promise<T> {
    const aggregate = factory(aggregateId);

    // Try to load from snapshot first
    if (this.options.useSnapshots) {
      const snapshot = await this.eventStore.getSnapshot(aggregateId);
      if (snapshot) {
        this.applySnapshot(aggregate, snapshot);
      }
    }

    // Get events after snapshot version (or all if no snapshot)
    const events = await this.eventStore.getEvents(aggregateId, aggregate.version + 1);

    // Apply events
    for (const event of events) {
      if (events.length > this.options.maxEventsToReplay) {
        throw new Error(`Too many events to replay (${events.length}). Consider creating a snapshot.`);
      }

      aggregate.apply(event);
    }

    // Create snapshot if interval reached
    if (this.options.useSnapshots && aggregate.version % this.options.snapshotInterval === 0) {
      await this.createSnapshot(aggregate);
    }

    return aggregate;
  }

  /**
   * Reconstruct state at a specific point in time
   */
  async reconstructAtTime<T extends AggregateRoot>(
    aggregateId: string,
    factory: (id: string) => T,
    timestamp: Date
  ): Promise<T> {
    const aggregate = factory(aggregateId);

    // Get all events up to timestamp
    const allEvents = await this.eventStore.getEvents(aggregateId);
    const events = allEvents.filter((e) => e.timestamp <= timestamp.getTime());

    // Apply events
    for (const event of events) {
      aggregate.apply(event);
    }

    return aggregate;
  }

  /**
   * Reconstruct state at a specific version
   */
  async reconstructAtVersion<T extends AggregateRoot>(
    aggregateId: string,
    factory: (id: string) => T,
    targetVersion: number
  ): Promise<T> {
    const aggregate = factory(aggregateId);

    // Get events up to target version
    const events = await this.eventStore.getEvents(aggregateId);
    const limitedEvents = events.filter((e) => e.version <= targetVersion);

    // Apply events
    for (const event of limitedEvents) {
      aggregate.apply(event);
    }

    return aggregate;
  }

  /**
   * Apply snapshot to aggregate
   */
  private applySnapshot(aggregate: AggregateRoot, snapshot: EventSnapshot): void {
    // Type assertion for aggregate that has restoreFromSnapshot
    const restorable = aggregate as AggregateRoot & {
      restoreFromSnapshot?(state: unknown): void;
    };

    if (typeof restorable.restoreFromSnapshot === 'function') {
      restorable.restoreFromSnapshot(snapshot.state);
    }

    // Update version
    (aggregate as any).version = snapshot.version;
  }

  /**
   * Create snapshot for aggregate
   */
  private async createSnapshot(aggregate: AggregateRoot): Promise<void> {
    const snapshot: EventSnapshot = {
      aggregateId: aggregate.id,
      aggregateType: this.getAggregateType(aggregate),
      version: aggregate.version,
      state: aggregate.getState(),
      timestamp: Date.now(),
    };

    await this.eventStore.saveSnapshot(snapshot);
  }

  /**
   * Get aggregate type from instance
   */
  private getAggregateType(aggregate: AggregateRoot): 'agent' | 'task' | 'memory' | 'swarm' {
    const typeName = aggregate.constructor.name.toLowerCase().replace('aggregate', '');
    // Map to valid aggregate types
    if (typeName === 'agent' || typeName === 'task' || typeName === 'memory' || typeName === 'swarm') {
      return typeName;
    }
    return 'agent'; // Default fallback
  }
}

/**
 * Agent Aggregate - Example implementation
 */
export class AgentAggregate implements AggregateRoot {
  id: string;
  version = 0;

  private state = {
    name: '',
    role: '',
    status: 'idle' as string,
    currentTask: null as string | null,
    completedTasks: [] as string[],
    capabilities: [] as string[],
    createdAt: null as Date | null,
    lastActiveAt: null as Date | null,
  };

  constructor(id: string) {
    this.id = id;
  }

  apply(event: DomainEvent): void {
    this.version = event.version;

    switch (event.type) {
      case 'agent:spawned':
        this.state.name = event.payload.name as string;
        this.state.role = event.payload.role as string;
        this.state.capabilities = (event.payload.capabilities as string[]) ?? [];
        this.state.status = 'idle';
        this.state.createdAt = new Date(event.timestamp);
        break;

      case 'agent:started':
        this.state.status = 'active';
        this.state.lastActiveAt = new Date(event.timestamp);
        break;

      case 'agent:task-assigned':
        this.state.currentTask = event.payload.taskId as string;
        this.state.status = 'busy';
        this.state.lastActiveAt = new Date(event.timestamp);
        break;

      case 'agent:task-completed':
        this.state.completedTasks.push(event.payload.taskId as string);
        this.state.currentTask = null;
        this.state.status = 'active';
        this.state.lastActiveAt = new Date(event.timestamp);
        break;

      case 'agent:terminated':
        this.state.status = 'terminated';
        break;
    }
  }

  getState(): Record<string, unknown> {
    return { ...this.state };
  }

  restoreFromSnapshot(snapshotState: unknown): void {
    const state = snapshotState as typeof this.state;
    this.state = {
      ...state,
      createdAt: state.createdAt ? new Date(state.createdAt) : null,
      lastActiveAt: state.lastActiveAt ? new Date(state.lastActiveAt) : null,
    };
  }

  // Getters for type safety
  get name(): string { return this.state.name; }
  get role(): string { return this.state.role; }
  get status(): string { return this.state.status; }
  get currentTask(): string | null { return this.state.currentTask; }
  get completedTasks(): string[] { return [...this.state.completedTasks]; }
  get capabilities(): string[] { return [...this.state.capabilities]; }
}

/**
 * Task Aggregate - Example implementation
 */
export class TaskAggregate implements AggregateRoot {
  id: string;
  version = 0;

  private state = {
    title: '',
    description: '',
    type: '',
    priority: 'normal' as string,
    status: 'pending' as string,
    assignedAgent: null as string | null,
    result: null as unknown,
    createdAt: null as Date | null,
    startedAt: null as Date | null,
    completedAt: null as Date | null,
  };

  constructor(id: string) {
    this.id = id;
  }

  apply(event: DomainEvent): void {
    this.version = event.version;

    switch (event.type) {
      case 'task:created':
        this.state.title = event.payload.title as string;
        this.state.description = event.payload.description as string;
        this.state.type = event.payload.taskType as string;
        this.state.priority = (event.payload.priority as string) ?? 'normal';
        this.state.status = 'pending';
        this.state.createdAt = new Date(event.timestamp);
        break;

      case 'task:started':
        this.state.assignedAgent = event.payload.agentId as string;
        this.state.status = 'running';
        this.state.startedAt = new Date(event.timestamp);
        break;

      case 'task:completed':
        this.state.result = event.payload.result;
        this.state.status = 'completed';
        this.state.completedAt = new Date(event.timestamp);
        break;

      case 'task:failed':
        this.state.status = 'failed';
        this.state.completedAt = new Date(event.timestamp);
        break;

      case 'task:cancelled':
        this.state.status = 'cancelled';
        this.state.completedAt = new Date(event.timestamp);
        break;
    }
  }

  getState(): Record<string, unknown> {
    return { ...this.state };
  }

  restoreFromSnapshot(snapshotState: unknown): void {
    const state = snapshotState as typeof this.state;
    this.state = {
      ...state,
      createdAt: state.createdAt ? new Date(state.createdAt) : null,
      startedAt: state.startedAt ? new Date(state.startedAt) : null,
      completedAt: state.completedAt ? new Date(state.completedAt) : null,
    };
  }

  // Getters
  get title(): string { return this.state.title; }
  get status(): string { return this.state.status; }
  get assignedAgent(): string | null { return this.state.assignedAgent; }
  get result(): unknown { return this.state.result; }
}

/**
 * Factory function
 */
export function createStateReconstructor(
  eventStore: EventStore,
  options?: Partial<ReconstructorOptions>
): StateReconstructor {
  return new StateReconstructor(eventStore, options);
}

/**
 * V3 Event Bus System
 * Event-driven communication for the 15-agent swarm
 *
 * Based on ADR-007 (Event Sourcing for State Changes)
 */

import {
  EventType,
  EventHandler,
  SwarmEvent,
  AgentId
} from './types.js';

// =============================================================================
// Event Bus Interface
// =============================================================================

export interface IEventBus {
  subscribe<T>(eventType: EventType, handler: EventHandler<T>): () => void;
  subscribeAll(handler: EventHandler): () => void;
  emit<T>(event: SwarmEvent<T>): Promise<void>;
  emitSync<T>(event: SwarmEvent<T>): void;
  getHistory(filter?: EventFilter): SwarmEvent[];
  clear(): void;
}

export interface EventFilter {
  types?: EventType[];
  sources?: (AgentId | 'swarm')[];
  since?: number;
  until?: number;
  limit?: number;
}

// =============================================================================
// Event Store Interface (Event Sourcing)
// =============================================================================

export interface IEventStore {
  append(event: SwarmEvent): Promise<void>;
  getEvents(aggregateId: string, fromVersion?: number): Promise<SwarmEvent[]>;
  getAllEvents(filter?: EventFilter): Promise<SwarmEvent[]>;
  getSnapshot(aggregateId: string): Promise<EventStoreSnapshot | null>;
  saveSnapshot(snapshot: EventStoreSnapshot): Promise<void>;
}

export interface EventStoreSnapshot {
  aggregateId: string;
  version: number;
  state: unknown;
  timestamp: number;
}

// =============================================================================
// Event Bus Implementation
// =============================================================================

export class EventBus implements IEventBus {
  private handlers: Map<EventType | '*', Set<EventHandler>> = new Map();
  private history: SwarmEvent[] = [];
  private maxHistorySize: number;

  constructor(options: { maxHistorySize?: number } = {}) {
    this.maxHistorySize = options.maxHistorySize ?? 10000;
  }

  subscribe<T>(eventType: EventType, handler: EventHandler<T>): () => void {
    if (!this.handlers.has(eventType)) {
      this.handlers.set(eventType, new Set());
    }

    const handlers = this.handlers.get(eventType)!;
    handlers.add(handler as EventHandler);

    return () => {
      handlers.delete(handler as EventHandler);
    };
  }

  subscribeAll(handler: EventHandler): () => void {
    if (!this.handlers.has('*')) {
      this.handlers.set('*', new Set());
    }

    const handlers = this.handlers.get('*')!;
    handlers.add(handler);

    return () => {
      handlers.delete(handler);
    };
  }

  async emit<T>(event: SwarmEvent<T>): Promise<void> {
    this.addToHistory(event);

    const typeHandlers = this.handlers.get(event.type) ?? new Set();
    const allHandlers = this.handlers.get('*') ?? new Set();

    const allPromises: Promise<void>[] = [];

    for (const handler of typeHandlers) {
      allPromises.push(this.safeExecute(handler, event));
    }

    for (const handler of allHandlers) {
      allPromises.push(this.safeExecute(handler, event));
    }

    await Promise.all(allPromises);
  }

  emitSync<T>(event: SwarmEvent<T>): void {
    this.addToHistory(event);

    const typeHandlers = this.handlers.get(event.type) ?? new Set();
    const allHandlers = this.handlers.get('*') ?? new Set();

    for (const handler of typeHandlers) {
      try {
        const result = handler(event);
        if (result instanceof Promise) {
          result.catch(err => console.error(`Event handler error: ${err}`));
        }
      } catch (err) {
        console.error(`Event handler error: ${err}`);
      }
    }

    for (const handler of allHandlers) {
      try {
        const result = handler(event);
        if (result instanceof Promise) {
          result.catch(err => console.error(`Event handler error: ${err}`));
        }
      } catch (err) {
        console.error(`Event handler error: ${err}`);
      }
    }
  }

  getHistory(filter?: EventFilter): SwarmEvent[] {
    let events = [...this.history];

    if (filter?.types?.length) {
      events = events.filter(e => filter.types!.includes(e.type));
    }

    if (filter?.sources?.length) {
      events = events.filter(e => filter.sources!.includes(e.source));
    }

    if (filter?.since) {
      events = events.filter(e => e.timestamp >= filter.since!);
    }

    if (filter?.until) {
      events = events.filter(e => e.timestamp <= filter.until!);
    }

    if (filter?.limit) {
      events = events.slice(-filter.limit);
    }

    return events;
  }

  clear(): void {
    this.history = [];
  }

  private addToHistory(event: SwarmEvent): void {
    this.history.push(event);

    if (this.history.length > this.maxHistorySize) {
      this.history = this.history.slice(-Math.floor(this.maxHistorySize / 2));
    }
  }

  private async safeExecute(handler: EventHandler, event: SwarmEvent): Promise<void> {
    try {
      await handler(event);
    } catch (err) {
      console.error(`Event handler error for ${event.type}: ${err}`);
    }
  }
}

// =============================================================================
// In-Memory Event Store
// =============================================================================

export class InMemoryEventStore implements IEventStore {
  private events: Map<string, SwarmEvent[]> = new Map();
  private allEvents: SwarmEvent[] = [];
  private snapshots: Map<string, EventStoreSnapshot> = new Map();

  async append(event: SwarmEvent): Promise<void> {
    const aggregateId = this.extractAggregateId(event);

    if (!this.events.has(aggregateId)) {
      this.events.set(aggregateId, []);
    }

    this.events.get(aggregateId)!.push(event);
    this.allEvents.push(event);
  }

  async getEvents(aggregateId: string, fromVersion?: number): Promise<SwarmEvent[]> {
    const events = this.events.get(aggregateId) ?? [];

    if (fromVersion !== undefined) {
      return events.slice(fromVersion);
    }

    return events;
  }

  async getAllEvents(filter?: EventFilter): Promise<SwarmEvent[]> {
    let events = [...this.allEvents];

    if (filter?.types?.length) {
      events = events.filter(e => filter.types!.includes(e.type));
    }

    if (filter?.sources?.length) {
      events = events.filter(e => filter.sources!.includes(e.source));
    }

    if (filter?.since) {
      events = events.filter(e => e.timestamp >= filter.since!);
    }

    if (filter?.until) {
      events = events.filter(e => e.timestamp <= filter.until!);
    }

    if (filter?.limit) {
      events = events.slice(-filter.limit);
    }

    return events;
  }

  async getSnapshot(aggregateId: string): Promise<EventStoreSnapshot | null> {
    return this.snapshots.get(aggregateId) ?? null;
  }

  async saveSnapshot(snapshot: EventStoreSnapshot): Promise<void> {
    this.snapshots.set(snapshot.aggregateId, snapshot);
  }

  private extractAggregateId(event: SwarmEvent): string {
    if (event.source !== 'swarm') {
      return event.source;
    }

    if (typeof event.payload === 'object' && event.payload !== null) {
      const payload = event.payload as Record<string, unknown>;
      if ('agentId' in payload) return payload.agentId as string;
      if ('taskId' in payload) return payload.taskId as string;
    }

    return 'swarm';
  }
}

