// Swarm Events
export function swarmInitializedEvent(config: unknown): SwarmEvent {
  return createEvent('swarm:initialized', 'swarm', { config });
}

export function swarmPhaseChangedEvent(previousPhase: string, newPhase: string): SwarmEvent {
