class AgentManager {
  async spawnAgent(type: string, config: Record<string, unknown>) {
    const agentId = `agent-${Date.now()}`;

    // Pre-spawn hooks
    const preContext: HookContext = {
      event: HookEvent.PreAgentSpawn,
      timestamp: new Date(),
      agent: {
        id: agentId,
        type,
        config,
      },
