    // Pre-terminate hooks
    const preContext: HookContext = {
      event: HookEvent.PreAgentTerminate,
      timestamp: new Date(),
      agent: { id: agentId, type: 'unknown' },
    };

    await hookExecutor.execute(HookEvent.PreAgentTerminate, preContext);

    // Terminate agent
    await this.destroyAgent(agentId);

