    const postContext: HookContext = {
      event: HookEvent.PostAgentTerminate,
      timestamp: new Date(),
      agent: { id: agentId, type: 'unknown' },
      metadata: { success: true },
    };

    await hookExecutor.execute(HookEvent.PostAgentTerminate, postContext);
  }

