    const context: HookContext = {
      event: HookEvent.SessionEnd,
      timestamp: new Date(),
      session: {
        id: sessionId,
        startTime: new Date(), // Would be loaded from state
        endTime: new Date(),
      },
    };

    await hookExecutor.execute(HookEvent.SessionEnd, context);

    // Emit system event
    eventBus.emit('session:terminated', {
      sessionId,
      timestamp: Date.now(),
    });
  }
}
