/**
 * V3 Session Management Hooks
 *
 * Provides session-end and session-restore hooks for state persistence.
 * Enables cross-session memory and state recovery.
 *
 * @module v3/shared/hooks/session-hooks
 */

import {
  HookEvent,
  HookContext,
  HookResult,
  HookPriority,
  SessionInfo,
} from './types.js';
import { HookRegistry } from './registry.js';

/**
 * Session state to persist
 */
export interface SessionState {
  /** Session ID */
  sessionId: string;
  /** Session start time */
  startTime: Date;
  /** Session end time */
  endTime?: Date;
  /** Working directory */
  workingDirectory?: string;
  /** Active tasks */
  activeTasks?: Array<{
    id: string;
    description: string;
    status: 'pending' | 'in_progress' | 'completed' | 'failed';
  }>;
  /** Spawned agents */
  spawnedAgents?: Array<{
    id: string;
    type: string;
    status: 'active' | 'idle' | 'terminated';
  }>;
  /** Memory entries */
  memoryEntries?: Array<{
    key: string;
    namespace: string;
    type: string;
  }>;
  /** Git state */
  gitState?: {
    branch: string;
    uncommittedChanges: number;
    lastCommit?: string;
  };
  /** Learning metrics */
  learningMetrics?: {
    patternsLearned: number;
    trajectoryCount: number;
    avgConfidence: number;
  };
  /** Custom metadata */
  metadata?: Record<string, unknown>;
}

/**
 * Session-end hook result
 */
export interface SessionEndHookResult extends HookResult {
  /** Session state that was persisted */
  persistedState?: SessionState;
  /** File path where state was saved */
  statePath?: string;
  /** Duration of the session in ms */
  duration?: number;
  /** Summary of session activity */
  summary?: SessionSummary;
}

/**
 * Session-restore hook result
 */
export interface SessionRestoreHookResult extends HookResult {
  /** Restored session state */
  restoredState?: SessionState;
  /** Number of tasks restored */
  tasksRestored?: number;
  /** Number of agents restored */
  agentsRestored?: number;
  /** Memory entries restored */
  memoryRestored?: number;
  /** Warnings during restoration */
  warnings?: string[];
}

/**
 * Session summary
 */
export interface SessionSummary {
  /** Total tasks executed */
  tasksExecuted: number;
  /** Successful tasks */
  tasksSucceeded: number;
  /** Failed tasks */
  tasksFailed: number;
  /** Commands executed */
  commandsExecuted: number;
  /** Files modified */
  filesModified: number;
  /** Agents spawned */
  agentsSpawned: number;
  /** Duration in ms */
  duration: number;
}

/**
 * Session storage interface
 */
export interface SessionStorage {
  /** Save session state */
  save(sessionId: string, state: SessionState): Promise<void>;
  /** Load session state */
  load(sessionId: string): Promise<SessionState | null>;
  /** List available sessions */
  list(): Promise<Array<{ id: string; startTime: Date; summary?: SessionSummary }>>;
  /** Delete session */
  delete(sessionId: string): Promise<boolean>;
  /** Get latest session ID */
  getLatest(): Promise<string | null>;
}

/**
 * In-memory session storage (for testing and fallback)
 */
export class InMemorySessionStorage implements SessionStorage {
  private sessions: Map<string, SessionState> = new Map();

  async save(sessionId: string, state: SessionState): Promise<void> {
    this.sessions.set(sessionId, state);
  }

  async load(sessionId: string): Promise<SessionState | null> {
    return this.sessions.get(sessionId) || null;
  }

  async list(): Promise<Array<{ id: string; startTime: Date; summary?: SessionSummary }>> {
    return Array.from(this.sessions.entries()).map(([id, state]) => ({
      id,
      startTime: state.startTime,
    }));
  }

  async delete(sessionId: string): Promise<boolean> {
    return this.sessions.delete(sessionId);
  }

  async getLatest(): Promise<string | null> {
    let latest: { id: string; time: number } | null = null;

    for (const [id, state] of this.sessions) {
      const time = state.startTime.getTime();
      if (!latest || time > latest.time) {
        latest = { id, time };
      }
    }

    return latest?.id || null;
  }
}

/**
 * Session activity tracker
 */
interface SessionActivity {
  tasksExecuted: number;
  tasksSucceeded: number;
  tasksFailed: number;
  commandsExecuted: number;
  filesModified: Set<string>;
  agentsSpawned: Set<string>;
}

/**
 * Session Hooks Manager
 *
 * Manages session lifecycle hooks with state persistence.
 */
export class SessionHooksManager {
  private registry: HookRegistry;
  private storage: SessionStorage;
  private currentSessionId: string | null = null;
  private sessionStartTime: Date | null = null;
  private activity: SessionActivity = {
    tasksExecuted: 0,
    tasksSucceeded: 0,
    tasksFailed: 0,
    commandsExecuted: 0,
    filesModified: new Set(),
    agentsSpawned: new Set(),
  };

  constructor(registry: HookRegistry, storage?: SessionStorage) {
    this.registry = registry;
    this.storage = storage || new InMemorySessionStorage();
    this.registerDefaultHooks();
  }

  /**
   * Register default session hooks
   */
  private registerDefaultHooks(): void {
    // Session start hook
    this.registry.register(
      HookEvent.SessionStart,
      this.handleSessionStart.bind(this),
      HookPriority.High,
      { name: 'session-hooks:start' }
    );

    // Session end hook
    this.registry.register(
      HookEvent.SessionEnd,
      this.handleSessionEnd.bind(this),
      HookPriority.High,
      { name: 'session-hooks:end' }
    );

    // Session resume hook (for restoration)
    this.registry.register(
      HookEvent.SessionResume,
      this.handleSessionResume.bind(this),
      HookPriority.High,
      { name: 'session-hooks:resume' }
    );

    // Track tasks
    this.registry.register(
      HookEvent.PostTaskExecute,
      this.trackTaskExecution.bind(this),
      HookPriority.Low,
      { name: 'session-hooks:track-task' }
    );

    // Track commands
    this.registry.register(
      HookEvent.PostCommand,
      this.trackCommandExecution.bind(this),
      HookPriority.Low,
      { name: 'session-hooks:track-command' }
    );

    // Track file modifications
    this.registry.register(
      HookEvent.PostEdit,
      this.trackFileModification.bind(this),
      HookPriority.Low,
      { name: 'session-hooks:track-file' }
    );

    // Track agent spawns
    this.registry.register(
      HookEvent.PostAgentSpawn,
      this.trackAgentSpawn.bind(this),
      HookPriority.Low,
      { name: 'session-hooks:track-agent' }
    );
  }

  /**
   * Handle session start
   */
  async handleSessionStart(context: HookContext): Promise<HookResult> {
    this.currentSessionId = context.session?.id || `session-${Date.now()}`;
    this.sessionStartTime = new Date();
    this.resetActivity();

    return {
      success: true,
      data: {
        session: {
          id: this.currentSessionId,
          startTime: this.sessionStartTime,
        },
      },
    };
  }

  /**
   * Handle session end
   */
  async handleSessionEnd(context: HookContext): Promise<SessionEndHookResult> {
    if (!this.currentSessionId || !this.sessionStartTime) {
      return { success: true }; // No active session to end
    }

    const endTime = new Date();
    const duration = endTime.getTime() - this.sessionStartTime.getTime();

    // Build session summary
    const summary: SessionSummary = {
      tasksExecuted: this.activity.tasksExecuted,
      tasksSucceeded: this.activity.tasksSucceeded,
      tasksFailed: this.activity.tasksFailed,
      commandsExecuted: this.activity.commandsExecuted,
      filesModified: this.activity.filesModified.size,
      agentsSpawned: this.activity.agentsSpawned.size,
      duration,
    };

    // Build session state
    const state: SessionState = {
      sessionId: this.currentSessionId,
      startTime: this.sessionStartTime,
      endTime,
      workingDirectory: context.metadata?.workingDirectory as string | undefined,
      activeTasks: context.metadata?.activeTasks as SessionState['activeTasks'],
      spawnedAgents: context.metadata?.spawnedAgents as SessionState['spawnedAgents'],
      memoryEntries: context.metadata?.memoryEntries as SessionState['memoryEntries'],
      gitState: context.metadata?.gitState as SessionState['gitState'],
      learningMetrics: context.metadata?.learningMetrics as SessionState['learningMetrics'],
      metadata: {
        summary,
        ...(context.metadata || {}),
      },
    };

    // Persist state
    await this.storage.save(this.currentSessionId, state);

    // Reset session tracking
    const sessionId = this.currentSessionId;
    this.currentSessionId = null;
    this.sessionStartTime = null;
    this.resetActivity();

    return {
      success: true,
      persistedState: state,
      statePath: `sessions/${sessionId}.json`,
      duration,
      summary,
    };
  }

  /**
   * Handle session resume (restoration)
   */
  async handleSessionResume(context: HookContext): Promise<SessionRestoreHookResult> {
    let sessionId = context.session?.id;

    // If 'latest' is requested, get the most recent session
    if (sessionId === 'latest' || !sessionId) {
      sessionId = await this.storage.getLatest() || undefined;
    }

    if (!sessionId) {
      return {
        success: false,
        error: new Error('No session ID provided and no previous sessions found'),
        warnings: ['No sessions available for restoration'],
      };
    }

    // Load session state
    const state = await this.storage.load(sessionId);

    if (!state) {
      return {
        success: false,
        error: new Error(`Session ${sessionId} not found`),
        warnings: [`Session ${sessionId} does not exist or has been deleted`],
      };
    }

    const warnings: string[] = [];

    // Validate state age
    const stateAge = Date.now() - state.startTime.getTime();
    const maxAge = 7 * 24 * 60 * 60 * 1000; // 7 days
    if (stateAge > maxAge) {
      warnings.push(`Session is ${Math.floor(stateAge / (24 * 60 * 60 * 1000))} days old, some state may be stale`);
    }

    // Count restorable items
    const tasksRestored = state.activeTasks?.length || 0;
    const agentsRestored = state.spawnedAgents?.length || 0;
    const memoryRestored = state.memoryEntries?.length || 0;

    // Check for incomplete tasks
    const incompleteTasks = state.activeTasks?.filter(
      t => t.status === 'pending' || t.status === 'in_progress'
    );
    if (incompleteTasks && incompleteTasks.length > 0) {
      warnings.push(`${incompleteTasks.length} tasks were incomplete when session ended`);
    }

    // Update current session tracking
    this.currentSessionId = `session-${Date.now()}-restored`;
    this.sessionStartTime = new Date();
    this.resetActivity();

    return {
      success: true,
      restoredState: state,
      tasksRestored,
      agentsRestored,
      memoryRestored,
      warnings: warnings.length > 0 ? warnings : undefined,
      data: {
        session: {
          id: this.currentSessionId,
          startTime: this.sessionStartTime,
          metadata: {
            restoredFrom: sessionId,
            originalStartTime: state.startTime,
          },
        },
      },
    };
  }

  /**
   * Track task execution
   */
  private async trackTaskExecution(context: HookContext): Promise<HookResult> {
    this.activity.tasksExecuted++;
    if (context.metadata?.success !== false) {
      this.activity.tasksSucceeded++;
    } else {
      this.activity.tasksFailed++;
    }
    return { success: true };
  }

  /**
   * Track command execution
   */
  private async trackCommandExecution(context: HookContext): Promise<HookResult> {
    this.activity.commandsExecuted++;
    return { success: true };
  }

  /**
   * Track file modification
   */
  private async trackFileModification(context: HookContext): Promise<HookResult> {
    if (context.file?.path) {
      this.activity.filesModified.add(context.file.path);
    }
    return { success: true };
  }

  /**
   * Track agent spawn
   */
  private async trackAgentSpawn(context: HookContext): Promise<HookResult> {
    if (context.agent?.id) {
      this.activity.agentsSpawned.add(context.agent.id);
    }
    return { success: true };
  }

  /**
   * Reset activity tracking
   */
  private resetActivity(): void {
    this.activity = {
      tasksExecuted: 0,
      tasksSucceeded: 0,
      tasksFailed: 0,
      commandsExecuted: 0,
      filesModified: new Set(),
      agentsSpawned: new Set(),
    };
  }

  /**
   * Execute session-end hook manually
   */
  async executeSessionEnd(metadata?: Record<string, unknown>): Promise<SessionEndHookResult> {
    const context: HookContext = {
      event: HookEvent.SessionEnd,
      timestamp: new Date(),
      session: this.currentSessionId
        ? {
            id: this.currentSessionId,
            startTime: this.sessionStartTime!,
          }
        : undefined,
      metadata,
    };

    return this.handleSessionEnd(context);
  }

  /**
   * Execute session-restore hook manually
   */
  async executeSessionRestore(
    sessionId?: string,
    metadata?: Record<string, unknown>
  ): Promise<SessionRestoreHookResult> {
    const context: HookContext = {
      event: HookEvent.SessionResume,
      timestamp: new Date(),
      session: {
        id: sessionId || 'latest',
        startTime: new Date(),
      },
      metadata,
    };

    return this.handleSessionResume(context);
  }

  /**
   * List available sessions
   */
  async listSessions(): Promise<Array<{ id: string; startTime: Date; summary?: SessionSummary }>> {
    return this.storage.list();
  }

  /**
   * Delete a session
   */
  async deleteSession(sessionId: string): Promise<boolean> {
    return this.storage.delete(sessionId);
  }

  /**
   * Get current session ID
   */
  getCurrentSessionId(): string | null {
    return this.currentSessionId;
  }

  /**
   * Get current session activity
   */
  getCurrentActivity(): SessionActivity {
    return { ...this.activity };
  }

  /**
   * Set storage backend
   */
  setStorage(storage: SessionStorage): void {
    this.storage = storage;
  }
}

/**
 * Create session hooks manager
 */
export function createSessionHooksManager(
  registry: HookRegistry,
  storage?: SessionStorage
): SessionHooksManager {
  return new SessionHooksManager(registry, storage);
}

/**
 * V3 Task Lifecycle Hooks
 *
 * Provides pre-task and post-task hooks for task execution lifecycle.
 * Integrates with ReasoningBank for learning and pattern recognition.
 *
 * @module v3/shared/hooks/task-hooks
 */

import {
  HookEvent,
  HookContext,
  HookResult,
  HookPriority,
  TaskInfo,
} from './types.js';
import { HookRegistry } from './registry.js';

/**
 * Pre-task hook result with agent suggestions
 */
export interface PreTaskHookResult extends HookResult {
  /** Suggested agents for the task */
  suggestedAgents?: AgentSuggestion[];
  /** Task complexity estimation */
  complexity?: 'low' | 'medium' | 'high';
  /** Estimated duration in milliseconds */
  estimatedDuration?: number;
  /** Related patterns from ReasoningBank */
  patterns?: TaskPattern[];
  /** Potential risks */
  risks?: string[];
  /** Recommendations */
  recommendations?: string[];
}

/**
 * Post-task hook result with learning data
 */
export interface PostTaskHookResult extends HookResult {
  /** Task outcome */
  outcome?: TaskOutcome;
  /** Learning updates applied */
  learningUpdates?: LearningUpdate;
  /** Pattern ID if a new pattern was created */
  patternId?: string;
  /** Trajectory ID for ReasoningBank */
  trajectoryId?: string;
}

/**
 * Agent suggestion for task routing
 */
export interface AgentSuggestion {
  /** Agent type */
  type: string;
  /** Confidence score (0-1) */
  confidence: number;
  /** Reason for suggestion */
  reason: string;
  /** Capabilities relevant to this task */
  capabilities?: string[];
}

/**
 * Task pattern from ReasoningBank
 */
export interface TaskPattern {
  /** Pattern identifier */
  id: string;
  /** Pattern description */
  description: string;
  /** Match score (0-1) */
  matchScore: number;
  /** Historical success rate */
  successRate: number;
  /** Average duration in ms */
  avgDuration: number;
  /** Recommended strategies */
  strategies?: string[];
}

/**
 * Task outcome for learning
 */
export interface TaskOutcome {
  /** Whether the task succeeded */
  success: boolean;
  /** Duration in milliseconds */
  duration: number;
  /** Quality score (0-1) */
  quality?: number;
  /** Error details if failed */
  error?: string;
  /** Output artifacts */
  artifacts?: string[];
  /** Agent that executed the task */
  agent?: string;
}

/**
 * Learning update result
 */
export interface LearningUpdate {
  /** Number of patterns updated */
  patternsUpdated: number;
  /** Number of new patterns created */
  newPatterns: number;
  /** Confidence adjustments made */
  confidenceAdjusted: number;
  /** Trajectories recorded */
  trajectoriesRecorded: number;
}

/**
 * Task store for tracking active tasks
 */
interface TaskStore {
  taskId: string;
  description: string;
  startTime: number;
  metadata?: Record<string, unknown>;
  suggestedAgents?: AgentSuggestion[];
}

/**
 * Task Hooks Manager
 *
 * Manages pre-task and post-task hooks with ReasoningBank integration.
 */
export class TaskHooksManager {
  private registry: HookRegistry;
  private activeTasks: Map<string, TaskStore> = new Map();
  private taskPatterns: Map<string, TaskPattern[]> = new Map();

  constructor(registry: HookRegistry) {
    this.registry = registry;
    this.registerDefaultHooks();
  }

  /**
   * Register default task hooks
   */
  private registerDefaultHooks(): void {
    // Pre-task hook for agent suggestion
    this.registry.register(
      HookEvent.PreTaskExecute,
      this.handlePreTask.bind(this),
      HookPriority.Normal,
      { name: 'task-hooks:pre-task' }
    );

    // Post-task hook for learning
    this.registry.register(
      HookEvent.PostTaskExecute,
      this.handlePostTask.bind(this),
      HookPriority.Normal,
      { name: 'task-hooks:post-task' }
    );
  }

  /**
   * Handle pre-task execution
   */
  async handlePreTask(context: HookContext): Promise<PreTaskHookResult> {
    const task = context.task;
    if (!task) {
      return { success: false, error: new Error('No task in context') };
    }

    // Store task for tracking
    const taskStore: TaskStore = {
      taskId: task.id,
      description: task.description,
      startTime: Date.now(),
      metadata: task.metadata,
    };

    // Analyze task and suggest agents
    const analysis = await this.analyzeTask(task);

    taskStore.suggestedAgents = analysis.suggestedAgents;
    this.activeTasks.set(task.id, taskStore);

    // Store patterns for this task
    if (analysis.patterns.length > 0) {
      this.taskPatterns.set(task.id, analysis.patterns);
    }

    return {
      success: true,
      suggestedAgents: analysis.suggestedAgents,
      complexity: analysis.complexity,
      estimatedDuration: analysis.estimatedDuration,
      patterns: analysis.patterns,
      risks: analysis.risks,
      recommendations: analysis.recommendations,
      data: {
        task: {
          ...task,
          metadata: {
            ...task.metadata,
            suggestedAgents: analysis.suggestedAgents.map(a => a.type),
            complexity: analysis.complexity,
          },
        },
      },
    };
  }

  /**
   * Handle post-task execution
   */
  async handlePostTask(context: HookContext): Promise<PostTaskHookResult> {
    const task = context.task;
    if (!task) {
      return { success: false, error: new Error('No task in context') };
    }

    const taskStore = this.activeTasks.get(task.id);
    const patterns = this.taskPatterns.get(task.id);

    // Calculate duration
    const duration = taskStore ? Date.now() - taskStore.startTime : 0;

    // Extract outcome from context metadata
    const success = context.metadata?.success !== false;
    const quality = context.metadata?.quality as number | undefined;
    const error = context.metadata?.error as string | undefined;
    const agent = context.metadata?.agent as string | undefined;

    const outcome: TaskOutcome = {
      success,
      duration,
      quality,
      error,
      agent,
      artifacts: context.metadata?.artifacts as string[] | undefined,
    };

    // Record learning trajectory
    const learningUpdates = await this.recordLearning(task, outcome, patterns);

    // Clean up
    this.activeTasks.delete(task.id);
    this.taskPatterns.delete(task.id);

    return {
      success: true,
      outcome,
      learningUpdates,
      patternId: learningUpdates.newPatterns > 0 ? `pattern-${task.id}` : undefined,
      trajectoryId: `trajectory-${task.id}-${Date.now()}`,
    };
  }

  /**
   * Analyze task for agent suggestions and patterns
   */
  private async analyzeTask(task: TaskInfo): Promise<{
    suggestedAgents: AgentSuggestion[];
    complexity: 'low' | 'medium' | 'high';
    estimatedDuration: number;
    patterns: TaskPattern[];
    risks: string[];
    recommendations: string[];
  }> {
    const description = task.description.toLowerCase();

    // Pattern-based agent suggestion
    const suggestedAgents: AgentSuggestion[] = [];
    const patterns: TaskPattern[] = [];
    const risks: string[] = [];
    const recommendations: string[] = [];

    // Analyze task keywords for agent routing
    const agentPatterns: Array<{
      keywords: string[];
      agent: string;
      capabilities: string[];
    }> = [
      {
        keywords: ['implement', 'code', 'create', 'build', 'develop', 'write'],
        agent: 'coder',
        capabilities: ['code-generation', 'implementation', 'debugging'],
      },
      {
        keywords: ['test', 'spec', 'coverage', 'unit', 'integration'],
        agent: 'tester',
        capabilities: ['unit-testing', 'integration-testing', 'coverage-analysis'],
      },
      {
        keywords: ['review', 'check', 'audit', 'analyze'],
        agent: 'reviewer',
        capabilities: ['code-review', 'quality-analysis', 'best-practices'],
      },
      {
        keywords: ['research', 'investigate', 'explore', 'study'],
        agent: 'researcher',
        capabilities: ['research', 'analysis', 'documentation'],
      },
      {
        keywords: ['security', 'vulnerability', 'cve', 'threat'],
        agent: 'security-architect',
        capabilities: ['security-analysis', 'vulnerability-detection', 'threat-modeling'],
      },
      {
        keywords: ['performance', 'optimize', 'speed', 'memory'],
        agent: 'performance-engineer',
        capabilities: ['performance-optimization', 'profiling', 'benchmarking'],
      },
      {
        keywords: ['architect', 'design', 'structure', 'pattern'],
        agent: 'core-architect',
        capabilities: ['architecture-design', 'pattern-application', 'system-design'],
      },
      {
        keywords: ['memory', 'storage', 'database', 'cache'],
        agent: 'memory-specialist',
        capabilities: ['memory-management', 'data-persistence', 'caching'],
      },
      {
        keywords: ['swarm', 'coordinate', 'orchestrate', 'agent'],
        agent: 'swarm-specialist',
        capabilities: ['swarm-coordination', 'agent-orchestration', 'distributed-systems'],
      },
    ];

    // Score each agent based on keyword matches
    for (const pattern of agentPatterns) {
      let matchCount = 0;
      for (const keyword of pattern.keywords) {
        if (description.includes(keyword)) {
          matchCount++;
        }
      }

      if (matchCount > 0) {
        const confidence = Math.min(0.3 + matchCount * 0.2, 0.95);
        suggestedAgents.push({
          type: pattern.agent,
          confidence,
          reason: `Matched keywords: ${pattern.keywords.filter(k => description.includes(k)).join(', ')}`,
          capabilities: pattern.capabilities,
        });
      }
    }

    // Sort by confidence
    suggestedAgents.sort((a, b) => b.confidence - a.confidence);

    // If no matches, default to coder
    if (suggestedAgents.length === 0) {
      suggestedAgents.push({
        type: 'coder',
        confidence: 0.5,
        reason: 'Default agent for unclassified tasks',
        capabilities: ['code-generation', 'implementation'],
      });
    }

    // Estimate complexity based on description length and keywords
    let complexity: 'low' | 'medium' | 'high' = 'medium';
    const complexityKeywords = ['complex', 'large', 'multiple', 'refactor', 'redesign', 'critical'];
    const simpleKeywords = ['simple', 'small', 'quick', 'fix', 'minor', 'typo'];

    const hasComplexKeywords = complexityKeywords.some(k => description.includes(k));
    const hasSimpleKeywords = simpleKeywords.some(k => description.includes(k));

    if (hasComplexKeywords) {
      complexity = 'high';
    } else if (hasSimpleKeywords) {
      complexity = 'low';
    } else if (description.length > 200) {
      complexity = 'high';
    } else if (description.length < 50) {
      complexity = 'low';
    }

    // Estimate duration based on complexity
    const durationMap = {
      low: 5 * 60 * 1000,      // 5 minutes
      medium: 30 * 60 * 1000,  // 30 minutes
      high: 2 * 60 * 60 * 1000, // 2 hours
    };
    const estimatedDuration = durationMap[complexity];

    // Detect risks
    if (description.includes('production') || description.includes('live')) {
      risks.push('Task involves production environment');
    }
    if (description.includes('delete') || description.includes('remove')) {
      risks.push('Task involves destructive operations');
    }
    if (description.includes('security') || description.includes('auth')) {
      risks.push('Task involves security-sensitive operations');
    }
    if (description.includes('database') || description.includes('migration')) {
      risks.push('Task involves database changes');
    }

    // Add recommendations
    if (complexity === 'high') {
      recommendations.push('Consider breaking this task into smaller subtasks');
    }
    if (suggestedAgents.length > 1) {
      recommendations.push('Consider using multiple agents for better coverage');
    }
    if (risks.length > 0) {
      recommendations.push('Review risks before proceeding');
    }

    return {
      suggestedAgents,
      complexity,
      estimatedDuration,
      patterns,
      risks,
      recommendations,
    };
  }

  /**
   * Record learning trajectory
   */
  private async recordLearning(
    task: TaskInfo,
    outcome: TaskOutcome,
    patterns?: TaskPattern[]
  ): Promise<LearningUpdate> {
    // In a real implementation, this would integrate with ReasoningBank
    // For now, we track basic statistics

    const learningUpdate: LearningUpdate = {
      patternsUpdated: patterns?.length || 0,
      newPatterns: outcome.success ? 1 : 0,
      confidenceAdjusted: patterns?.length || 0,
      trajectoriesRecorded: 1,
    };

    return learningUpdate;
  }

  /**
   * Execute pre-task hook manually
   */
  async executePreTask(
    taskId: string,
    description: string,
    metadata?: Record<string, unknown>
  ): Promise<PreTaskHookResult> {
    const context: HookContext = {
      event: HookEvent.PreTaskExecute,
      timestamp: new Date(),
      task: {
        id: taskId,
        description,
        metadata,
      },
    };

    return this.handlePreTask(context);
  }

  /**
   * Execute post-task hook manually
   */
  async executePostTask(
    taskId: string,
    success: boolean,
    metadata?: Record<string, unknown>
  ): Promise<PostTaskHookResult> {
    const taskStore = this.activeTasks.get(taskId);

    const context: HookContext = {
      event: HookEvent.PostTaskExecute,
      timestamp: new Date(),
      task: {
        id: taskId,
        description: taskStore?.description || 'Unknown task',
        metadata: taskStore?.metadata,
      },
      metadata: {
        ...metadata,
        success,
      },
    };

    return this.handlePostTask(context);
  }

  /**
   * Get active tasks
   */
  getActiveTasks(): Map<string, TaskStore> {
    return new Map(this.activeTasks);
  }

  /**
   * Clear all active tasks
   */
  clearActiveTasks(): void {
    this.activeTasks.clear();
    this.taskPatterns.clear();
  }
}

/**
 * Create task hooks manager
 */
export function createTaskHooksManager(registry: HookRegistry): TaskHooksManager {
  return new TaskHooksManager(registry);
}

/**
 * V3 Hooks System - Type Definitions
 *
 * Provides extensible hook points for tool execution, file operations,
 * and session lifecycle events. Integrates with event bus for coordination.
 *
 * @module v3/shared/hooks/types
 */

/**
 * Hook event types
 */
export enum HookEvent {
  // Tool execution hooks
  PreToolUse = 'hook:pre-tool-use',
  PostToolUse = 'hook:post-tool-use',

  // File operation hooks
  PreEdit = 'hook:pre-edit',
  PostEdit = 'hook:post-edit',
  PreRead = 'hook:pre-read',
  PostRead = 'hook:post-read',
  PreWrite = 'hook:pre-write',
  PostWrite = 'hook:post-write',

  // Command execution hooks
  PreCommand = 'hook:pre-command',
  PostCommand = 'hook:post-command',

  // Session lifecycle hooks
  SessionStart = 'hook:session-start',
  SessionEnd = 'hook:session-end',
  SessionPause = 'hook:session-pause',
  SessionResume = 'hook:session-resume',

  // Agent lifecycle hooks
  PreAgentSpawn = 'hook:pre-agent-spawn',
  PostAgentSpawn = 'hook:post-agent-spawn',
  PreAgentTerminate = 'hook:pre-agent-terminate',
  PostAgentTerminate = 'hook:post-agent-terminate',

  // Task lifecycle hooks
  PreTaskExecute = 'hook:pre-task-execute',
  PostTaskExecute = 'hook:post-task-execute',
  PreTaskComplete = 'hook:pre-task-complete',
  PostTaskComplete = 'hook:post-task-complete',

  // Memory hooks
  PreMemoryStore = 'hook:pre-memory-store',
  PostMemoryStore = 'hook:post-memory-store',
  PreMemoryRetrieve = 'hook:pre-memory-retrieve',
  PostMemoryRetrieve = 'hook:post-memory-retrieve',

  // Error hooks
  OnError = 'hook:on-error',
  OnWarning = 'hook:on-warning',
}

/**
 * Hook priority levels (higher = earlier execution)
 */
export enum HookPriority {
  Critical = 1000,
  High = 500,
  Normal = 0,
  Low = -500,
  Lowest = -1000,
}

/**
 * Tool information for tool-related hooks
 */
export interface ToolInfo {
  /** Tool name (e.g., 'Read', 'Write', 'Bash') */
  name: string;

  /** Tool parameters */
  parameters: Record<string, unknown>;

  /** Estimated execution time in ms */
  estimatedDuration?: number;

  /** Tool category */
  category?: 'file' | 'bash' | 'search' | 'edit' | 'git' | 'other';
}

/**
 * Command information for command-related hooks
 */
export interface CommandInfo {
  /** Command string */
  command: string;

  /** Working directory */
  cwd?: string;

  /** Environment variables */
  env?: Record<string, string>;

  /** Command timeout in ms */
  timeout?: number;

  /** Whether command is destructive */
  isDestructive?: boolean;
}

/**
 * File operation information
 */
export interface FileOperationInfo {
  /** File path */
  path: string;

  /** Operation type */
  operation: 'read' | 'write' | 'edit' | 'delete';

  /** File content (for write/edit operations) */
  content?: string;

  /** Previous content (for edit operations) */
  previousContent?: string;

  /** File size in bytes */
  size?: number;
}

/**
 * Session information
 */
export interface SessionInfo {
  /** Session ID */
  id: string;

  /** Session start time */
  startTime: Date;

  /** Session end time */
  endTime?: Date;

  /** Session metadata */
  metadata?: Record<string, unknown>;

  /** User ID (if available) */
  userId?: string;
}

/**
 * Agent information
 */
export interface AgentInfo {
  /** Agent ID */
  id: string;

  /** Agent type/role */
  type: string;

  /** Agent configuration */
  config?: Record<string, unknown>;

  /** Parent agent ID */
  parentId?: string;
}

/**
 * Task information
 */
export interface TaskInfo {
  /** Task ID */
  id: string;

  /** Task description */
  description: string;

  /** Task priority */
  priority?: number;

  /** Assigned agent ID */
  agentId?: string;

  /** Task metadata */
  metadata?: Record<string, unknown>;
}

/**
 * Memory operation information
 */
export interface MemoryInfo {
  /** Memory key */
  key: string;

  /** Memory value */
  value?: unknown;

  /** Memory namespace */
  namespace?: string;

  /** TTL in seconds */
  ttl?: number;
}

/**
 * Error information
 */
export interface ErrorInfo {
  /** Error object */
  error: Error;

  /** Error context */
  context?: string;

  /** Error severity */
  severity: 'warning' | 'error' | 'fatal';

  /** Recoverable flag */
  recoverable: boolean;
}

/**
 * Hook context - contains information about the event being hooked
 */
export interface HookContext {
  /** Event type */
  event: HookEvent;

  /** Timestamp when hook was triggered */
  timestamp: Date;

  /** Correlation ID for tracking related events */
  correlationId?: string;

  /** Tool information (for tool hooks) */
  tool?: ToolInfo;

  /** Command information (for command hooks) */
  command?: CommandInfo;

  /** File operation information (for file hooks) */
  file?: FileOperationInfo;

  /** Session information (for session hooks) */
  session?: SessionInfo;

  /** Agent information (for agent hooks) */
  agent?: AgentInfo;

  /** Task information (for task hooks) */
  task?: TaskInfo;

  /** Memory information (for memory hooks) */
  memory?: MemoryInfo;

  /** Error information (for error hooks) */
  error?: ErrorInfo;

  /** Additional metadata */
  metadata?: Record<string, unknown>;
}

/**
 * Hook result - returned by hook handlers
 */
export interface HookResult {
  /** Whether the hook succeeded */
  success: boolean;

  /** Result data (can modify context) */
  data?: Partial<HookContext>;

  /** Error if hook failed */
  error?: Error;

  /** Whether to continue executing other hooks */
  continueChain?: boolean;

  /** Whether to abort the operation */
  abort?: boolean;

  /** Hook execution time in ms */
  executionTime?: number;

  /** Additional metadata */
  metadata?: Record<string, unknown>;
}

/**
 * Hook handler function type
 */
export type HookHandler = (context: HookContext) => Promise<HookResult> | HookResult;

/**
 * Hook definition with metadata
 */
export interface HookDefinition {
  /** Unique hook ID */
  id: string;

  /** Hook event type */
  event: HookEvent;

  /** Hook handler function */
  handler: HookHandler;

  /** Hook priority */
  priority: HookPriority;

  /** Hook name/description */
  name?: string;

  /** Whether hook is enabled */
  enabled: boolean;

  /** Hook timeout in ms */
  timeout?: number;

  /** Hook metadata */
  metadata?: Record<string, unknown>;
}

/**
 * Hook statistics
 */
export interface HookStats {
  /** Total hooks registered */
  totalHooks: number;

  /** Hooks by event type */
  byEvent: Record<HookEvent, number>;

  /** Total executions */
  totalExecutions: number;

  /** Total failures */
  totalFailures: number;

  /** Average execution time in ms */
  avgExecutionTime: number;

  /** Total execution time in ms */
  totalExecutionTime: number;
}

/**
 * Hook execution options
 */
export interface HookExecutionOptions {
  /** Timeout in ms (overrides hook-specific timeout) */
  timeout?: number;

  /** Whether to continue on error */
  continueOnError?: boolean;

  /** Maximum parallel executions */
  maxParallel?: number;

  /** Whether to collect results from all hooks */
  collectResults?: boolean;
}

