};

/**
 * MCP Server Interface
 */
export interface IMCPServer {
  start(): Promise<void>;
  stop(): Promise<void>;
  registerTool(tool: MCPTool): boolean;
  registerTools(tools: MCPTool[]): { registered: number; failed: string[] };
  getHealthStatus(): Promise<{
    healthy: boolean;
    error?: string;
    metrics?: Record<string, number>;
  }>;
  getMetrics(): MCPServerMetrics;
  getSessions(): MCPSession[];
  getSession(sessionId: string): MCPSession | undefined;
  terminateSession(sessionId: string): boolean;
}

/**
 * V3 MCP Server
 */
export class MCPServer extends EventEmitter implements IMCPServer {
  private readonly config: MCPServerConfig;
  private readonly toolRegistry: ToolRegistry;
  private readonly sessionManager: SessionManager;
  private readonly connectionPool?: ConnectionPool;
  private readonly transportManager: TransportManager;
  private transport?: ITransport;
  private running = false;
  private startTime?: Date;
  private startupDuration?: number;
  private currentSession?: MCPSession;

  // Server information
  private readonly serverInfo = {
    name: 'Claude-Flow MCP Server V3',
    version: '3.0.0',
  };

  // MCP protocol version — spec-required YYYY-MM-DD date string (#1874).
  // Claude Code's Zod validator rejects any other shape.
  private readonly protocolVersion: MCPProtocolVersion = '2024-11-05';

  // Server capabilities
  private readonly capabilities: MCPCapabilities = {
    logging: { level: 'info' },
    tools: { listChanged: true },
    resources: { listChanged: false, subscribe: false },
    prompts: { listChanged: false },
  };

  // Request statistics
  private requestStats = {
    total: 0,
    successful: 0,
    failed: 0,
    totalResponseTime: 0,
  };

  constructor(
    config: Partial<MCPServerConfig>,
    private readonly logger: ILogger,
    private readonly orchestrator?: unknown,
    private readonly swarmCoordinator?: unknown
  ) {
    super();
    this.config = { ...DEFAULT_CONFIG, ...config } as MCPServerConfig;

    // Initialize components
    this.toolRegistry = createToolRegistry(logger);
    this.sessionManager = createSessionManager(logger, {
      maxSessions: 100,
      sessionTimeout: 30 * 60 * 1000,
    });
    this.transportManager = createTransportManager(logger);

    // Initialize connection pool if enabled
    if (this.config.connectionPool) {
      this.connectionPool = createConnectionPool(
        this.config.connectionPool,
        logger,
        this.config.transport
      );
    }

    // Setup event handlers
    this.setupEventHandlers();
  }

  /**
   * Start the MCP server
   */
  async start(): Promise<void> {
    if (this.running) {
      throw new MCPServerError('Server already running');
    }

    const startTime = performance.now();
    this.startTime = new Date();

    this.logger.info('Starting MCP server', {
      name: this.config.name,
      version: this.config.version,
      transport: this.config.transport,
    });

    try {
      // Create and start transport
      this.transport = createTransport(this.config.transport, this.logger, {
        type: this.config.transport,
        host: this.config.host,
        port: this.config.port,
        corsEnabled: this.config.corsEnabled,
        corsOrigins: this.config.corsOrigins,
        auth: this.config.auth,
        maxRequestSize: String(this.config.maxRequestSize),
        requestTimeout: this.config.requestTimeout,
      } as any);

      // Setup request handler
      this.transport.onRequest(async (request) => {
        return await this.handleRequest(request);
      });

      // Setup notification handler
      this.transport.onNotification(async (notification) => {
        await this.handleNotification(notification);
      });

      // Start transport
      await this.transport.start();

      // Register built-in tools
      await this.registerBuiltInTools();

      this.running = true;
      this.startupDuration = performance.now() - startTime;

      this.logger.info('MCP server started', {
        startupTime: `${this.startupDuration.toFixed(2)}ms`,
        tools: this.toolRegistry.getToolCount(),
      });

      this.emit('server:started', {
        startupTime: this.startupDuration,
        tools: this.toolRegistry.getToolCount(),
      });

    } catch (error) {
      this.logger.error('Failed to start MCP server', { error });
      throw new MCPServerError('Failed to start server', ErrorCodes.INTERNAL_ERROR, { error });
    }
  }

  /**
   * Stop the MCP server
   */
  async stop(): Promise<void> {
    if (!this.running) {
      return;
    }

    this.logger.info('Stopping MCP server');

    try {
      // Stop transport
      if (this.transport) {
        await this.transport.stop();
        this.transport = undefined;
      }

      // Clear sessions
      this.sessionManager.clearAll();

      // Clear connection pool
      if (this.connectionPool) {
        await this.connectionPool.clear();
      }

      this.running = false;
      this.currentSession = undefined;

      this.logger.info('MCP server stopped');
      this.emit('server:stopped');

    } catch (error) {
      this.logger.error('Error stopping MCP server', { error });
      throw error;
    }
  }

  /**
   * Register a tool
   */
  registerTool(tool: MCPTool): boolean {
    return this.toolRegistry.register(tool);
  }

  /**
   * Register multiple tools
   */
  registerTools(tools: MCPTool[]): { registered: number; failed: string[] } {
    return this.toolRegistry.registerBatch(tools);
  }

  /**
   * Unregister a tool
   */
  unregisterTool(name: string): boolean {
    return this.toolRegistry.unregister(name);
  }

  /**
   * Get health status
   */
  async getHealthStatus(): Promise<{
    healthy: boolean;
    error?: string;
    metrics?: Record<string, number>;
  }> {
    try {
      const transportHealth = this.transport
        ? await this.transport.getHealthStatus()
        : { healthy: false, error: 'Transport not initialized' };

      const sessionMetrics = this.sessionManager.getSessionMetrics();
      const poolStats = this.connectionPool?.getStats();

      const metrics: Record<string, number> = {
        registeredTools: this.toolRegistry.getToolCount(),
        totalRequests: this.requestStats.total,
        successfulRequests: this.requestStats.successful,
        failedRequests: this.requestStats.failed,
        totalSessions: sessionMetrics.total,
        activeSessions: sessionMetrics.active,
        ...(transportHealth.metrics || {}),
      };

      if (poolStats) {
        metrics.poolConnections = poolStats.totalConnections;
        metrics.poolIdleConnections = poolStats.idleConnections;
        metrics.poolBusyConnections = poolStats.busyConnections;
      }

      return {
        healthy: this.running && transportHealth.healthy,
        error: transportHealth.error,
        metrics,
      };

    } catch (error) {
      return {
        healthy: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Get server metrics
   */
  getMetrics(): MCPServerMetrics {
    const sessionMetrics = this.sessionManager.getSessionMetrics();
    const registryStats = this.toolRegistry.getStats();

    return {
      totalRequests: this.requestStats.total,
      successfulRequests: this.requestStats.successful,
      failedRequests: this.requestStats.failed,
      averageResponseTime: this.requestStats.total > 0
        ? this.requestStats.totalResponseTime / this.requestStats.total
        : 0,
      activeSessions: sessionMetrics.active,
      toolInvocations: Object.fromEntries(
        registryStats.topTools.map((t) => [t.name, t.calls])
      ),
      errors: {},
      lastReset: this.startTime || new Date(),
      startupTime: this.startupDuration,
      uptime: this.startTime ? Date.now() - this.startTime.getTime() : 0,
    };
  }

  /**
   * Get all sessions
   */
  getSessions(): MCPSession[] {
    return this.sessionManager.getActiveSessions();
  }

  /**
   * Get session by ID
   */
  getSession(sessionId: string): MCPSession | undefined {
    return this.sessionManager.getSession(sessionId);
  }

  /**
   * Terminate a session
   */
  terminateSession(sessionId: string): boolean {
    const result = this.sessionManager.closeSession(sessionId, 'Terminated by server');
    if (this.currentSession?.id === sessionId) {
      this.currentSession = undefined;
    }
    return result;
  }

  /**
   * Handle incoming request
   */
  private async handleRequest(request: MCPRequest): Promise<MCPResponse> {
    const startTime = performance.now();
    this.requestStats.total++;

    this.logger.debug('Handling request', {
      id: request.id,
      method: request.method,
    });

    try {
      // Handle initialization
      if (request.method === 'initialize') {
        return await this.handleInitialize(request);
      }

      // Get or create session
      const session = this.getOrCreateSession();

      // Check initialization
      if (!session.isInitialized && request.method !== 'initialized') {
        return this.createErrorResponse(
          request.id,
          ErrorCodes.SERVER_NOT_INITIALIZED,
          'Server not initialized'
        );
      }

      // Update session activity
      this.sessionManager.updateActivity(session.id);

      // Route request
      const response = await this.routeRequest(request);

      const duration = performance.now() - startTime;
      this.requestStats.successful++;
      this.requestStats.totalResponseTime += duration;

      this.logger.debug('Request completed', {
        id: request.id,
        method: request.method,
        duration: `${duration.toFixed(2)}ms`,
      });

      return response;

    } catch (error) {
      const duration = performance.now() - startTime;
      this.requestStats.failed++;
      this.requestStats.totalResponseTime += duration;

      this.logger.error('Request failed', {
        id: request.id,
        method: request.method,
        error,
      });

      return this.createErrorResponse(
        request.id,
        ErrorCodes.INTERNAL_ERROR,
        error instanceof Error ? error.message : 'Internal error'
      );
    }
  }

  /**
   * Handle notification
   */
  private async handleNotification(notification: MCPNotification): Promise<void> {
    this.logger.debug('Handling notification', { method: notification.method });

    switch (notification.method) {
      case 'initialized':
        this.logger.info('Client initialized notification received');
        break;

      case 'notifications/cancelled':
        this.logger.debug('Request cancelled', notification.params);
        break;

      default:
        this.logger.debug('Unknown notification', { method: notification.method });
    }
  }

  /**
   * Handle initialize request
   */
  private async handleInitialize(request: MCPRequest): Promise<MCPResponse> {
    const params = request.params as unknown as MCPInitializeParams | undefined;

    if (!params) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        'Invalid params'
      );
    }

    // Create and initialize session
    const session = this.sessionManager.createSession(this.config.transport);
    this.sessionManager.initializeSession(session.id, params);
    this.currentSession = session;

    const result: MCPInitializeResult = {
      protocolVersion: this.protocolVersion,
      capabilities: this.capabilities,
      serverInfo: this.serverInfo,
      instructions: 'Claude-Flow MCP Server V3 ready for tool execution',
    };

    this.logger.info('Session initialized', {
      sessionId: session.id,
      clientInfo: params.clientInfo,
    });

    return {
      jsonrpc: '2.0',
      id: request.id,
      result,
    };
  }

  /**
   * Route request to appropriate handler
   */
  private async routeRequest(request: MCPRequest): Promise<MCPResponse> {
    switch (request.method) {
      case 'tools/list':
        return this.handleToolsList(request);

      case 'tools/call':
        return this.handleToolsCall(request);

      case 'resources/list':
        return this.handleResourcesList(request);

      case 'prompts/list':
        return this.handlePromptsList(request);

      case 'ping':
        return {
          jsonrpc: '2.0',
          id: request.id,
          result: { pong: true, timestamp: Date.now() },
        };

      default:
        // Try to execute as tool call (backwards compatibility)
        if (this.toolRegistry.hasTool(request.method)) {
          return this.handleToolExecution(request);
        }

        return this.createErrorResponse(
          request.id,
          ErrorCodes.METHOD_NOT_FOUND,
          `Method not found: ${request.method}`
        );
    }
  }

  /**
   * Handle tools/list request
   */
  private handleToolsList(request: MCPRequest): MCPResponse {
    const tools = this.toolRegistry.listTools().map((t) => ({
      name: t.name,
      description: t.description,
      inputSchema: this.toolRegistry.getTool(t.name)?.inputSchema,
    }));

    return {
      jsonrpc: '2.0',
      id: request.id,
      result: { tools },
    };
  }

  /**
   * Handle tools/call request
   */
  private async handleToolsCall(request: MCPRequest): Promise<MCPResponse> {
    const params = request.params as { name: string; arguments?: Record<string, unknown> };

    if (!params?.name) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        'Tool name is required'
      );
    }

    const context: ToolContext = {
      sessionId: this.currentSession?.id || 'unknown',
      requestId: request.id,
      orchestrator: this.orchestrator,
      swarmCoordinator: this.swarmCoordinator,
    };

    const result = await this.toolRegistry.execute(
      params.name,
      params.arguments || {},
      context
    );

    return {
      jsonrpc: '2.0',
      id: request.id,
      result,
    };
  }

  /**
   * Handle direct tool execution (backwards compatibility)
   */
  private async handleToolExecution(request: MCPRequest): Promise<MCPResponse> {
    const context: ToolContext = {
      sessionId: this.currentSession?.id || 'unknown',
      requestId: request.id,
      orchestrator: this.orchestrator,
      swarmCoordinator: this.swarmCoordinator,
    };

    const result = await this.toolRegistry.execute(
      request.method,
      (request.params as Record<string, unknown>) || {},
      context
    );

    return {
      jsonrpc: '2.0',
      id: request.id,
      result,
    };
  }

  /**
   * Handle resources/list request
   */
  private handleResourcesList(request: MCPRequest): MCPResponse {
    return {
      jsonrpc: '2.0',
      id: request.id,
      result: { resources: [] },
    };
  }

  /**
   * Handle prompts/list request
   */
  private handlePromptsList(request: MCPRequest): MCPResponse {
    return {
      jsonrpc: '2.0',
      id: request.id,
      result: { prompts: [] },
    };
  }

  /**
   * Get or create current session
   */
  private getOrCreateSession(): MCPSession {
    if (this.currentSession) {
      return this.currentSession;
    }

    const session = this.sessionManager.createSession(this.config.transport);
    this.currentSession = session;
    return session;
  }

  /**
   * Create error response
   */
  private createErrorResponse(
    id: string | number | null,
    code: number,
    message: string
  ): MCPResponse {
    return {
      jsonrpc: '2.0',
      id,
      error: { code, message },
    };
  }

  /**
   * Register built-in tools
   */
  private async registerBuiltInTools(): Promise<void> {
    // System info tool
    this.registerTool({
      name: 'system/info',
      description: 'Get system information',
      inputSchema: { type: 'object', properties: {} },
      handler: async () => ({
        name: this.serverInfo.name,
        version: this.serverInfo.version,
        platform: platform(),
        arch: arch(),
        runtime: 'Node.js',
        uptime: this.startTime ? Date.now() - this.startTime.getTime() : 0,
      }),
      category: 'system',
    });

    // Health check tool
    this.registerTool({
      name: 'system/health',
      description: 'Get system health status',
      inputSchema: { type: 'object', properties: {} },
      handler: async () => await this.getHealthStatus(),
      category: 'system',
      cacheable: true,
      cacheTTL: 2000,
    });

    // Metrics tool
    this.registerTool({
      name: 'system/metrics',
      description: 'Get server metrics',
      inputSchema: { type: 'object', properties: {} },
      handler: async () => this.getMetrics(),
      category: 'system',
      cacheable: true,
      cacheTTL: 1000,
    });

    // Tools list tool
    this.registerTool({
      name: 'tools/list-detailed',
      description: 'List all registered tools with details',
      inputSchema: {
        type: 'object',
        properties: {
          category: { type: 'string', description: 'Filter by category' },
        },
      },
      handler: async (input: unknown) => {
        const params = input as { category?: string };
        if (params.category) {
          return this.toolRegistry.getByCategory(params.category);
        }
        return this.toolRegistry.listTools();
      },
      category: 'system',
    });

    this.logger.info('Built-in tools registered', {
      count: 4,
    });
  }

  /**
   * Setup event handlers
   */
  private setupEventHandlers(): void {
    // Tool events
    this.toolRegistry.on('tool:registered', (name) => {
      this.emit('tool:registered', name);
    });

    this.toolRegistry.on('tool:called', (data) => {
      this.emit('tool:called', data);
    });

    this.toolRegistry.on('tool:completed', (data) => {
      this.emit('tool:completed', data);
    });

    this.toolRegistry.on('tool:error', (data) => {
      this.emit('tool:error', data);
    });

    // Session events
    this.sessionManager.on('session:created', (session) => {
      this.emit('session:created', session);
    });

    this.sessionManager.on('session:closed', (data) => {
      this.emit('session:closed', data);
    });

    this.sessionManager.on('session:expired', (session) => {
      this.emit('session:expired', session);
    });
  }
}

/**
 * Create an MCP server instance
 */
export function createMCPServer(
  config: Partial<MCPServerConfig>,
  logger: ILogger,
  orchestrator?: unknown,
  swarmCoordinator?: unknown
): MCPServer {
  return new MCPServer(config, logger, orchestrator, swarmCoordinator);
}

/**
 * V3 MCP Session Manager
 *
 * Manages MCP sessions with:
 * - Session lifecycle management
 * - Authentication integration
 * - Session timeout handling
 * - Concurrent session support
 * - Session metrics and monitoring
 *
 * Performance Targets:
 * - Session creation: <5ms
 * - Session lookup: <1ms
 * - Session cleanup: <10ms
 */

import { EventEmitter } from 'events';
import {
  MCPSession,
  SessionState,
  SessionMetrics,
  MCPInitializeParams,
  MCPCapabilities,
  MCPClientInfo,
  MCPProtocolVersion,
  TransportType,
  ILogger,
} from './types.js';

/**
 * Session configuration
 */
export interface SessionConfig {
  maxSessions?: number;
  sessionTimeout?: number;
  cleanupInterval?: number;
  enableMetrics?: boolean;
}

/**
 * Default session configuration
 */
const DEFAULT_SESSION_CONFIG: Required<SessionConfig> = {
  maxSessions: 100,
  sessionTimeout: 30 * 60 * 1000, // 30 minutes
  cleanupInterval: 60 * 1000, // 1 minute
  enableMetrics: true,
};

/**
 * Session Manager
 *
 * Handles creation, tracking, and cleanup of MCP sessions
 */
export class SessionManager extends EventEmitter {
  private readonly sessions: Map<string, MCPSession> = new Map();
  private readonly config: Required<SessionConfig>;
  private cleanupTimer?: NodeJS.Timeout;
  private sessionCounter = 0;

  // Statistics
  private totalCreated = 0;
  private totalClosed = 0;
  private totalExpired = 0;

  constructor(
    private readonly logger: ILogger,
    config: SessionConfig = {}
  ) {
    super();
    this.config = { ...DEFAULT_SESSION_CONFIG, ...config };
    this.startCleanupTimer();
  }

  /**
   * Create a new session
   */
  createSession(transport: TransportType): MCPSession {
    // Check max sessions
    if (this.sessions.size >= this.config.maxSessions) {
      throw new Error(`Maximum sessions (${this.config.maxSessions}) reached`);
    }

    const id = this.generateSessionId();
    const now = new Date();

    const session: MCPSession = {
      id,
      state: 'created',
      transport,
      createdAt: now,
      lastActivityAt: now,
      isInitialized: false,
      isAuthenticated: false,
    };

    this.sessions.set(id, session);
    this.totalCreated++;

    this.logger.debug('Session created', { id, transport });
    this.emit('session:created', session);

    return session;
  }

  /**
   * Initialize a session with client information
   */
  initializeSession(
    sessionId: string,
    params: MCPInitializeParams
  ): MCPSession | undefined {
    const session = this.sessions.get(sessionId);
    if (!session) {
      this.logger.warn('Session not found for initialization', { sessionId });
      return undefined;
    }

    session.state = 'ready';
    session.isInitialized = true;
    session.clientInfo = params.clientInfo;
    session.protocolVersion = params.protocolVersion;
    session.capabilities = params.capabilities;
    session.lastActivityAt = new Date();

    this.logger.info('Session initialized', {
      sessionId,
      clientInfo: params.clientInfo,
      protocolVersion: params.protocolVersion,
    });

    this.emit('session:initialized', session);
    return session;
  }

  /**
   * Authenticate a session
   */
  authenticateSession(sessionId: string): boolean {
    const session = this.sessions.get(sessionId);
    if (!session) {
      return false;
    }

    session.isAuthenticated = true;
    session.lastActivityAt = new Date();

    this.logger.debug('Session authenticated', { sessionId });
    this.emit('session:authenticated', session);

    return true;
  }

  /**
   * Get a session by ID
   */
  getSession(sessionId: string): MCPSession | undefined {
    return this.sessions.get(sessionId);
  }

  /**
   * Check if session exists
   */
  hasSession(sessionId: string): boolean {
    return this.sessions.has(sessionId);
  }

  /**
   * Get all active sessions
   */
  getActiveSessions(): MCPSession[] {
    return Array.from(this.sessions.values()).filter(
      (s) => s.state === 'ready' || s.state === 'created' || s.state === 'initializing'
    );
  }

  /**
   * Update session activity timestamp
   */
  updateActivity(sessionId: string): boolean {
    const session = this.sessions.get(sessionId);
    if (!session) {
      return false;
    }

    session.lastActivityAt = new Date();
    return true;
  }

  /**
   * Set session state
   */
  setState(sessionId: string, state: SessionState): boolean {
    const session = this.sessions.get(sessionId);
    if (!session) {
      return false;
    }

    const oldState = session.state;
    session.state = state;
    session.lastActivityAt = new Date();

    this.logger.debug('Session state changed', {
      sessionId,
      oldState,
      newState: state,
    });

    this.emit('session:stateChanged', { session, oldState, newState: state });
    return true;
  }

  /**
   * Set session metadata
   */
  setMetadata(sessionId: string, key: string, value: unknown): boolean {
    const session = this.sessions.get(sessionId);
    if (!session) {
      return false;
    }

    if (!session.metadata) {
      session.metadata = {};
    }
    session.metadata[key] = value;
    session.lastActivityAt = new Date();

    return true;
  }

  /**
   * Get session metadata
   */
  getMetadata(sessionId: string, key: string): unknown {
    const session = this.sessions.get(sessionId);
    return session?.metadata?.[key];
  }

  /**
   * Close a session
   */
  closeSession(sessionId: string, reason?: string): boolean {
    const session = this.sessions.get(sessionId);
    if (!session) {
      return false;
    }

    session.state = 'closed';
    this.sessions.delete(sessionId);
    this.totalClosed++;

    this.logger.info('Session closed', { sessionId, reason });
    this.emit('session:closed', { session, reason });

    return true;
  }

  /**
   * Remove a session (alias for closeSession)
   */
  removeSession(sessionId: string): boolean {
    return this.closeSession(sessionId);
  }

  /**
   * Get session metrics
   */
  getSessionMetrics(): SessionMetrics {
    let authenticated = 0;
    let active = 0;

    for (const session of this.sessions.values()) {
      if (session.isAuthenticated) authenticated++;
      if (session.state === 'ready') active++;
    }

    return {
      total: this.sessions.size,
      active,
      authenticated,
      expired: this.totalExpired,
    };
  }

  /**
   * Get detailed statistics
   */
  getStats(): {
    total: number;
    byState: Record<SessionState, number>;
    byTransport: Record<TransportType, number>;
    totalCreated: number;
    totalClosed: number;
    totalExpired: number;
    oldestSession?: Date;
    newestSession?: Date;
  } {
    const byState: Record<string, number> = {
      created: 0,
      initializing: 0,
      ready: 0,
      closing: 0,
      closed: 0,
      error: 0,
    };

    const byTransport: Record<string, number> = {
      stdio: 0,
      http: 0,
      websocket: 0,
      'in-process': 0,
    };

    let oldest: Date | undefined;
    let newest: Date | undefined;

    for (const session of this.sessions.values()) {
      byState[session.state] = (byState[session.state] || 0) + 1;
      byTransport[session.transport] = (byTransport[session.transport] || 0) + 1;

      if (!oldest || session.createdAt < oldest) {
        oldest = session.createdAt;
      }
      if (!newest || session.createdAt > newest) {
        newest = session.createdAt;
      }
    }

    return {
      total: this.sessions.size,
      byState: byState as Record<SessionState, number>,
      byTransport: byTransport as Record<TransportType, number>,
      totalCreated: this.totalCreated,
      totalClosed: this.totalClosed,
      totalExpired: this.totalExpired,
      oldestSession: oldest,
      newestSession: newest,
    };
  }

  /**
   * Clean up expired sessions
   */
  cleanupExpiredSessions(): number {
    const now = Date.now();
    const expired: string[] = [];

    for (const [id, session] of this.sessions) {
      const inactiveTime = now - session.lastActivityAt.getTime();
      if (inactiveTime > this.config.sessionTimeout) {
        expired.push(id);
      }
    }

    for (const id of expired) {
      const session = this.sessions.get(id);
      if (session) {
        session.state = 'closed';
        this.sessions.delete(id);
        this.totalExpired++;
        this.logger.info('Session expired', { sessionId: id });
        this.emit('session:expired', session);
      }
    }

    if (expired.length > 0) {
      this.logger.info('Cleaned up expired sessions', { count: expired.length });
    }

    return expired.length;
  }

  /**
   * Start cleanup timer
   */
  private startCleanupTimer(): void {
    this.cleanupTimer = setInterval(() => {
      this.cleanupExpiredSessions();
    }, this.config.cleanupInterval);
  }

  /**
   * Stop cleanup timer
   */
  private stopCleanupTimer(): void {
    if (this.cleanupTimer) {
      clearInterval(this.cleanupTimer);
      this.cleanupTimer = undefined;
    }
  }

  /**
   * Generate a unique session ID
   */
  private generateSessionId(): string {
    return `session-${++this.sessionCounter}-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`;
  }

  /**
   * Clear all sessions
   */
  clearAll(): void {
    for (const id of this.sessions.keys()) {
      this.closeSession(id, 'Session manager cleared');
    }
    this.logger.info('All sessions cleared');
  }

  /**
   * Destroy the session manager
   */
  destroy(): void {
    this.stopCleanupTimer();
    this.clearAll();
    this.removeAllListeners();
    this.logger.info('Session manager destroyed');
  }
}

/**
 * Create a session manager
 */
export function createSessionManager(
  logger: ILogger,
  config?: SessionConfig
): SessionManager {
  return new SessionManager(logger, config);
}

/**
 * V3 MCP Tool Registry
 *
 * High-performance tool management with:
 * - Fast O(1) lookup using Map
 * - Category-based organization
 * - Tool validation on registration
 * - Dynamic registration/unregistration
 * - Caching for frequently used tools
 *
 * Performance Targets:
 * - Tool registration: <10ms
 * - Tool lookup: <1ms
 * - Tool validation: <5ms
 */

import { EventEmitter } from 'events';
import {
  MCPTool,
  JSONSchema,
  ToolHandler,
  ToolContext,
  ToolCallResult,
  ToolRegistrationOptions,
  ILogger,
} from './types.js';

/**
 * Tool metadata for enhanced lookup
 */
interface ToolMetadata {
  tool: MCPTool;
  registeredAt: Date;
  callCount: number;
  lastCalled?: Date;
  avgExecutionTime: number;
  errorCount: number;
}

/**
 * Tool search options
 */
interface ToolSearchOptions {
  category?: string;
  tags?: string[];
  deprecated?: boolean;
  cacheable?: boolean;
}

/**
 * Tool Registry
 *
 * Manages registration, lookup, and execution of MCP tools
 */
export class ToolRegistry extends EventEmitter {
  private readonly tools: Map<string, ToolMetadata> = new Map();
  private readonly categoryIndex: Map<string, Set<string>> = new Map();
  private readonly tagIndex: Map<string, Set<string>> = new Map();
  private defaultContext?: ToolContext;

  // Performance tracking
  private totalRegistrations = 0;
  private totalLookups = 0;
  private totalExecutions = 0;

  constructor(private readonly logger: ILogger) {
    super();
  }

  /**
   * Register a tool
   */
  register(tool: MCPTool, options: ToolRegistrationOptions = {}): boolean {
    const startTime = performance.now();

    // Check for existing tool
    if (this.tools.has(tool.name) && !options.override) {
      this.logger.warn('Tool already registered', { name: tool.name });
      return false;
    }

    // Validate tool if requested
    if (options.validate !== false) {
      const validation = this.validateTool(tool);
      if (!validation.valid) {
        this.logger.error('Tool validation failed', {
          name: tool.name,
          errors: validation.errors,
        });
        return false;
      }
    }

    // Create metadata
    const metadata: ToolMetadata = {
      tool,
      registeredAt: new Date(),
      callCount: 0,
      avgExecutionTime: 0,
      errorCount: 0,
    };

    // Register tool
    this.tools.set(tool.name, metadata);
    this.totalRegistrations++;

    // Update category index
    if (tool.category) {
      if (!this.categoryIndex.has(tool.category)) {
        this.categoryIndex.set(tool.category, new Set());
      }
      this.categoryIndex.get(tool.category)!.add(tool.name);
    }

    // Update tag index
    if (tool.tags) {
      for (const tag of tool.tags) {
        if (!this.tagIndex.has(tag)) {
          this.tagIndex.set(tag, new Set());
        }
        this.tagIndex.get(tag)!.add(tool.name);
      }
    }

    const duration = performance.now() - startTime;
    this.logger.debug('Tool registered', {
      name: tool.name,
      category: tool.category,
      duration: `${duration.toFixed(2)}ms`,
    });

    this.emit('tool:registered', tool.name);
    return true;
  }

  /**
   * Register multiple tools at once
   */
  registerBatch(tools: MCPTool[], options: ToolRegistrationOptions = {}): {
    registered: number;
    failed: string[];
  } {
    const startTime = performance.now();
    const failed: string[] = [];
    let registered = 0;

    for (const tool of tools) {
      if (this.register(tool, options)) {
        registered++;
      } else {
        failed.push(tool.name);
      }
    }

    const duration = performance.now() - startTime;
    this.logger.info('Batch registration complete', {
      total: tools.length,
      registered,
      failed: failed.length,
      duration: `${duration.toFixed(2)}ms`,
    });

    return { registered, failed };
  }

  /**
   * Unregister a tool
   */
  unregister(name: string): boolean {
    const metadata = this.tools.get(name);
    if (!metadata) {
      return false;
    }

    // Remove from category index
    if (metadata.tool.category) {
      const categoryTools = this.categoryIndex.get(metadata.tool.category);
      categoryTools?.delete(name);
      if (categoryTools?.size === 0) {
        this.categoryIndex.delete(metadata.tool.category);
      }
    }

    // Remove from tag index
    if (metadata.tool.tags) {
      for (const tag of metadata.tool.tags) {
        const tagTools = this.tagIndex.get(tag);
        tagTools?.delete(name);
        if (tagTools?.size === 0) {
          this.tagIndex.delete(tag);
        }
      }
    }

    this.tools.delete(name);
    this.logger.debug('Tool unregistered', { name });
    this.emit('tool:unregistered', name);

    return true;
  }

  /**
   * Get a tool by name
   */
  getTool(name: string): MCPTool | undefined {
    this.totalLookups++;
    return this.tools.get(name)?.tool;
  }

  /**
   * Check if a tool exists
   */
  hasTool(name: string): boolean {
    return this.tools.has(name);
  }

  /**
   * Get tool count
   */
  getToolCount(): number {
    return this.tools.size;
  }

  /**
   * Get all tool names
   */
  getToolNames(): string[] {
    return Array.from(this.tools.keys());
  }

  /**
   * List all tools with metadata
   */
  listTools(): Array<{
    name: string;
    description: string;
    category?: string;
    tags?: string[];
    deprecated?: boolean;
  }> {
    return Array.from(this.tools.values()).map(({ tool }) => ({
      name: tool.name,
      description: tool.description,
      category: tool.category,
      tags: tool.tags,
      deprecated: tool.deprecated,
    }));
  }

  /**
   * Search tools by criteria
   */
  search(options: ToolSearchOptions): MCPTool[] {
    let results: Set<string> | undefined;

    // Filter by category
    if (options.category) {
      const categoryTools = this.categoryIndex.get(options.category);
      if (!categoryTools) return [];
      results = new Set(categoryTools);
    }

    // Filter by tags (intersection)
    if (options.tags && options.tags.length > 0) {
      for (const tag of options.tags) {
        const tagTools = this.tagIndex.get(tag);
        if (!tagTools) return [];

        if (results) {
          results = new Set([...results].filter((name) => tagTools.has(name)));
        } else {
          results = new Set(tagTools);
        }
      }
    }

    // Get all tools if no filters applied
    if (!results) {
      results = new Set(this.tools.keys());
    }

    // Convert to tools and apply additional filters
    const tools: MCPTool[] = [];
    for (const name of results) {
      const metadata = this.tools.get(name);
      if (!metadata) continue;

      const tool = metadata.tool;

      // Filter by deprecated status
      if (options.deprecated !== undefined && tool.deprecated !== options.deprecated) {
        continue;
      }

      // Filter by cacheable status
      if (options.cacheable !== undefined && tool.cacheable !== options.cacheable) {
        continue;
      }

      tools.push(tool);
    }

    return tools;
  }

  /**
   * Get tools by category
   */
  getByCategory(category: string): MCPTool[] {
    const toolNames = this.categoryIndex.get(category);
    if (!toolNames) return [];

    return Array.from(toolNames)
      .map((name) => this.tools.get(name)?.tool)
      .filter((tool): tool is MCPTool => tool !== undefined);
  }

  /**
   * Get tools by tag
   */
  getByTag(tag: string): MCPTool[] {
    const toolNames = this.tagIndex.get(tag);
    if (!toolNames) return [];

    return Array.from(toolNames)
      .map((name) => this.tools.get(name)?.tool)
      .filter((tool): tool is MCPTool => tool !== undefined);
  }

  /**
   * Get all categories
   */
  getCategories(): string[] {
    return Array.from(this.categoryIndex.keys());
  }

  /**
   * Get all tags
   */
  getTags(): string[] {
    return Array.from(this.tagIndex.keys());
  }

  /**
   * Execute a tool
   */
  async execute(
    name: string,
    input: Record<string, unknown>,
    context?: ToolContext
  ): Promise<ToolCallResult> {
    const startTime = performance.now();
    const metadata = this.tools.get(name);

    if (!metadata) {
      return {
        content: [{ type: 'text', text: `Tool not found: ${name}` }],
        isError: true,
      };
    }

    // Build execution context with required sessionId
    const execContext: ToolContext = {
      sessionId: context?.sessionId || this.defaultContext?.sessionId || 'default-session',
      ...this.defaultContext,
      ...context,
    };
    this.totalExecutions++;
    metadata.callCount++;
    metadata.lastCalled = new Date();

    try {
      this.emit('tool:called', { name, input });

      const result = await metadata.tool.handler(input, execContext);

      const duration = performance.now() - startTime;
      this.updateAverageExecutionTime(metadata, duration);

      this.logger.debug('Tool executed', {
        name,
        duration: `${duration.toFixed(2)}ms`,
        success: true,
      });

      this.emit('tool:completed', { name, duration, success: true });

      // Format result
      return {
        content: [{
          type: 'text',
          text: typeof result === 'string' ? result : JSON.stringify(result, null, 2),
        }],
        isError: false,
      };
    } catch (error) {
      const duration = performance.now() - startTime;
      metadata.errorCount++;

      this.logger.error('Tool execution failed', { name, error });
      this.emit('tool:error', { name, error, duration });

      return {
        content: [{
          type: 'text',
          text: `Error: ${error instanceof Error ? error.message : String(error)}`,
        }],
        isError: true,
      };
    }
  }

  /**
   * Set default execution context
   */
  setDefaultContext(context: ToolContext): void {
    this.defaultContext = context;
  }

  /**
   * Get tool metadata
   */
  getMetadata(name: string): ToolMetadata | undefined {
    return this.tools.get(name);
  }

  /**
   * Get registry statistics
   */
  getStats(): {
    totalTools: number;
    totalCategories: number;
    totalTags: number;
    totalRegistrations: number;
    totalLookups: number;
    totalExecutions: number;
    topTools: Array<{ name: string; calls: number }>;
  } {
    // Get top 10 most used tools
    const topTools = Array.from(this.tools.entries())
      .map(([name, metadata]) => ({ name, calls: metadata.callCount }))
      .sort((a, b) => b.calls - a.calls)
      .slice(0, 10);

    return {
      totalTools: this.tools.size,
      totalCategories: this.categoryIndex.size,
      totalTags: this.tagIndex.size,
      totalRegistrations: this.totalRegistrations,
      totalLookups: this.totalLookups,
      totalExecutions: this.totalExecutions,
      topTools,
    };
  }

  /**
   * Validate a tool definition
   */
  validateTool(tool: MCPTool): { valid: boolean; errors: string[] } {
    const errors: string[] = [];

    if (!tool.name || typeof tool.name !== 'string') {
      errors.push('Tool name is required and must be a string');
    } else if (!/^[a-zA-Z][a-zA-Z0-9_/:-]*$/.test(tool.name)) {
      errors.push('Tool name must start with a letter and contain only alphanumeric characters, underscores, slashes, colons, and hyphens');
    }

    if (!tool.description || typeof tool.description !== 'string') {
      errors.push('Tool description is required and must be a string');
    }

    if (!tool.inputSchema || typeof tool.inputSchema !== 'object') {
      errors.push('Tool inputSchema is required and must be an object');
    } else {
      const schemaErrors = this.validateSchema(tool.inputSchema);
      errors.push(...schemaErrors);
    }

    if (typeof tool.handler !== 'function') {
      errors.push('Tool handler is required and must be a function');
    }

    return {
      valid: errors.length === 0,
      errors,
    };
  }

  /**
   * Validate JSON Schema
   */
  private validateSchema(schema: JSONSchema, path = ''): string[] {
    const errors: string[] = [];

    if (!schema.type) {
      errors.push(`${path || 'schema'}: type is required`);
    }

    if (schema.type === 'object' && schema.properties) {
      for (const [key, propSchema] of Object.entries(schema.properties)) {
        const propPath = path ? `${path}.${key}` : key;
        errors.push(...this.validateSchema(propSchema, propPath));
      }
    }

    if (schema.type === 'array' && schema.items) {
      errors.push(...this.validateSchema(schema.items, `${path}[]`));
    }

    return errors;
  }

  /**
   * Update average execution time
   */
  private updateAverageExecutionTime(metadata: ToolMetadata, duration: number): void {
    const n = metadata.callCount;
    metadata.avgExecutionTime =
      ((metadata.avgExecutionTime * (n - 1)) + duration) / n;
  }

  /**
   * Clear all tools
   */
  clear(): void {
    this.tools.clear();
    this.categoryIndex.clear();
    this.tagIndex.clear();
    this.logger.info('Tool registry cleared');
    this.emit('registry:cleared');
  }
}

/**
 * Create a tool registry
 */
export function createToolRegistry(logger: ILogger): ToolRegistry {
  return new ToolRegistry(logger);
}

/**
 * Helper to create a tool definition
 */
export function defineTool<TInput = Record<string, unknown>, TOutput = unknown>(
  name: string,
  description: string,
  inputSchema: JSONSchema,
  handler: ToolHandler<TInput, TOutput>,
  options?: {
    category?: string;
    tags?: string[];
    version?: string;
    deprecated?: boolean;
    cacheable?: boolean;
    cacheTTL?: number;
    timeout?: number;
  }
): MCPTool<TInput, TOutput> {
  return {
    name,
    description,
    inputSchema,
    handler,
    ...options,
  };
}

/**
 * V3 MCP HTTP Transport
 *
 * HTTP/REST transport for MCP communication:
 * - Express-based with optimized middleware
 * - WebSocket support for real-time notifications
 * - Connection pooling for client connections
 * - Security headers with helmet
 *
 * Performance Targets:
 * - Request handling: <20ms overhead
 * - WebSocket message: <5ms
 */

import { EventEmitter } from 'events';
import express, { Express, Request, Response, NextFunction } from 'express';
import { createServer, Server } from 'http';
import { WebSocketServer, WebSocket } from 'ws';
import cors from 'cors';
import helmet from 'helmet';
import {
  ITransport,
  TransportType,
  MCPRequest,
  MCPResponse,
  MCPNotification,
  RequestHandler,
  NotificationHandler,
  TransportHealthStatus,
  ILogger,
  AuthConfig,
} from '../types.js';

/**
 * HTTP Transport Configuration
 */
export interface HttpTransportConfig {
  host: string;
  port: number;
  tlsEnabled?: boolean;
  tlsCert?: string;
  tlsKey?: string;
  corsEnabled?: boolean;
  corsOrigins?: string[];
  auth?: AuthConfig;
  maxRequestSize?: string;
  requestTimeout?: number;
}

/**
 * HTTP Transport Implementation
 */
export class HttpTransport extends EventEmitter implements ITransport {
  public readonly type: TransportType = 'http';

  private requestHandler?: RequestHandler;
  private notificationHandler?: NotificationHandler;
  private app: Express;
  private server?: Server;
  private wss?: WebSocketServer;
  private running = false;
  private activeConnections = new Set<WebSocket>();

  // Statistics
  private messagesReceived = 0;
  private messagesSent = 0;
  private errors = 0;
  private httpRequests = 0;
  private wsMessages = 0;

  constructor(
    private readonly logger: ILogger,
    private readonly config: HttpTransportConfig
  ) {
    super();
    this.app = express();
    this.setupMiddleware();
    this.setupRoutes();
  }

  /**
   * Start the transport
   */
  async start(): Promise<void> {
    if (this.running) {
      throw new Error('HTTP transport already running');
    }

    this.logger.info('Starting HTTP transport', {
      host: this.config.host,
      port: this.config.port,
    });

    // Create HTTP server
    this.server = createServer(this.app);

    // Create WebSocket server
    this.wss = new WebSocketServer({
      server: this.server,
      path: '/ws',
    });

    this.setupWebSocketHandlers();

    // Start server
    await new Promise<void>((resolve, reject) => {
      this.server!.listen(this.config.port, this.config.host, () => {
        resolve();
      });
      this.server!.on('error', reject);
    });

    this.running = true;
    this.logger.info('HTTP transport started', {
      url: `http://${this.config.host}:${this.config.port}`,
    });
  }

  /**
   * Stop the transport
   */
  async stop(): Promise<void> {
    if (!this.running) {
      return;
    }

    this.logger.info('Stopping HTTP transport');
    this.running = false;

    // Close all WebSocket connections
    for (const ws of this.activeConnections) {
      try {
        ws.close(1000, 'Server shutting down');
      } catch {
        // Ignore errors
      }
    }
    this.activeConnections.clear();

    // Close WebSocket server
    if (this.wss) {
      this.wss.close();
      this.wss = undefined;
    }

    // Close HTTP server
    if (this.server) {
      await new Promise<void>((resolve) => {
        this.server!.close(() => resolve());
      });
      this.server = undefined;
    }

    this.logger.info('HTTP transport stopped');
  }

  /**
   * Register request handler
   */
  onRequest(handler: RequestHandler): void {
    this.requestHandler = handler;
  }

  /**
   * Register notification handler
   */
  onNotification(handler: NotificationHandler): void {
    this.notificationHandler = handler;
  }

  /**
   * Get health status
   */
  async getHealthStatus(): Promise<TransportHealthStatus> {
    return {
      healthy: this.running,
      metrics: {
        messagesReceived: this.messagesReceived,
        messagesSent: this.messagesSent,
        errors: this.errors,
        httpRequests: this.httpRequests,
        wsMessages: this.wsMessages,
        activeConnections: this.activeConnections.size,
      },
    };
  }

  /**
   * Send notification to all connected WebSocket clients
   */
  async sendNotification(notification: MCPNotification): Promise<void> {
    const message = JSON.stringify(notification);

    for (const ws of this.activeConnections) {
      try {
        if (ws.readyState === WebSocket.OPEN) {
          ws.send(message);
          this.messagesSent++;
        }
      } catch (error) {
        this.logger.error('Failed to send notification', { error });
        this.errors++;
      }
    }
  }

  /**
   * Setup Express middleware
   */
  private setupMiddleware(): void {
    // Security headers
    this.app.use(helmet({
      contentSecurityPolicy: false, // Allow for flexibility
    }));

    // CORS - Secure defaults (no wildcard in production)
    if (this.config.corsEnabled !== false) {
      const allowedOrigins = this.config.corsOrigins;

      // SECURITY: Reject wildcard CORS in production unless explicitly configured
      if (!allowedOrigins || allowedOrigins.length === 0) {
        this.logger.warn('CORS: No origins configured, restricting to same-origin only');
      }

      this.app.use(cors({
        origin: (origin, callback) => {
          // Allow requests with no origin (same-origin, curl, etc.)
          if (!origin) {
            callback(null, true);
            return;
          }

          // Check against allowed origins
          if (allowedOrigins && allowedOrigins.length > 0) {
            if (allowedOrigins.includes(origin) || allowedOrigins.includes('*')) {
              callback(null, true);
            } else {
              callback(new Error(`CORS: Origin '${origin}' not allowed`));
            }
          } else {
            // No origins configured - reject cross-origin requests
            callback(new Error('CORS: Cross-origin requests not allowed'));
          }
        },
        credentials: true,
        maxAge: 86400,
        methods: ['GET', 'POST', 'OPTIONS'],
        allowedHeaders: ['Content-Type', 'Authorization', 'X-Request-ID'],
      }));
    }

    // Body parsing
    this.app.use(express.json({
      limit: this.config.maxRequestSize || '10mb',
    }));

    // Request timeout
    if (this.config.requestTimeout) {
      this.app.use((req, res, next) => {
        res.setTimeout(this.config.requestTimeout!, () => {
          res.status(408).json({
            jsonrpc: '2.0',
            id: null,
            error: { code: -32000, message: 'Request timeout' },
          });
        });
        next();
      });
    }

    // Request logging
    this.app.use((req, res, next) => {
      const startTime = performance.now();
      res.on('finish', () => {
        const duration = performance.now() - startTime;
        this.logger.debug('HTTP request', {
          method: req.method,
          path: req.path,
          status: res.statusCode,
          duration: `${duration.toFixed(2)}ms`,
        });
      });
      next();
    });
  }

  /**
   * Setup Express routes
   */
  private setupRoutes(): void {
    // Health check
    this.app.get('/health', (req, res) => {
      res.json({
        status: 'ok',
        timestamp: new Date().toISOString(),
        connections: this.activeConnections.size,
      });
    });

    // MCP JSON-RPC endpoint
    this.app.post('/rpc', async (req, res) => {
      await this.handleHttpRequest(req, res);
    });

    // Alternative MCP endpoint
    this.app.post('/mcp', async (req, res) => {
      await this.handleHttpRequest(req, res);
    });

    // Server info
    this.app.get('/info', (req, res) => {
      res.json({
        name: 'Claude-Flow MCP Server V3',
        version: '3.0.0',
        transport: 'http',
        capabilities: {
          jsonrpc: true,
          websocket: true,
        },
      });
    });

    // 404 handler
    this.app.use((req, res) => {
      res.status(404).json({
        error: 'Not found',
        path: req.path,
      });
    });

    // Error handler
    this.app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
      this.logger.error('Express error', { error: err });
      this.errors++;
      res.status(500).json({
        jsonrpc: '2.0',
        id: null,
        error: { code: -32603, message: 'Internal error' },
      });
    });
  }

  /**
   * Setup WebSocket handlers
   */
  private setupWebSocketHandlers(): void {
    if (!this.wss) return;

    this.wss.on('connection', (ws, req) => {
      this.activeConnections.add(ws);
      this.logger.info('WebSocket client connected', {
        total: this.activeConnections.size,
      });

      ws.on('message', async (data) => {
        await this.handleWebSocketMessage(ws, data.toString());
      });

      ws.on('close', () => {
        this.activeConnections.delete(ws);
        this.logger.info('WebSocket client disconnected', {
          total: this.activeConnections.size,
        });
      });

      ws.on('error', (error) => {
        this.logger.error('WebSocket error', { error });
        this.errors++;
        this.activeConnections.delete(ws);
      });
    });
  }

  /**
   * Handle HTTP request
   */
  private async handleHttpRequest(req: Request, res: Response): Promise<void> {
    this.httpRequests++;
    this.messagesReceived++;

    // Validate authentication (ALWAYS check, not just when explicitly enabled)
    // SECURITY: Auth should be opt-out, not opt-in
    const requiresAuth = this.config.auth?.enabled !== false; // Default to requiring auth

    if (requiresAuth && this.config.auth) {
      const authResult = this.validateAuth(req);
      if (!authResult.valid) {
        this.logger.warn('Authentication failed', {
          ip: req.ip,
          path: req.path,
          error: authResult.error,
        });
        res.status(401).json({
          jsonrpc: '2.0',
          id: null,
          error: { code: -32001, message: 'Unauthorized' },
        });
        return;
      }
    } else if (requiresAuth && !this.config.auth) {
      // No auth configured but auth is required - warn and continue (development mode)
      this.logger.warn('No authentication configured - running in development mode');
    }

    const message = req.body;

    // Validate JSON-RPC format
    if (message.jsonrpc !== '2.0') {
      res.status(400).json({
        jsonrpc: '2.0',
        id: message.id || null,
        error: { code: -32600, message: 'Invalid JSON-RPC version' },
      });
      return;
    }

    if (!message.method) {
      res.status(400).json({
        jsonrpc: '2.0',
        id: message.id || null,
        error: { code: -32600, message: 'Missing method' },
      });
      return;
    }

    // Handle notification vs request
    if (message.id === undefined) {
      // Notification
      if (this.notificationHandler) {
        await this.notificationHandler(message as MCPNotification);
      }
      res.status(204).end();
    } else {
      // Request
      if (!this.requestHandler) {
        res.status(500).json({
          jsonrpc: '2.0',
          id: message.id,
          error: { code: -32603, message: 'No request handler' },
        });
        return;
      }

      try {
        const response = await this.requestHandler(message as MCPRequest);
        res.json(response);
        this.messagesSent++;
      } catch (error) {
        this.errors++;
        res.status(500).json({
          jsonrpc: '2.0',
          id: message.id,
          error: {
            code: -32603,
            message: error instanceof Error ? error.message : 'Internal error',
          },
        });
      }
    }
  }

  /**
   * Handle WebSocket message
   */
  private async handleWebSocketMessage(ws: WebSocket, data: string): Promise<void> {
    this.wsMessages++;
    this.messagesReceived++;

    try {
      const message = JSON.parse(data);

      if (message.jsonrpc !== '2.0') {
        ws.send(JSON.stringify({
          jsonrpc: '2.0',
          id: message.id || null,
          error: { code: -32600, message: 'Invalid JSON-RPC version' },
        }));
        return;
      }

      if (message.id === undefined) {
        // Notification
        if (this.notificationHandler) {
          await this.notificationHandler(message as MCPNotification);
        }
      } else {
        // Request
        if (!this.requestHandler) {
          ws.send(JSON.stringify({
            jsonrpc: '2.0',
            id: message.id,
            error: { code: -32603, message: 'No request handler' },
          }));
          return;
        }

        const response = await this.requestHandler(message as MCPRequest);
        ws.send(JSON.stringify(response));
        this.messagesSent++;
      }
    } catch (error) {
      this.errors++;
      this.logger.error('WebSocket message error', { error });

      try {
        const parsed = JSON.parse(data);
        ws.send(JSON.stringify({
          jsonrpc: '2.0',
          id: parsed.id || null,
          error: { code: -32700, message: 'Parse error' },
        }));
      } catch {
        ws.send(JSON.stringify({
          jsonrpc: '2.0',
          id: null,
          error: { code: -32700, message: 'Parse error' },
        }));
      }
    }
  }

  /**
   * Validate authentication
   */
  private validateAuth(req: Request): { valid: boolean; error?: string } {
    const auth = req.headers.authorization;

    if (!auth) {
      return { valid: false, error: 'Authorization header required' };
    }

    const tokenMatch = auth.match(/^Bearer\s+(.+)$/i);
    if (!tokenMatch) {
      return { valid: false, error: 'Invalid authorization format' };
    }

    const token = tokenMatch[1];

    if (this.config.auth?.tokens?.length) {
      if (!this.config.auth.tokens.includes(token)) {
        return { valid: false, error: 'Invalid token' };
      }
    }

    return { valid: true };
  }
}

/**
 * Create HTTP transport
 */
export function createHttpTransport(
  logger: ILogger,
  config: HttpTransportConfig
): HttpTransport {
  return new HttpTransport(logger, config);
}

/**
 * V3 MCP Transport Factory
 *
 * Central factory for creating transport instances:
 * - Unified transport creation API
 * - Transport type validation
 * - Configuration defaults
 * - Multi-transport support
 *
 * Supported transports:
 * - stdio: Standard I/O (default for CLI)
 * - http: HTTP/REST with WebSocket upgrade
 * - websocket: Standalone WebSocket
 * - in-process: Direct function calls (fastest)
 */

import {
  ITransport,
  TransportType,
  TransportHealthStatus,
  ILogger,
} from '../types.js';
import { StdioTransport, StdioTransportConfig, createStdioTransport } from './stdio.js';
import { HttpTransport, HttpTransportConfig, createHttpTransport } from './http.js';
import { WebSocketTransport, WebSocketTransportConfig, createWebSocketTransport } from './websocket.js';

// Re-export transport classes (values)
export { StdioTransport } from './stdio.js';
export { HttpTransport } from './http.js';
export { WebSocketTransport } from './websocket.js';

// Re-export transport config types
export type { StdioTransportConfig } from './stdio.js';
export type { HttpTransportConfig } from './http.js';
export type { WebSocketTransportConfig } from './websocket.js';

/**
 * Transport configuration union
 */
export type TransportConfig =
  | { type: 'stdio' } & StdioTransportConfig
  | { type: 'http' } & HttpTransportConfig
  | { type: 'websocket' } & WebSocketTransportConfig
  | { type: 'in-process' };

/**
 * Create a transport instance based on type
 */
export function createTransport(
  type: TransportType,
  logger: ILogger,
  config?: Partial<TransportConfig>
): ITransport {
  switch (type) {
    case 'stdio':
      return createStdioTransport(logger, config as StdioTransportConfig);

    case 'http':
      if (!config || !('host' in config) || !('port' in config)) {
        throw new Error('HTTP transport requires host and port configuration');
      }
      return createHttpTransport(logger, {
        host: config.host as string,
        port: config.port as number,
        ...config,
      } as HttpTransportConfig);

    case 'websocket':
      if (!config || !('host' in config) || !('port' in config)) {
        throw new Error('WebSocket transport requires host and port configuration');
      }
      return createWebSocketTransport(logger, {
        host: config.host as string,
        port: config.port as number,
        ...config,
      } as WebSocketTransportConfig);

    case 'in-process':
      // In-process transport is handled directly by the server
      // Return a no-op transport wrapper
      return createInProcessTransport(logger);

    default:
      throw new Error(`Unknown transport type: ${type}`);
  }
}

/**
 * In-process transport (no-op wrapper)
 *
 * Used when tools are executed directly without network transport
 */
class InProcessTransport implements ITransport {
  public readonly type: TransportType = 'in-process';

  constructor(private readonly logger: ILogger) {}

  async start(): Promise<void> {
    this.logger.debug('In-process transport started');
  }

  async stop(): Promise<void> {
    this.logger.debug('In-process transport stopped');
  }

  onRequest(): void {
    // No-op - requests are handled directly
  }

  onNotification(): void {
    // No-op - notifications are handled directly
  }

  async getHealthStatus(): Promise<TransportHealthStatus> {
    return {
      healthy: true,
      metrics: {
        latency: 0,
        connections: 1,
      },
    };
  }
}

/**
 * Create in-process transport
 */
export function createInProcessTransport(logger: ILogger): ITransport {
  return new InProcessTransport(logger);
}

/**
 * Transport manager for multi-transport scenarios
 */
export class TransportManager {
  private transports: Map<string, ITransport> = new Map();
  private running = false;

  constructor(private readonly logger: ILogger) {}

  /**
   * Add a transport
   */
  addTransport(name: string, transport: ITransport): void {
    if (this.transports.has(name)) {
      throw new Error(`Transport "${name}" already exists`);
    }
    this.transports.set(name, transport);
    this.logger.debug('Transport added', { name, type: transport.type });
  }

  /**
   * Remove a transport
   */
  async removeTransport(name: string): Promise<boolean> {
    const transport = this.transports.get(name);
    if (!transport) {
      return false;
    }

    await transport.stop();
    this.transports.delete(name);
    this.logger.debug('Transport removed', { name });
    return true;
  }

  /**
   * Get a transport by name
   */
  getTransport(name: string): ITransport | undefined {
    return this.transports.get(name);
  }

  /**
   * Get all transport names
   */
  getTransportNames(): string[] {
    return Array.from(this.transports.keys());
  }

  /**
   * Start all transports
   */
  async startAll(): Promise<void> {
    if (this.running) {
      throw new Error('TransportManager already running');
    }

    this.logger.info('Starting all transports', { count: this.transports.size });

    const startPromises = Array.from(this.transports.entries()).map(
      async ([name, transport]) => {
        try {
          await transport.start();
          this.logger.info('Transport started', { name, type: transport.type });
        } catch (error) {
          this.logger.error('Failed to start transport', { name, error });
          throw error;
        }
      }
    );

    await Promise.all(startPromises);
    this.running = true;
    this.logger.info('All transports started');
  }

  /**
   * Stop all transports
   */
  async stopAll(): Promise<void> {
    if (!this.running) {
      return;
    }

    this.logger.info('Stopping all transports');

    const stopPromises = Array.from(this.transports.entries()).map(
      async ([name, transport]) => {
        try {
          await transport.stop();
          this.logger.info('Transport stopped', { name });
        } catch (error) {
          this.logger.error('Error stopping transport', { name, error });
        }
      }
    );

    await Promise.all(stopPromises);
    this.running = false;
    this.logger.info('All transports stopped');
  }

  /**
   * Get health status of all transports
   */
  async getHealthStatus(): Promise<Record<string, { healthy: boolean; error?: string }>> {
    const results: Record<string, { healthy: boolean; error?: string }> = {};

    for (const [name, transport] of this.transports) {
      try {
        const status = await transport.getHealthStatus();
        results[name] = { healthy: status.healthy, error: status.error };
      } catch (error) {
        results[name] = {
          healthy: false,
          error: error instanceof Error ? error.message : 'Unknown error',
        };
      }
    }

    return results;
  }

  /**
   * Check if any transport is running
   */
  isRunning(): boolean {
    return this.running;
  }
}

/**
 * Create a transport manager
 */
export function createTransportManager(logger: ILogger): TransportManager {
  return new TransportManager(logger);
}

