/**
 * V3 MCP Stdio Transport
 *
 * Standard I/O transport for MCP communication:
 * - Optimized JSON parsing with streaming
 * - Buffer management for large messages
 * - Graceful shutdown handling
 *
 * Performance Targets:
 * - Message parsing: <5ms
 * - Response sending: <2ms
 */

import { EventEmitter } from 'events';
import * as readline from 'readline';
import {
  ITransport,
  TransportType,
  MCPRequest,
  MCPResponse,
  MCPNotification,
  RequestHandler,
  NotificationHandler,
  TransportHealthStatus,
  ILogger,
} from '../types.js';

/**
 * Stdio Transport Configuration
 */
export interface StdioTransportConfig {
  inputStream?: NodeJS.ReadableStream;
  outputStream?: NodeJS.WritableStream;
  maxMessageSize?: number;
}

/**
 * Stdio Transport Implementation
 *
 * Uses readline for efficient line-by-line processing of JSON-RPC messages
 */
export class StdioTransport extends EventEmitter implements ITransport {
  public readonly type: TransportType = 'stdio';

  private requestHandler?: RequestHandler;
  private notificationHandler?: NotificationHandler;
  private rl?: readline.Interface;
  private running = false;
  private messageBuffer = '';

  // Statistics
  private messagesReceived = 0;
  private messagesSent = 0;
  private errors = 0;

  private readonly inputStream: NodeJS.ReadableStream;
  private readonly outputStream: NodeJS.WritableStream;
  private readonly maxMessageSize: number;

  constructor(
    private readonly logger: ILogger,
    config: StdioTransportConfig = {}
  ) {
    super();
    this.inputStream = config.inputStream || process.stdin;
    this.outputStream = config.outputStream || process.stdout;
    this.maxMessageSize = config.maxMessageSize || 10 * 1024 * 1024; // 10MB default
  }

  /**
   * Start the transport
   */
  async start(): Promise<void> {
    if (this.running) {
      throw new Error('Stdio transport already running');
    }

    this.logger.info('Starting stdio transport');

    // Create readline interface for efficient line processing
    this.rl = readline.createInterface({
      input: this.inputStream,
      crlfDelay: Infinity,
    });

    // Handle incoming lines
    this.rl.on('line', (line) => {
      this.handleLine(line);
    });

    // Handle close
    this.rl.on('close', () => {
      this.handleClose();
    });

    // Handle errors on input stream
    this.inputStream.on('error', (error) => {
      this.handleError(error);
    });

    this.running = true;
    this.logger.info('Stdio transport started');
  }

  /**
   * Stop the transport
   */
  async stop(): Promise<void> {
    if (!this.running) {
      return;
    }

    this.logger.info('Stopping stdio transport');
    this.running = false;

    if (this.rl) {
      this.rl.close();
      this.rl = undefined;
    }

    this.logger.info('Stdio transport stopped');
  }

  /**
   * Register request handler
   */
  onRequest(handler: RequestHandler): void {
    this.requestHandler = handler;
  }

  /**
   * Register notification handler
   */
  onNotification(handler: NotificationHandler): void {
    this.notificationHandler = handler;
  }

  /**
   * Get health status
   */
  async getHealthStatus(): Promise<TransportHealthStatus> {
    return {
      healthy: this.running,
      metrics: {
        messagesReceived: this.messagesReceived,
        messagesSent: this.messagesSent,
        errors: this.errors,
      },
    };
  }

  /**
   * Handle incoming line
   */
  private async handleLine(line: string): Promise<void> {
    if (!line.trim()) {
      return;
    }

    // Check message size
    if (line.length > this.maxMessageSize) {
      this.logger.error('Message exceeds maximum size', {
        size: line.length,
        max: this.maxMessageSize,
      });
      this.errors++;
      return;
    }

    try {
      const message = JSON.parse(line);
      this.messagesReceived++;

      // Validate JSON-RPC format
      if (message.jsonrpc !== '2.0') {
        this.logger.warn('Invalid JSON-RPC version', { received: message.jsonrpc });
        await this.sendError(message.id, -32600, 'Invalid JSON-RPC version');
        return;
      }

      if (!message.method) {
        this.logger.warn('Missing method in request');
        await this.sendError(message.id, -32600, 'Missing method');
        return;
      }

      // Determine if this is a request or notification
      if (message.id !== undefined) {
        // Request - needs response
        await this.handleRequest(message as MCPRequest);
      } else {
        // Notification - no response needed
        await this.handleNotification(message as MCPNotification);
      }
    } catch (error) {
      this.errors++;
      this.logger.error('Failed to parse message', { error, line: line.substring(0, 100) });
      await this.sendError(null, -32700, 'Parse error');
    }
  }

  /**
   * Handle MCP request
   */
  private async handleRequest(request: MCPRequest): Promise<void> {
    if (!this.requestHandler) {
      this.logger.warn('No request handler registered');
      await this.sendError(request.id, -32603, 'No request handler');
      return;
    }

    try {
      const startTime = performance.now();
      const response = await this.requestHandler(request);
      const duration = performance.now() - startTime;

      this.logger.debug('Request processed', {
        method: request.method,
        duration: `${duration.toFixed(2)}ms`,
      });

      await this.sendResponse(response);
    } catch (error) {
      this.logger.error('Request handler error', { method: request.method, error });
      await this.sendError(
        request.id,
        -32603,
        error instanceof Error ? error.message : 'Internal error'
      );
    }
  }

  /**
   * Handle MCP notification
   */
  private async handleNotification(notification: MCPNotification): Promise<void> {
    if (!this.notificationHandler) {
      this.logger.debug('Notification received but no handler', { method: notification.method });
      return;
    }

    try {
      await this.notificationHandler(notification);
    } catch (error) {
      this.logger.error('Notification handler error', { method: notification.method, error });
      // Notifications don't send error responses
    }
  }

  /**
   * Send response to stdout
   */
  private async sendResponse(response: MCPResponse): Promise<void> {
    const json = JSON.stringify(response);
    await this.write(json);
    this.messagesSent++;
  }

  /**
   * Send error response
   */
  private async sendError(id: string | number | null, code: number, message: string): Promise<void> {
    const response: MCPResponse = {
      jsonrpc: '2.0',
      id,
      error: { code, message },
    };
    await this.sendResponse(response);
    this.errors++;
  }

  /**
   * Send notification to stdout
   */
  async sendNotification(notification: MCPNotification): Promise<void> {
    const json = JSON.stringify(notification);
    await this.write(json);
    this.messagesSent++;
  }

  /**
   * Write to output stream
   */
  private write(data: string): Promise<void> {
    return new Promise((resolve, reject) => {
      this.outputStream.write(data + '\n', (error) => {
        if (error) {
          this.errors++;
          reject(error);
        } else {
          resolve();
        }
      });
    });
  }

  /**
   * Handle stream close
   */
  private handleClose(): void {
    this.logger.info('Stdio stream closed');
    this.running = false;
    this.emit('close');
  }

  /**
   * Handle stream error
   */
  private handleError(error: Error): void {
    this.logger.error('Stdio stream error', error);
    this.errors++;
    this.emit('error', error);
  }
}

/**
 * Create stdio transport
 */
export function createStdioTransport(
  logger: ILogger,
  config: StdioTransportConfig = {}
): StdioTransport {
  return new StdioTransport(logger, config);
}

/**
 * V3 MCP WebSocket Transport
 *
 * Standalone WebSocket transport for MCP communication:
 * - Native WebSocket server without HTTP dependency
 * - Binary message support for efficiency
 * - Heartbeat/ping-pong for connection health
 * - Automatic reconnection handling
 *
 * Performance Targets:
 * - Message latency: <3ms
 * - Connection overhead: <10ms
 */

import { EventEmitter } from 'events';
import { WebSocketServer, WebSocket, RawData } from 'ws';
import { createServer, Server } from 'http';
import {
  ITransport,
  TransportType,
  MCPRequest,
  MCPResponse,
  MCPNotification,
  RequestHandler,
  NotificationHandler,
  TransportHealthStatus,
  ILogger,
  AuthConfig,
} from '../types.js';

/**
 * WebSocket Transport Configuration
 */
export interface WebSocketTransportConfig {
  host: string;
  port: number;
  path?: string;
  maxConnections?: number;
  heartbeatInterval?: number;
  heartbeatTimeout?: number;
  maxMessageSize?: number;
  auth?: AuthConfig;
  enableBinaryMode?: boolean;
}

/**
 * Client connection info
 */
interface ClientConnection {
  id: string;
  ws: WebSocket;
  createdAt: Date;
  lastActivity: Date;
  messageCount: number;
  isAlive: boolean;
  isAuthenticated: boolean;
}

/**
 * WebSocket Transport Implementation
 */
export class WebSocketTransport extends EventEmitter implements ITransport {
  public readonly type: TransportType = 'websocket';

  private requestHandler?: RequestHandler;
  private notificationHandler?: NotificationHandler;
  private server?: Server;
  private wss?: WebSocketServer;
  private clients: Map<string, ClientConnection> = new Map();
  private heartbeatTimer?: NodeJS.Timeout;
  private running = false;
  private connectionCounter = 0;

  // Statistics
  private messagesReceived = 0;
  private messagesSent = 0;
  private errors = 0;
  private totalConnections = 0;

  constructor(
    private readonly logger: ILogger,
    private readonly config: WebSocketTransportConfig
  ) {
    super();
  }

  /**
   * Start the transport
   */
  async start(): Promise<void> {
    if (this.running) {
      throw new Error('WebSocket transport already running');
    }

    this.logger.info('Starting WebSocket transport', {
      host: this.config.host,
      port: this.config.port,
      path: this.config.path || '/ws',
    });

    // Create HTTP server for WebSocket upgrade
    this.server = createServer((req, res) => {
      // Simple HTTP response for non-WebSocket requests
      res.writeHead(426, { 'Content-Type': 'text/plain' });
      res.end('Upgrade Required - WebSocket connection expected');
    });

    // Create WebSocket server
    this.wss = new WebSocketServer({
      server: this.server,
      path: this.config.path || '/ws',
      maxPayload: this.config.maxMessageSize || 10 * 1024 * 1024,
      perMessageDeflate: true, // Enable compression
    });

    this.setupWebSocketHandlers();
    this.startHeartbeat();

    // Start server
    await new Promise<void>((resolve, reject) => {
      this.server!.listen(this.config.port, this.config.host, () => {
        resolve();
      });
      this.server!.on('error', reject);
    });

    this.running = true;
    this.logger.info('WebSocket transport started', {
      url: `ws://${this.config.host}:${this.config.port}${this.config.path || '/ws'}`,
    });
  }

  /**
   * Stop the transport
   */
  async stop(): Promise<void> {
    if (!this.running) {
      return;
    }

    this.logger.info('Stopping WebSocket transport');
    this.running = false;

    this.stopHeartbeat();

    // Close all client connections
    for (const client of this.clients.values()) {
      try {
        client.ws.close(1000, 'Server shutting down');
      } catch {
        // Ignore errors
      }
    }
    this.clients.clear();

    // Close WebSocket server
    if (this.wss) {
      this.wss.close();
      this.wss = undefined;
    }

    // Close HTTP server
    if (this.server) {
      await new Promise<void>((resolve) => {
        this.server!.close(() => resolve());
      });
      this.server = undefined;
    }

    this.logger.info('WebSocket transport stopped');
  }

  /**
   * Register request handler
   */
  onRequest(handler: RequestHandler): void {
    this.requestHandler = handler;
  }

  /**
   * Register notification handler
   */
  onNotification(handler: NotificationHandler): void {
    this.notificationHandler = handler;
  }

  /**
   * Get health status
   */
  async getHealthStatus(): Promise<TransportHealthStatus> {
    return {
      healthy: this.running,
      metrics: {
        messagesReceived: this.messagesReceived,
        messagesSent: this.messagesSent,
        errors: this.errors,
        activeConnections: this.clients.size,
        totalConnections: this.totalConnections,
      },
    };
  }

  /**
   * Send notification to all connected clients
   */
  async sendNotification(notification: MCPNotification): Promise<void> {
    const message = this.serializeMessage(notification);

    for (const client of this.clients.values()) {
      try {
        if (client.ws.readyState === WebSocket.OPEN) {
          client.ws.send(message);
          this.messagesSent++;
        }
      } catch (error) {
        this.logger.error('Failed to send notification', { clientId: client.id, error });
        this.errors++;
      }
    }
  }

  /**
   * Send notification to specific client
   */
  async sendToClient(clientId: string, notification: MCPNotification): Promise<boolean> {
    const client = this.clients.get(clientId);
    if (!client || client.ws.readyState !== WebSocket.OPEN) {
      return false;
    }

    try {
      client.ws.send(this.serializeMessage(notification));
      this.messagesSent++;
      return true;
    } catch (error) {
      this.logger.error('Failed to send to client', { clientId, error });
      this.errors++;
      return false;
    }
  }

  /**
   * Get connected clients
   */
  getClients(): string[] {
    return Array.from(this.clients.keys());
  }

  /**
   * Get client info
   */
  getClientInfo(clientId: string): ClientConnection | undefined {
    return this.clients.get(clientId);
  }

  /**
   * Disconnect specific client
   */
  disconnectClient(clientId: string, reason = 'Disconnected by server'): boolean {
    const client = this.clients.get(clientId);
    if (!client) {
      return false;
    }

    try {
      client.ws.close(1000, reason);
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Setup WebSocket handlers
   */
  private setupWebSocketHandlers(): void {
    if (!this.wss) return;

    this.wss.on('connection', (ws, req) => {
      // Check max connections
      if (this.config.maxConnections && this.clients.size >= this.config.maxConnections) {
        this.logger.warn('Max connections reached, rejecting client');
        ws.close(1013, 'Server at capacity');
        return;
      }

      const clientId = `client-${++this.connectionCounter}`;
      const client: ClientConnection = {
        id: clientId,
        ws,
        createdAt: new Date(),
        lastActivity: new Date(),
        messageCount: 0,
        isAlive: true,
        isAuthenticated: !this.config.auth?.enabled,
      };

      this.clients.set(clientId, client);
      this.totalConnections++;

      this.logger.info('Client connected', {
        id: clientId,
        total: this.clients.size,
      });

      // Setup message handler
      ws.on('message', async (data) => {
        await this.handleMessage(client, data);
      });

      // Setup pong handler for heartbeat
      ws.on('pong', () => {
        client.isAlive = true;
      });

      // Setup close handler
      ws.on('close', (code, reason) => {
        this.clients.delete(clientId);
        this.logger.info('Client disconnected', {
          id: clientId,
          code,
          reason: reason.toString(),
          total: this.clients.size,
        });
        this.emit('client:disconnected', clientId);
      });

      // Setup error handler
      ws.on('error', (error) => {
        this.logger.error('Client error', { id: clientId, error });
        this.errors++;
        this.clients.delete(clientId);
      });

      this.emit('client:connected', clientId);
    });
  }

  /**
   * Handle incoming message
   */
  private async handleMessage(client: ClientConnection, data: RawData): Promise<void> {
    client.lastActivity = new Date();
    client.messageCount++;
    this.messagesReceived++;

    try {
      const message = this.parseMessage(data);

      // Check authentication for non-authenticated clients
      if (!client.isAuthenticated && this.config.auth?.enabled) {
        if (message.method !== 'authenticate') {
          client.ws.send(this.serializeMessage({
            jsonrpc: '2.0',
            id: message.id || null,
            error: { code: -32001, message: 'Authentication required' },
          } as MCPResponse));
          return;
        }
      }

      if (message.jsonrpc !== '2.0') {
        client.ws.send(this.serializeMessage({
          jsonrpc: '2.0',
          id: message.id || null,
          error: { code: -32600, message: 'Invalid JSON-RPC version' },
        } as MCPResponse));
        return;
      }

      if (message.id === undefined) {
        // Notification
        if (this.notificationHandler) {
          await this.notificationHandler(message as MCPNotification);
        }
      } else {
        // Request
        if (!this.requestHandler) {
          client.ws.send(this.serializeMessage({
            jsonrpc: '2.0',
            id: message.id,
            error: { code: -32603, message: 'No request handler' },
          } as MCPResponse));
          return;
        }

        const startTime = performance.now();
        const response = await this.requestHandler(message as MCPRequest);
        const duration = performance.now() - startTime;

        this.logger.debug('Request processed', {
          clientId: client.id,
          method: message.method,
          duration: `${duration.toFixed(2)}ms`,
        });

        client.ws.send(this.serializeMessage(response));
        this.messagesSent++;
      }
    } catch (error) {
      this.errors++;
      this.logger.error('Message handling error', { clientId: client.id, error });

      try {
        client.ws.send(this.serializeMessage({
          jsonrpc: '2.0',
          id: null,
          error: { code: -32700, message: 'Parse error' },
        } as MCPResponse));
      } catch {
        // Ignore send errors
      }
    }
  }

  /**
   * Parse incoming message
   */
  private parseMessage(data: RawData): any {
    if (this.config.enableBinaryMode && Buffer.isBuffer(data)) {
      // Could implement binary protocol here
      return JSON.parse(data.toString());
    }
    return JSON.parse(data.toString());
  }

  /**
   * Serialize outgoing message
   */
  private serializeMessage(message: MCPResponse | MCPNotification): string | Buffer {
    if (this.config.enableBinaryMode) {
      // Could implement binary protocol here
      return JSON.stringify(message);
    }
    return JSON.stringify(message);
  }

  /**
   * Start heartbeat interval
   */
  private startHeartbeat(): void {
    const interval = this.config.heartbeatInterval || 30000; // 30 seconds
    const timeout = this.config.heartbeatTimeout || 10000; // 10 seconds

    this.heartbeatTimer = setInterval(() => {
      for (const client of this.clients.values()) {
        if (!client.isAlive) {
          // Client didn't respond to last ping
          this.logger.warn('Client heartbeat timeout', { id: client.id });
          client.ws.terminate();
          this.clients.delete(client.id);
          continue;
        }

        client.isAlive = false;
        try {
          client.ws.ping();
        } catch {
          // Ignore ping errors
        }
      }
    }, interval);
  }

  /**
   * Stop heartbeat interval
   */
  private stopHeartbeat(): void {
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = undefined;
    }
  }
}

/**
 * Create WebSocket transport
 */
export function createWebSocketTransport(
  logger: ILogger,
  config: WebSocketTransportConfig
): WebSocketTransport {
  return new WebSocketTransport(logger, config);
}

/**
 * V3 MCP Types and Interfaces
 *
 * Optimized type definitions for the V3 MCP server with:
 * - Strict typing for performance
 * - Connection pooling types
 * - Transport layer abstractions
 * - Tool registry interfaces
 *
 * Performance Targets:
 * - Server startup: <400ms
 * - Tool registration: <10ms
 * - Tool execution: <50ms overhead
 */

// ============================================================================
// Core Protocol Types
// ============================================================================

/**
 * JSON-RPC 2.0 Protocol Version
 */
export type JsonRpcVersion = '2.0';

/**
 * MCP Protocol Version. Per the [MCP spec](https://spec.modelcontextprotocol.io/specification/basic/lifecycle/#initialization)
 * this must be a `YYYY-MM-DD` date string (e.g. `'2024-11-05'`, `'2025-06-18'`).
 * Claude Code's Zod validator rejects any other shape (#1874).
 */
export type MCPProtocolVersion = string;

/**
 * MCP Request ID (can be string, number, or null)
 */
export type RequestId = string | number | null;

/**
 * Base MCP Message
 */
export interface MCPMessage {
  jsonrpc: JsonRpcVersion;
}

/**
 * MCP Request
 */
export interface MCPRequest extends MCPMessage {
  id: RequestId;
  method: string;
  params?: Record<string, unknown>;
}

/**
 * MCP Notification (request without id)
 */
export interface MCPNotification extends MCPMessage {
  method: string;
  params?: Record<string, unknown>;
}

/**
 * MCP Error
 */
export interface MCPError {
  code: number;
  message: string;
  data?: unknown;
}

/**
 * MCP Response
 */
export interface MCPResponse extends MCPMessage {
  id: RequestId;
  result?: unknown;
  error?: MCPError;
}

// ============================================================================
// Server Configuration
// ============================================================================

/**
 * Transport type options
 */
export type TransportType = 'stdio' | 'http' | 'websocket' | 'in-process';

/**
 * Authentication method
 */
export type AuthMethod = 'token' | 'oauth' | 'api-key' | 'none';

/**
 * Authentication configuration
 */
export interface AuthConfig {
  enabled: boolean;
  method: AuthMethod;
  tokens?: string[];
  apiKeys?: string[];
  jwtSecret?: string;
  oauth?: {
    clientId: string;
    clientSecret: string;
    authorizationUrl: string;
    tokenUrl: string;
  };
}

/**
 * Load balancer configuration
 */
export interface LoadBalancerConfig {
  enabled: boolean;
  maxConcurrentRequests: number;
  rateLimit?: {
    requestsPerSecond: number;
    burstSize: number;
  };
  circuitBreaker?: {
    failureThreshold: number;
    resetTimeout: number;
  };
}

/**
 * Connection pool configuration
 */
export interface ConnectionPoolConfig {
  maxConnections: number;
  minConnections: number;
  idleTimeout: number;
  acquireTimeout: number;
  maxWaitingClients: number;
  evictionRunInterval: number;
}

/**
 * MCP Server configuration
 */
export interface MCPServerConfig {
  name: string;
  version: string;
  transport: TransportType;
  host?: string;
  port?: number;
  tlsEnabled?: boolean;
  tlsCert?: string;
  tlsKey?: string;
  auth?: AuthConfig;
  loadBalancer?: LoadBalancerConfig;
  connectionPool?: ConnectionPoolConfig;
  corsEnabled?: boolean;
  corsOrigins?: string[];
  maxRequestSize?: number;
  requestTimeout?: number;
  enableMetrics?: boolean;
  enableCaching?: boolean;
  cacheTTL?: number;
  logLevel?: 'debug' | 'info' | 'warn' | 'error';
}

// ============================================================================
// Session Types
// ============================================================================

/**
 * MCP Session state
 */
export type SessionState = 'created' | 'initializing' | 'ready' | 'closing' | 'closed' | 'error';

/**
 * MCP Session
 */
export interface MCPSession {
  id: string;
  state: SessionState;
  transport: TransportType;
  createdAt: Date;
  lastActivityAt: Date;
  isInitialized: boolean;
  isAuthenticated: boolean;
  clientInfo?: MCPClientInfo;
  protocolVersion?: MCPProtocolVersion;
  capabilities?: MCPCapabilities;
  metadata?: Record<string, unknown>;
}

/**
 * Client information from initialization
 */
export interface MCPClientInfo {
  name: string;
  version: string;
}

// ============================================================================
// Capability Types
// ============================================================================

/**
 * MCP Capabilities
 */
export interface MCPCapabilities {
  logging?: {
    level: 'debug' | 'info' | 'warn' | 'error';
  };
  tools?: {
    listChanged: boolean;
  };
  resources?: {
    listChanged: boolean;
    subscribe: boolean;
  };
  prompts?: {
    listChanged: boolean;
  };
  experimental?: Record<string, unknown>;
}

/**
 * Initialize request parameters
 */
export interface MCPInitializeParams {
  protocolVersion: MCPProtocolVersion;
  capabilities: MCPCapabilities;
  clientInfo: MCPClientInfo;
}

/**
 * Initialize response result
 */
export interface MCPInitializeResult {
  protocolVersion: MCPProtocolVersion;
  capabilities: MCPCapabilities;
  serverInfo: {
    name: string;
    version: string;
  };
  instructions?: string;
}

// ============================================================================
// Tool Types
// ============================================================================

/**
 * JSON Schema type for tool input
 */
export interface JSONSchema {
  type: string;
  properties?: Record<string, JSONSchema>;
  required?: string[];
  items?: JSONSchema;
  enum?: string[];
  description?: string;
  default?: unknown;
  minimum?: number;
  maximum?: number;
  minLength?: number;
  maxLength?: number;
  pattern?: string;
  additionalProperties?: boolean | JSONSchema;
}

/**
 * Tool execution context
 */
export interface ToolContext {
  sessionId: string;
  requestId?: RequestId;
  orchestrator?: unknown;
  swarmCoordinator?: unknown;
  agentManager?: unknown;
  resourceManager?: unknown;
  messageBus?: unknown;
  monitor?: unknown;
  metadata?: Record<string, unknown>;
}

/**
 * Tool handler function type
 */
export type ToolHandler<TInput = unknown, TOutput = unknown> = (
  input: TInput,
  context?: ToolContext
) => Promise<TOutput>;

/**
 * MCP Tool definition
 */
export interface MCPTool<TInput = unknown, TOutput = unknown> {
  name: string;
  description: string;
  inputSchema: JSONSchema;
  handler: ToolHandler<TInput, TOutput>;
  category?: string;
  tags?: string[];
  version?: string;
  deprecated?: boolean;
  cacheable?: boolean;
  cacheTTL?: number;
  timeout?: number;
}

/**
 * Tool call result
 */
export interface ToolCallResult {
  content: Array<{
    type: 'text' | 'image' | 'resource';
    text?: string;
    data?: string;
    mimeType?: string;
  }>;
  isError: boolean;
}

/**
 * Tool registration options
 */
export interface ToolRegistrationOptions {
  override?: boolean;
  validate?: boolean;
  preload?: boolean;
}

// ============================================================================
// Transport Types
// ============================================================================

/**
 * Request handler function type
 */
export type RequestHandler = (request: MCPRequest) => Promise<MCPResponse>;

/**
 * Notification handler function type
 */
export type NotificationHandler = (notification: MCPNotification) => Promise<void>;

/**
 * Transport health status
 */
export interface TransportHealthStatus {
  healthy: boolean;
  error?: string;
  metrics?: Record<string, number>;
}

/**
 * Transport interface
 */
export interface ITransport {
  readonly type: TransportType;

  start(): Promise<void>;
  stop(): Promise<void>;

  onRequest(handler: RequestHandler): void;
  onNotification(handler: NotificationHandler): void;

  sendNotification?(notification: MCPNotification): Promise<void>;

  getHealthStatus(): Promise<TransportHealthStatus>;
}

// ============================================================================
// Connection Pool Types
// ============================================================================

/**
 * Connection state
 */
export type ConnectionState = 'idle' | 'busy' | 'closing' | 'closed' | 'error';

/**
 * Pooled connection
 */
export interface PooledConnection {
  id: string;
  state: ConnectionState;
  createdAt: Date;
  lastUsedAt: Date;
  useCount: number;
  transport: TransportType;
  metadata?: Record<string, unknown>;
}

/**
 * Connection pool statistics
