}

/**
 * Plugin error types
 */
export class PluginError extends Error {
  constructor(
    message: string,
    public readonly pluginName: string,
    public readonly code: PluginErrorCode,
    public readonly cause?: Error
  ) {
    super(message);
    this.name = 'PluginError';
  }
}

export type PluginErrorCode =
  | 'INITIALIZATION_FAILED'
  | 'SHUTDOWN_FAILED'
  | 'DEPENDENCY_NOT_FOUND'
  | 'CIRCULAR_DEPENDENCY'
  | 'INVALID_PLUGIN'
  | 'DUPLICATE_PLUGIN'
  | 'HEALTH_CHECK_FAILED';

/**
 * V3 Plugin Loader
 * Domain-Driven Design - Plugin-Based Architecture (ADR-004)
 *
 * Handles plugin loading, dependency resolution, and lifecycle management
 */

import type {
  ClaudeFlowPlugin,
  PluginContext,
  PluginInfo,
  PluginLifecycleState,
  PluginError as PluginErrorType,
  PluginErrorCode,
} from './plugin-interface.js';
import { PluginError } from './plugin-interface.js';
import type { PluginRegistry } from './plugin-registry.js';

/**
 * Plugin loader configuration
 */
export interface PluginLoaderConfig {
  /**
   * Maximum time to wait for plugin initialization (ms)
   */
  initializationTimeout?: number;

  /**
   * Maximum time to wait for plugin shutdown (ms)
   */
  shutdownTimeout?: number;

  /**
   * Enable parallel plugin initialization
   */
  parallelInitialization?: boolean;

  /**
   * Enable strict dependency checking
   */
  strictDependencies?: boolean;

  /**
   * Enable health checks
   */
  enableHealthChecks?: boolean;

  /**
   * Health check interval (ms)
   */
  healthCheckInterval?: number;
}

/**
 * Default plugin loader configuration
 */
const DEFAULT_CONFIG: Required<PluginLoaderConfig> = {
  initializationTimeout: 30000, // 30 seconds
  shutdownTimeout: 10000, // 10 seconds
  parallelInitialization: false, // Sequential by default for safety
  strictDependencies: true,
  enableHealthChecks: false,
  healthCheckInterval: 60000, // 1 minute
};

/**
 * Plugin dependency graph node
 */
interface DependencyNode {
  plugin: ClaudeFlowPlugin;
  dependencies: Set<string>;
  dependents: Set<string>;
  depth: number;
}

/**
 * Plugin loader for managing plugin lifecycle
 */
export class PluginLoader {
  private config: Required<PluginLoaderConfig>;
  private registry: PluginRegistry;
  private initializationOrder: string[] = [];
  private healthCheckIntervalId?: NodeJS.Timeout;

  constructor(registry: PluginRegistry, config?: PluginLoaderConfig) {
    this.registry = registry;
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Load a single plugin
   */
  async loadPlugin(plugin: ClaudeFlowPlugin, context: PluginContext): Promise<void> {
    // Validate plugin
    this.validatePlugin(plugin);

    // Check for duplicates
    if (this.registry.hasPlugin(plugin.name)) {
      throw new PluginError(
        `Plugin '${plugin.name}' is already loaded`,
        plugin.name,
        'DUPLICATE_PLUGIN'
      );
    }

    // Register plugin in uninitialized state
    this.registry.registerPlugin(plugin, 'uninitialized', context);

    // Resolve dependencies
    if (this.config.strictDependencies) {
      this.validateDependencies(plugin);
    }

    // Initialize plugin
    await this.initializePlugin(plugin, context);

    // Update initialization order
    this.initializationOrder.push(plugin.name);
  }

  /**
   * Load multiple plugins with dependency resolution
   */
  async loadPlugins(
    plugins: ClaudeFlowPlugin[],
    context: PluginContext
  ): Promise<LoadPluginsResult> {
    const results: LoadPluginsResult = {
      successful: [],
      failed: [],
      totalDuration: 0,
    };

    const startTime = Date.now();

    try {
      // Validate all plugins first
      for (const plugin of plugins) {
        this.validatePlugin(plugin);
      }

      // Build dependency graph
      const dependencyGraph = this.buildDependencyGraph(plugins);

      // Detect circular dependencies
      this.detectCircularDependencies(dependencyGraph);

      // Sort plugins by dependency order (topological sort)
      const sortedPlugins = this.topologicalSort(dependencyGraph);

      // Initialize plugins in order
      if (this.config.parallelInitialization) {
        await this.initializePluginsParallel(sortedPlugins, context, results);
      } else {
        await this.initializePluginsSequential(sortedPlugins, context, results);
      }
    } catch (error) {
      // If error during setup, mark all as failed
      for (const plugin of plugins) {
        if (!results.successful.includes(plugin.name) && !results.failed.some((f) => f.name === plugin.name)) {
          results.failed.push({
            name: plugin.name,
            error: error instanceof Error ? error : new Error(String(error)),
          });
        }
      }
    } finally {
      results.totalDuration = Date.now() - startTime;
    }

    // Start health checks if enabled
    if (this.config.enableHealthChecks) {
      this.startHealthChecks();
    }

    return results;
  }

  /**
   * Unload a single plugin
   */
  async unloadPlugin(pluginName: string): Promise<void> {
    const pluginInfo = this.registry.getPlugin(pluginName);
    if (!pluginInfo) {
      throw new PluginError(
        `Plugin '${pluginName}' not found`,
        pluginName,
        'INVALID_PLUGIN'
      );
    }

    // Check for dependents
    const dependents = this.findDependents(pluginName);
    if (dependents.length > 0) {
      throw new PluginError(
        `Cannot unload plugin '${pluginName}': depended on by ${dependents.join(', ')}`,
        pluginName,
        'DEPENDENCY_NOT_FOUND'
      );
    }

    // Shutdown plugin
    await this.shutdownPlugin(pluginInfo.plugin);

    // Unregister plugin
    this.registry.unregisterPlugin(pluginName);

    // Remove from initialization order
    const index = this.initializationOrder.indexOf(pluginName);
    if (index !== -1) {
      this.initializationOrder.splice(index, 1);
    }
  }

  /**
   * Unload all plugins in reverse initialization order
   */
  async unloadAll(): Promise<void> {
    // Stop health checks
    if (this.healthCheckIntervalId) {
      clearInterval(this.healthCheckIntervalId);
      this.healthCheckIntervalId = undefined;
    }

    // Shutdown in reverse order
    const pluginsToShutdown = [...this.initializationOrder].reverse();

    for (const pluginName of pluginsToShutdown) {
      try {
        await this.unloadPlugin(pluginName);
      } catch (error) {
        // Log error but continue shutting down other plugins
        console.error(`Error unloading plugin '${pluginName}':`, error);
      }
    }

    this.initializationOrder = [];
  }

  /**
   * Reload a plugin
   */
  async reloadPlugin(pluginName: string, newPlugin: ClaudeFlowPlugin, context: PluginContext): Promise<void> {
    await this.unloadPlugin(pluginName);
    await this.loadPlugin(newPlugin, context);
  }

  /**
   * Get plugin initialization order
   */
  getInitializationOrder(): string[] {
    return [...this.initializationOrder];
  }

  /**
   * Validate plugin interface
   */
  private validatePlugin(plugin: ClaudeFlowPlugin): void {
    if (!plugin.name) {
      throw new PluginError(
        'Plugin must have a name',
        '<unknown>',
        'INVALID_PLUGIN'
      );
    }

    if (!plugin.version) {
      throw new PluginError(
        `Plugin '${plugin.name}' must have a version`,
        plugin.name,
        'INVALID_PLUGIN'
      );
    }

    if (typeof plugin.initialize !== 'function') {
      throw new PluginError(
        `Plugin '${plugin.name}' must implement initialize()`,
        plugin.name,
        'INVALID_PLUGIN'
      );
    }

    if (typeof plugin.shutdown !== 'function') {
      throw new PluginError(
        `Plugin '${plugin.name}' must implement shutdown()`,
        plugin.name,
        'INVALID_PLUGIN'
      );
    }
  }

  /**
   * Validate plugin dependencies
   */
  private validateDependencies(plugin: ClaudeFlowPlugin): void {
    if (!plugin.dependencies || plugin.dependencies.length === 0) {
      return;
    }

    for (const dep of plugin.dependencies) {
      if (!this.registry.hasPlugin(dep)) {
        throw new PluginError(
          `Plugin '${plugin.name}' depends on '${dep}' which is not loaded`,
          plugin.name,
          'DEPENDENCY_NOT_FOUND'
        );
      }

      // Check dependency is initialized
      const depInfo = this.registry.getPlugin(dep);
      if (depInfo && depInfo.state !== 'initialized') {
        throw new PluginError(
          `Plugin '${plugin.name}' depends on '${dep}' which is not initialized (state: ${depInfo.state})`,
          plugin.name,
          'DEPENDENCY_NOT_FOUND'
        );
      }
    }
  }

  /**
   * Initialize a single plugin
   */
  private async initializePlugin(plugin: ClaudeFlowPlugin, context: PluginContext): Promise<void> {
    this.registry.updatePluginState(plugin.name, 'initializing');

    try {
      // Run initialization with timeout
      await this.withTimeout(
        plugin.initialize(context),
        this.config.initializationTimeout,
        `Plugin '${plugin.name}' initialization timed out`
      );

      this.registry.updatePluginState(plugin.name, 'initialized');
      this.registry.collectPluginMetrics(plugin.name);
    } catch (error) {
      this.registry.updatePluginState(plugin.name, 'error', error instanceof Error ? error : new Error(String(error)));
      throw new PluginError(
        `Failed to initialize plugin '${plugin.name}': ${error}`,
        plugin.name,
        'INITIALIZATION_FAILED',
        error instanceof Error ? error : undefined
      );
    }
  }

  /**
   * Shutdown a single plugin
   */
  private async shutdownPlugin(plugin: ClaudeFlowPlugin): Promise<void> {
    this.registry.updatePluginState(plugin.name, 'shutting-down');

    try {
      await this.withTimeout(
        plugin.shutdown(),
        this.config.shutdownTimeout,
        `Plugin '${plugin.name}' shutdown timed out`
      );

      this.registry.updatePluginState(plugin.name, 'shutdown');
    } catch (error) {
      this.registry.updatePluginState(plugin.name, 'error', error instanceof Error ? error : new Error(String(error)));
      throw new PluginError(
        `Failed to shutdown plugin '${plugin.name}': ${error}`,
        plugin.name,
        'SHUTDOWN_FAILED',
        error instanceof Error ? error : undefined
      );
    }
  }

  /**
   * Initialize plugins sequentially
   */
  private async initializePluginsSequential(
    plugins: ClaudeFlowPlugin[],
    context: PluginContext,
    results: LoadPluginsResult
  ): Promise<void> {
    for (const plugin of plugins) {
      try {
        // Register and initialize
        this.registry.registerPlugin(plugin, 'uninitialized', context);
        await this.initializePlugin(plugin, context);

        results.successful.push(plugin.name);
        this.initializationOrder.push(plugin.name);
      } catch (error) {
        results.failed.push({
          name: plugin.name,
          error: error instanceof Error ? error : new Error(String(error)),
        });

        // Stop on first failure in sequential mode if strict
        if (this.config.strictDependencies) {
          break;
        }
      }
    }
  }

  /**
   * Initialize plugins in parallel (by dependency level)
   */
  private async initializePluginsParallel(
    plugins: ClaudeFlowPlugin[],
    context: PluginContext,
    results: LoadPluginsResult
  ): Promise<void> {
    // Group plugins by dependency depth
    const dependencyGraph = this.buildDependencyGraph(plugins);
    const levels = this.groupByDepth(dependencyGraph);

    // Initialize each level in parallel
    for (const level of levels) {
      const promises = level.map(async (plugin) => {
        try {
          this.registry.registerPlugin(plugin, 'uninitialized', context);
          await this.initializePlugin(plugin, context);

          results.successful.push(plugin.name);
          this.initializationOrder.push(plugin.name);
        } catch (error) {
          results.failed.push({
            name: plugin.name,
            error: error instanceof Error ? error : new Error(String(error)),
          });
        }
      });

      await Promise.all(promises);

      // Stop on failures in level if strict
      if (this.config.strictDependencies && results.failed.length > 0) {
        break;
      }
    }
  }

  /**
   * Build dependency graph
   */
  private buildDependencyGraph(plugins: ClaudeFlowPlugin[]): Map<string, DependencyNode> {
    const graph = new Map<string, DependencyNode>();

    // Create nodes
    for (const plugin of plugins) {
      graph.set(plugin.name, {
        plugin,
        dependencies: new Set(plugin.dependencies || []),
        dependents: new Set(),
        depth: 0,
      });
    }

    // Build dependency links
    for (const [name, node] of Array.from(graph.entries())) {
      for (const dep of Array.from(node.dependencies)) {
        const depNode = graph.get(dep);
        if (depNode) {
          depNode.dependents.add(name);
        }
      }
    }

    // Calculate depths
    this.calculateDepths(graph);

    return graph;
  }

  /**
   * Calculate depth of each node (for topological sorting)
   */
  private calculateDepths(graph: Map<string, DependencyNode>): void {
    const visited = new Set<string>();

    const visit = (name: string): number => {
      if (visited.has(name)) {
        const node = graph.get(name);
        return node ? node.depth : 0;
      }

      visited.add(name);
      const node = graph.get(name);
      if (!node) return 0;

      let maxDepth = 0;
      for (const dep of Array.from(node.dependencies)) {
        maxDepth = Math.max(maxDepth, visit(dep) + 1);
      }

      node.depth = maxDepth;
      return maxDepth;
    };

    for (const name of Array.from(graph.keys())) {
      visit(name);
    }
  }

  /**
   * Topological sort (dependency order)
   */
  private topologicalSort(graph: Map<string, DependencyNode>): ClaudeFlowPlugin[] {
    const sorted: ClaudeFlowPlugin[] = [];
    const nodes = Array.from(graph.values());

    // Sort by depth (dependencies first)
    nodes.sort((a, b) => a.depth - b.depth);

    for (const node of nodes) {
      sorted.push(node.plugin);
    }

    return sorted;
  }

  /**
   * Group plugins by dependency depth (for parallel initialization)
   */
  private groupByDepth(graph: Map<string, DependencyNode>): ClaudeFlowPlugin[][] {
    const levels: ClaudeFlowPlugin[][] = [];
    const maxDepth = Math.max(...Array.from(graph.values()).map((n) => n.depth));

    for (let depth = 0; depth <= maxDepth; depth++) {
      const level: ClaudeFlowPlugin[] = [];
      for (const node of Array.from(graph.values())) {
        if (node.depth === depth) {
          level.push(node.plugin);
        }
      }
      if (level.length > 0) {
        levels.push(level);
      }
    }

    return levels;
  }

  /**
   * Detect circular dependencies
   */
  private detectCircularDependencies(graph: Map<string, DependencyNode>): void {
    const visited = new Set<string>();
    const stack = new Set<string>();

    const visit = (name: string, path: string[]): void => {
      if (stack.has(name)) {
        const cycle = [...path, name];
        throw new PluginError(
          `Circular dependency detected: ${cycle.join(' -> ')}`,
          name,
          'CIRCULAR_DEPENDENCY'
        );
      }

      if (visited.has(name)) {
        return;
      }

      visited.add(name);
      stack.add(name);

      const node = graph.get(name);
      if (node) {
        for (const dep of Array.from(node.dependencies)) {
          visit(dep, [...path, name]);
        }
      }

      stack.delete(name);
    };

    for (const name of Array.from(graph.keys())) {
      visit(name, []);
    }
  }

  /**
   * Find plugins that depend on a given plugin
   */
  private findDependents(pluginName: string): string[] {
    const dependents: string[] = [];

    for (const [name, info] of Array.from(this.registry.getAllPlugins().entries())) {
      if (info.plugin.dependencies?.includes(pluginName)) {
        dependents.push(name);
      }
    }

    return dependents;
  }

  /**
   * Start periodic health checks
   */
  private startHealthChecks(): void {
    this.healthCheckIntervalId = setInterval(async () => {
      for (const [name, info] of Array.from(this.registry.getAllPlugins().entries())) {
        if (info.state === 'initialized' && info.plugin.healthCheck) {
          try {
            const healthy = await info.plugin.healthCheck();
            if (!healthy) {
              console.warn(`Plugin '${name}' health check failed`);
              this.registry.updatePluginState(name, 'error', new Error('Health check failed'));
            }
          } catch (error) {
            console.error(`Plugin '${name}' health check error:`, error);
            this.registry.updatePluginState(name, 'error', error instanceof Error ? error : new Error(String(error)));
          }
        }
      }
    }, this.config.healthCheckInterval);
  }

  /**
   * Utility: Run promise with timeout
   */
  private async withTimeout<T>(promise: Promise<T>, timeoutMs: number, errorMessage: string): Promise<T> {
    return Promise.race([
      promise,
      new Promise<T>((_, reject) =>
        setTimeout(() => reject(new Error(errorMessage)), timeoutMs)
      ),
    ]);
  }
}

/**
 * Load plugins result
 */
export interface LoadPluginsResult {
  successful: string[];
  failed: Array<{ name: string; error: Error }>;
  totalDuration: number;
}

/**
 * V3 Plugin Registry
 * Domain-Driven Design - Plugin-Based Architecture (ADR-004)
 *
 * Central registry for tracking plugin state, metadata, and registrations
 */

import type {
  ClaudeFlowPlugin,
  PluginInfo,
  PluginLifecycleState,
  PluginContext,
  AgentTypeDefinition,
  TaskTypeDefinition,
  MCPToolDefinition,
  CLICommandDefinition,
  MemoryBackendFactory,
} from './plugin-interface.js';
import { PluginError } from './plugin-interface.js';

/**
 * Plugin registry for managing plugin lifecycle and registrations
 */
export class PluginRegistry {
  private plugins = new Map<string, PluginInfo>();
  private agentTypes = new Map<string, { plugin: string; definition: AgentTypeDefinition }>();
  private taskTypes = new Map<string, { plugin: string; definition: TaskTypeDefinition }>();
  private mcpTools = new Map<string, { plugin: string; definition: MCPToolDefinition }>();
  private cliCommands = new Map<string, { plugin: string; definition: CLICommandDefinition }>();
  private memoryBackends = new Map<string, { plugin: string; factory: MemoryBackendFactory }>();

  /**
   * Register a plugin in the registry
   */
  registerPlugin(
    plugin: ClaudeFlowPlugin,
    initialState: PluginLifecycleState,
    context: PluginContext
  ): void {
    if (this.plugins.has(plugin.name)) {
      throw new PluginError(
        `Plugin '${plugin.name}' is already registered`,
        plugin.name,
        'DUPLICATE_PLUGIN'
      );
    }

    const info: PluginInfo = {
      plugin,
      state: initialState,
      context,
      metrics: {
        agentTypesRegistered: 0,
        taskTypesRegistered: 0,
        mcpToolsRegistered: 0,
        cliCommandsRegistered: 0,
        memoryBackendsRegistered: 0,
      },
    };

    this.plugins.set(plugin.name, info);
  }

  /**
   * Unregister a plugin from the registry
   */
  unregisterPlugin(pluginName: string): boolean {
    const info = this.plugins.get(pluginName);
    if (!info) {
      return false;
    }

    // Unregister all plugin's registrations
    this.unregisterPluginAgentTypes(pluginName);
    this.unregisterPluginTaskTypes(pluginName);
    this.unregisterPluginMCPTools(pluginName);
    this.unregisterPluginCLICommands(pluginName);
    this.unregisterPluginMemoryBackends(pluginName);

    // Remove plugin
    return this.plugins.delete(pluginName);
  }

  /**
   * Get a plugin by name
   */
  getPlugin(pluginName: string): PluginInfo | undefined {
    return this.plugins.get(pluginName);
  }

  /**
   * Get all registered plugins
   */
  getAllPlugins(): Map<string, PluginInfo> {
    return new Map(this.plugins);
  }

  /**
   * Get all plugin names
   */
  getPluginNames(): string[] {
    return Array.from(this.plugins.keys());
  }

  /**
   * Check if a plugin is registered
   */
  hasPlugin(pluginName: string): boolean {
    return this.plugins.has(pluginName);
  }

  /**
   * Get plugins by state
   */
  getPluginsByState(state: PluginLifecycleState): PluginInfo[] {
    return Array.from(this.plugins.values()).filter((info) => info.state === state);
  }

  /**
   * Get plugin count
   */
  getPluginCount(): number {
    return this.plugins.size;
  }

  /**
   * Update plugin state
   */
  updatePluginState(pluginName: string, state: PluginLifecycleState, error?: Error): void {
    const info = this.plugins.get(pluginName);
    if (!info) {
      throw new PluginError(
        `Plugin '${pluginName}' not found`,
        pluginName,
        'INVALID_PLUGIN'
      );
    }

    info.state = state;

    if (state === 'initialized') {
      info.initializedAt = new Date();
    } else if (state === 'shutdown') {
      info.shutdownAt = new Date();
    } else if (state === 'error') {
      info.error = error;
    }
  }

  /**
   * Collect and update plugin metrics
   */
  collectPluginMetrics(pluginName: string): void {
    const info = this.plugins.get(pluginName);
    if (!info || !info.metrics) {
      return;
    }

    const plugin = info.plugin;

    // Count registered items
    info.metrics.agentTypesRegistered = plugin.registerAgentTypes?.()?.length || 0;
    info.metrics.taskTypesRegistered = plugin.registerTaskTypes?.()?.length || 0;
    info.metrics.mcpToolsRegistered = plugin.registerMCPTools?.()?.length || 0;
    info.metrics.cliCommandsRegistered = plugin.registerCLICommands?.()?.length || 0;
    info.metrics.memoryBackendsRegistered = plugin.registerMemoryBackends?.()?.length || 0;
  }

  /**
   * Get plugin status summary
   */
  getStatusSummary(): PluginRegistryStatus {
    const states = Array.from(this.plugins.values()).reduce((acc, info) => {
      acc[info.state] = (acc[info.state] || 0) + 1;
      return acc;
    }, {} as Record<PluginLifecycleState, number>);

    return {
      totalPlugins: this.plugins.size,
      states,
      agentTypesRegistered: this.agentTypes.size,
      taskTypesRegistered: this.taskTypes.size,
      mcpToolsRegistered: this.mcpTools.size,
      cliCommandsRegistered: this.cliCommands.size,
      memoryBackendsRegistered: this.memoryBackends.size,
    };
  }

  // =============================================================================
  // Agent Type Registry
  // =============================================================================

  /**
   * Register agent types from a plugin
   */
  registerAgentTypes(pluginName: string): void {
    const info = this.plugins.get(pluginName);
    if (!info) {
      throw new PluginError(
        `Plugin '${pluginName}' not found`,
        pluginName,
        'INVALID_PLUGIN'
      );
    }

    const agentTypes = info.plugin.registerAgentTypes?.();
    if (!agentTypes || agentTypes.length === 0) {
      return;
    }

    for (const definition of agentTypes) {
      if (this.agentTypes.has(definition.type)) {
        throw new PluginError(
          `Agent type '${definition.type}' is already registered by plugin '${this.agentTypes.get(definition.type)?.plugin}'`,
          pluginName,
          'DUPLICATE_PLUGIN'
        );
      }

      this.agentTypes.set(definition.type, { plugin: pluginName, definition });
    }
  }

  /**
   * Unregister agent types from a plugin
   */
  unregisterPluginAgentTypes(pluginName: string): void {
    for (const [type, entry] of Array.from(this.agentTypes.entries())) {
      if (entry.plugin === pluginName) {
        this.agentTypes.delete(type);
      }
    }
  }

  /**
   * Get agent type definition
   */
  getAgentType(type: string): AgentTypeDefinition | undefined {
    return this.agentTypes.get(type)?.definition;
  }

  /**
   * Get all agent types
   */
  getAllAgentTypes(): AgentTypeDefinition[] {
    return Array.from(this.agentTypes.values()).map((entry) => entry.definition);
  }

  /**
   * Get agent types by plugin
   */
  getAgentTypesByPlugin(pluginName: string): AgentTypeDefinition[] {
    return Array.from(this.agentTypes.values())
      .filter((entry) => entry.plugin === pluginName)
      .map((entry) => entry.definition);
  }

  // =============================================================================
  // Task Type Registry
  // =============================================================================

  /**
   * Register task types from a plugin
   */
  registerTaskTypes(pluginName: string): void {
    const info = this.plugins.get(pluginName);
    if (!info) {
      throw new PluginError(
        `Plugin '${pluginName}' not found`,
        pluginName,
        'INVALID_PLUGIN'
      );
    }

    const taskTypes = info.plugin.registerTaskTypes?.();
    if (!taskTypes || taskTypes.length === 0) {
      return;
    }

    for (const definition of taskTypes) {
      if (this.taskTypes.has(definition.type)) {
        throw new PluginError(
          `Task type '${definition.type}' is already registered by plugin '${this.taskTypes.get(definition.type)?.plugin}'`,
          pluginName,
          'DUPLICATE_PLUGIN'
        );
      }

      this.taskTypes.set(definition.type, { plugin: pluginName, definition });
    }
  }

  /**
   * Unregister task types from a plugin
   */
  unregisterPluginTaskTypes(pluginName: string): void {
    for (const [type, entry] of Array.from(this.taskTypes.entries())) {
      if (entry.plugin === pluginName) {
        this.taskTypes.delete(type);
      }
    }
  }

  /**
   * Get task type definition
   */
  getTaskType(type: string): TaskTypeDefinition | undefined {
    return this.taskTypes.get(type)?.definition;
  }

  /**
   * Get all task types
   */
  getAllTaskTypes(): TaskTypeDefinition[] {
    return Array.from(this.taskTypes.values()).map((entry) => entry.definition);
  }

  /**
   * Get task types by plugin
   */
  getTaskTypesByPlugin(pluginName: string): TaskTypeDefinition[] {
    return Array.from(this.taskTypes.values())
      .filter((entry) => entry.plugin === pluginName)
      .map((entry) => entry.definition);
  }

  // =============================================================================
  // MCP Tool Registry
  // =============================================================================

  /**
   * Register MCP tools from a plugin
   */
  registerMCPTools(pluginName: string): void {
    const info = this.plugins.get(pluginName);
    if (!info) {
      throw new PluginError(
        `Plugin '${pluginName}' not found`,
        pluginName,
        'INVALID_PLUGIN'
      );
    }

    const mcpTools = info.plugin.registerMCPTools?.();
    if (!mcpTools || mcpTools.length === 0) {
      return;
    }

    for (const definition of mcpTools) {
      if (this.mcpTools.has(definition.name)) {
        throw new PluginError(
          `MCP tool '${definition.name}' is already registered by plugin '${this.mcpTools.get(definition.name)?.plugin}'`,
          pluginName,
          'DUPLICATE_PLUGIN'
        );
      }

      // Add plugin metadata
      definition.pluginName = pluginName;

      this.mcpTools.set(definition.name, { plugin: pluginName, definition });
    }
  }

  /**
   * Unregister MCP tools from a plugin
   */
  unregisterPluginMCPTools(pluginName: string): void {
    for (const [name, entry] of Array.from(this.mcpTools.entries())) {
      if (entry.plugin === pluginName) {
        this.mcpTools.delete(name);
      }
    }
  }

  /**
   * Get MCP tool definition
   */
  getMCPTool(name: string): MCPToolDefinition | undefined {
    return this.mcpTools.get(name)?.definition;
  }

  /**
   * Get all MCP tools
   */
  getAllMCPTools(): MCPToolDefinition[] {
    return Array.from(this.mcpTools.values()).map((entry) => entry.definition);
  }

  /**
   * Get MCP tools by plugin
   */
  getMCPToolsByPlugin(pluginName: string): MCPToolDefinition[] {
    return Array.from(this.mcpTools.values())
      .filter((entry) => entry.plugin === pluginName)
      .map((entry) => entry.definition);
  }

  // =============================================================================
  // CLI Command Registry
  // =============================================================================

  /**
   * Register CLI commands from a plugin
   */
  registerCLICommands(pluginName: string): void {
    const info = this.plugins.get(pluginName);
    if (!info) {
      throw new PluginError(
        `Plugin '${pluginName}' not found`,
        pluginName,
        'INVALID_PLUGIN'
      );
    }

    const cliCommands = info.plugin.registerCLICommands?.();
    if (!cliCommands || cliCommands.length === 0) {
      return;
    }

    for (const definition of cliCommands) {
      if (this.cliCommands.has(definition.name)) {
        throw new PluginError(
          `CLI command '${definition.name}' is already registered by plugin '${this.cliCommands.get(definition.name)?.plugin}'`,
          pluginName,
          'DUPLICATE_PLUGIN'
        );
      }

      this.cliCommands.set(definition.name, { plugin: pluginName, definition });

      // Register aliases
      if (definition.aliases) {
        for (const alias of definition.aliases) {
          if (this.cliCommands.has(alias)) {
            throw new PluginError(
              `CLI command alias '${alias}' is already registered`,
              pluginName,
              'DUPLICATE_PLUGIN'
            );
          }
          this.cliCommands.set(alias, { plugin: pluginName, definition });
        }
      }
    }
  }

  /**
   * Unregister CLI commands from a plugin
   */
  unregisterPluginCLICommands(pluginName: string): void {
    for (const [name, entry] of Array.from(this.cliCommands.entries())) {
      if (entry.plugin === pluginName) {
        this.cliCommands.delete(name);
      }
    }
  }

  /**
   * Get CLI command definition
   */
  getCLICommand(name: string): CLICommandDefinition | undefined {
    return this.cliCommands.get(name)?.definition;
  }

  /**
   * Get all CLI commands
   */
  getAllCLICommands(): CLICommandDefinition[] {
    const seen = new Set<CLICommandDefinition>();
    return Array.from(this.cliCommands.values())
      .map((entry) => entry.definition)
      .filter((def) => {
        if (seen.has(def)) return false;
        seen.add(def);
        return true;
      });
  }

  /**
   * Get CLI commands by plugin
   */
  getCLICommandsByPlugin(pluginName: string): CLICommandDefinition[] {
    const seen = new Set<CLICommandDefinition>();
    return Array.from(this.cliCommands.values())
      .filter((entry) => entry.plugin === pluginName)
      .map((entry) => entry.definition)
      .filter((def) => {
        if (seen.has(def)) return false;
        seen.add(def);
        return true;
      });
  }

  // =============================================================================
  // Memory Backend Registry
  // =============================================================================

  /**
   * Register memory backends from a plugin
   */
  registerMemoryBackends(pluginName: string): void {
    const info = this.plugins.get(pluginName);
    if (!info) {
      throw new PluginError(
        `Plugin '${pluginName}' not found`,
        pluginName,
        'INVALID_PLUGIN'
      );
    }

    const memoryBackends = info.plugin.registerMemoryBackends?.();
    if (!memoryBackends || memoryBackends.length === 0) {
      return;
    }

    for (const factory of memoryBackends) {
      if (this.memoryBackends.has(factory.name)) {
        throw new PluginError(
          `Memory backend '${factory.name}' is already registered by plugin '${this.memoryBackends.get(factory.name)?.plugin}'`,
          pluginName,
          'DUPLICATE_PLUGIN'
        );
      }

      this.memoryBackends.set(factory.name, { plugin: pluginName, factory });
    }
  }

  /**
   * Unregister memory backends from a plugin
   */
  unregisterPluginMemoryBackends(pluginName: string): void {
    for (const [name, entry] of Array.from(this.memoryBackends.entries())) {
      if (entry.plugin === pluginName) {
        this.memoryBackends.delete(name);
      }
    }
  }

  /**
   * Get memory backend factory
   */
  getMemoryBackend(name: string): MemoryBackendFactory | undefined {
    return this.memoryBackends.get(name)?.factory;
  }

  /**
   * Get all memory backends
   */
  getAllMemoryBackends(): MemoryBackendFactory[] {
    return Array.from(this.memoryBackends.values()).map((entry) => entry.factory);
  }

  /**
   * Get memory backends by plugin
   */
  getMemoryBackendsByPlugin(pluginName: string): MemoryBackendFactory[] {
    return Array.from(this.memoryBackends.values())
      .filter((entry) => entry.plugin === pluginName)
      .map((entry) => entry.factory);
  }

  // =============================================================================
  // Bulk Registration
  // =============================================================================

  /**
   * Register all extension points from a plugin
   */
  registerAllFromPlugin(pluginName: string): void {
    this.registerAgentTypes(pluginName);
    this.registerTaskTypes(pluginName);
    this.registerMCPTools(pluginName);
    this.registerCLICommands(pluginName);
    this.registerMemoryBackends(pluginName);
    this.collectPluginMetrics(pluginName);
  }

  /**
   * Clear all registrations (for testing)
   */
  clear(): void {
    this.plugins.clear();
    this.agentTypes.clear();
    this.taskTypes.clear();
    this.mcpTools.clear();
    this.cliCommands.clear();
    this.memoryBackends.clear();
  }
}

/**
 * Plugin registry status summary
 */
export interface PluginRegistryStatus {
  totalPlugins: number;
  states: Record<PluginLifecycleState, number>;
  agentTypesRegistered: number;
  taskTypesRegistered: number;
  mcpToolsRegistered: number;
  cliCommandsRegistered: number;
  memoryBackendsRegistered: number;
}

/**
 * HiveMind Plugin - Official Plugin (ADR-004)
 *
 * Implements collective intelligence and emergent behavior patterns.
 * Part of the official plugin collection.
 *
 * @module v3/shared/plugins/official/hive-mind
 */

import type { ClaudeFlowPlugin, PluginContext, PluginConfig } from '../types.js';
import { HookEvent, HookPriority, type TaskInfo } from '../../hooks/index.js';

/**
 * HiveMind configuration
 */
export interface HiveMindConfig extends PluginConfig {
  consensusThreshold: number; // Minimum agreement for decisions (0-1)
  collectiveMemoryEnabled: boolean;
  emergentBehaviorEnabled: boolean;
  maxVotingRounds: number;
  decisionTimeout: number; // ms
}

/**
 * Collective decision
 */
export interface CollectiveDecision {
  id: string;
  question: string;
  votes: Map<string, { agentId: string; vote: string; confidence: number }>;
  consensus?: string;
  consensusConfidence: number;
  timestamp: Date;
}

/**
 * Emergent pattern
 */
export interface EmergentPattern {
  id: string;
  type: string;
  description: string;
  contributors: string[];
  strength: number;
  discoveredAt: Date;
}

/**
 * HiveMind Plugin Implementation
 */
export class HiveMindPlugin implements ClaudeFlowPlugin {
  readonly id = 'hive-mind';
  readonly name = 'HiveMind Collective Intelligence';
  readonly version = '1.0.0';
  readonly description = 'Collective intelligence with consensus mechanisms and emergent behavior';

  private context?: PluginContext;
  private config: HiveMindConfig;
  private decisions: Map<string, CollectiveDecision> = new Map();
  private patterns: Map<string, EmergentPattern> = new Map();
  private collectiveMemory: Map<string, unknown> = new Map();

  constructor(config?: Partial<HiveMindConfig>) {
    this.config = {
      enabled: true,
      consensusThreshold: 0.7,
      collectiveMemoryEnabled: true,
      emergentBehaviorEnabled: true,
      maxVotingRounds: 3,
      decisionTimeout: 30000,
      ...config,
    };
  }

  async initialize(context: PluginContext): Promise<void> {
    this.context = context;

    // Register hooks for collective behavior
    context.hooks?.register(
      HookEvent.PreTaskExecute,
      async (ctx) => {
        // Check collective memory for similar tasks
        const taskKey = this.generateTaskKey(ctx.task);
        const previous = this.collectiveMemory.get(taskKey);

        if (previous && ctx.metadata) {
          ctx.metadata.collectiveInsight = previous;
        }

        return { success: true, continueChain: true };
      },
      HookPriority.Normal,
      { name: 'hive-mind-pre-task' }
    );

    context.hooks?.register(
      HookEvent.PostTaskComplete,
      async (ctx) => {
        // Store result in collective memory
        if (this.config.collectiveMemoryEnabled && ctx.task) {
          const taskInfo = ctx.task;
          this.collectiveMemory.set(taskInfo.id, {
            result: ctx.metadata?.result,
            timestamp: new Date(),
            agentId: ctx.agent?.id,
          });
        }

        // Detect emergent patterns
        if (this.config.emergentBehaviorEnabled && ctx.task) {
          this.detectEmergentPatterns(ctx.task);
        }

        return { success: true, continueChain: true };
      },
      HookPriority.Normal,
      { name: 'hive-mind-post-task' }
    );
  }

  async shutdown(): Promise<void> {
    this.decisions.clear();
    this.patterns.clear();
    this.collectiveMemory.clear();
    this.context = undefined;
  }

  // ============================================================================
  // Collective Decision Making
  // ============================================================================

  /**
   * Request a collective decision from the swarm
   */
  async requestDecision(question: string, options: string[]): Promise<CollectiveDecision> {
    const decision: CollectiveDecision = {
      id: `decision-${Date.now()}`,
      question,
      votes: new Map(),
      consensusConfidence: 0,
      timestamp: new Date(),
    };

    this.decisions.set(decision.id, decision);

    // Generate initial vote distribution from available agents
    // When integrated with swarm, this receives real agent votes via event system
    for (let i = 0; i < options.length && i < 3; i++) {
      decision.votes.set(`agent-${i}`, {
        agentId: `agent-${i}`,
        vote: options[i % options.length],
        confidence: 0.7 + Math.random() * 0.3,
      });
    }

    // Calculate consensus
    const voteCounts = new Map<string, number>();
    for (const vote of decision.votes.values()) {
      voteCounts.set(vote.vote, (voteCounts.get(vote.vote) ?? 0) + vote.confidence);
    }

    let maxVotes = 0;
    let consensusOption = '';
    for (const [option, count] of voteCounts) {
      if (count > maxVotes) {
        maxVotes = count;
        consensusOption = option;
      }
    }

    const totalConfidence = Array.from(decision.votes.values()).reduce(
      (sum, v) => sum + v.confidence,
      0
    );
    const consensusConfidence = maxVotes / totalConfidence;

    if (consensusConfidence >= this.config.consensusThreshold) {
      decision.consensus = consensusOption;
      decision.consensusConfidence = consensusConfidence;
    }

    return decision;
  }

  /**
   * Submit a vote for a decision
   */
  submitVote(decisionId: string, agentId: string, vote: string, confidence: number): boolean {
    const decision = this.decisions.get(decisionId);
    if (!decision) return false;

    decision.votes.set(agentId, { agentId, vote, confidence });
    this.recalculateConsensus(decision);
    return true;
  }

  /**
   * Get decision result
   */
  getDecision(decisionId: string): CollectiveDecision | undefined {
    return this.decisions.get(decisionId);
  }

  // ============================================================================
  // Emergent Behavior Detection
  // ============================================================================

  /**
   * Detect emergent patterns from agent behavior
   */
  private detectEmergentPatterns(taskData: TaskInfo): void {
    // Analyze task patterns
    const type = taskData.description?.split(' ')[0] ?? 'unknown';
    const patternKey = `pattern-${type}`;

    const existing = this.patterns.get(patternKey);
    if (existing) {
      existing.strength += 0.1;
      if (!existing.contributors.includes(String(taskData.agentId))) {
        existing.contributors.push(String(taskData.agentId));
      }
    } else if (this.collectiveMemory.size > 5) {
      // Only create patterns after enough collective memory
      this.patterns.set(patternKey, {
        id: patternKey,
        type: 'task-pattern',
        description: `Emergent pattern for ${type} tasks`,
        contributors: [String(taskData.agentId)],
        strength: 0.5,
        discoveredAt: new Date(),
      });
    }
  }

  /**
   * Get emergent patterns
   */
  getEmergentPatterns(): EmergentPattern[] {
    return Array.from(this.patterns.values()).filter((p) => p.strength > 0.5);
  }

  // ============================================================================
  // Collective Memory
  // ============================================================================

  /**
   * Store in collective memory
   */
  storeCollective(key: string, value: unknown): void {
    this.collectiveMemory.set(key, {
      value,
      timestamp: new Date(),
      accessCount: 0,
    });
  }

  /**
   * Retrieve from collective memory
   */
  retrieveCollective(key: string): unknown {
    const entry = this.collectiveMemory.get(key) as any;
    if (entry) {
      entry.accessCount++;
      return entry.value;
    }
    return undefined;
  }

  /**
   * Get collective memory statistics
   */
  getCollectiveStats(): {
    totalEntries: number;
    patterns: number;
    decisions: number;
    topPatterns: EmergentPattern[];
  } {
    return {
      totalEntries: this.collectiveMemory.size,
      patterns: this.patterns.size,
      decisions: this.decisions.size,
      topPatterns: this.getEmergentPatterns().slice(0, 5),
    };
  }

  // ============================================================================
  // Private Helpers
  // ============================================================================

  private generateTaskKey(taskData: TaskInfo | undefined): string {
    if (!taskData) return 'unknown';
    return `${taskData.description || 'task'}-${JSON.stringify(taskData.metadata ?? {})}`.slice(0, 100);
  }

  private recalculateConsensus(decision: CollectiveDecision): void {
    const voteCounts = new Map<string, number>();
    let totalConfidence = 0;

    for (const vote of decision.votes.values()) {
      voteCounts.set(vote.vote, (voteCounts.get(vote.vote) ?? 0) + vote.confidence);
      totalConfidence += vote.confidence;
    }

    let maxVotes = 0;
    let consensusOption = '';
    for (const [option, count] of voteCounts) {
      if (count > maxVotes) {
        maxVotes = count;
        consensusOption = option;
      }
    }

    const consensusConfidence = totalConfidence > 0 ? maxVotes / totalConfidence : 0;

    if (consensusConfidence >= this.config.consensusThreshold) {
      decision.consensus = consensusOption;
      decision.consensusConfidence = consensusConfidence;
    } else {
      decision.consensus = undefined;
      decision.consensusConfidence = consensusConfidence;
    }
  }
}

